/** Genererad: Videoskolan (8 animerade videolektioner om trading), svenska källsträngar + översättningar. */
import type { VideoDef } from '../types';
export const VIDEOS: VideoDef[] = [{"id": "v1", "seed": 1, "n": 40, "a": [[0, 100], [8, 103], [12, 101], [20, 108], [24, 105], [32, 112], [36, 110], [39, 114]], "title": "Varför rör sig priset?", "desc": "Köpare, säljare och varför ljusen ser ut som de gör.", "scenes": [{"to": 5, "ov": [], "say": "Välkommen till Wickis videoskola. Jag är Wicki, och i de här videorna lär du dig det som traders faktiskt vill förstå: varför priset rör sig, när man köper, när man säljer och hur man går in i en trade. Vi börjar med den viktigaste frågan av alla: varför rör sig priset över huvud taget?"}, {"to": 7, "ov": [{"t": "bs", "b": 50}], "say": "Varje gång någon köper en aktie måste någon annan sälja den. Priset är helt enkelt den nivå där en köpare och en säljare möts just nu. Så länge båda sidor är ungefär lika starka står priset nästan still."}, {"to": 8, "ov": [{"t": "bs", "b": 72}], "say": "Men när fler vill köpa än sälja händer något. Köparna måste erbjuda ett högre pris för att någon ska vilja sälja till dem. Då stiger priset. Det är därför du ser gröna ljus staplas på varandra uppåt."}, {"to": 12, "ov": [{"t": "bs", "b": 30}], "say": "Och tvärtom. När fler vill sälja än köpa måste säljarna sänka priset för att hitta köpare. Då faller priset och du ser röda ljus. Priset rör sig alltså mot den sida där det finns minst motstånd."}, {"to": 16, "ov": [{"t": "mark", "i": 16, "at": "h", "c": "pri", "l": ["Ett ljus", "One candle", "Une bougie", "شمعة واحدة"]}], "say": "Varje ljus är en sammanfattning av striden under en viss tid, till exempel en timme. Kroppen visar var priset öppnade och stängde. Vekarna visar hur långt köpare och säljare lyckades trycka priset innan motparten tryckte tillbaka."}, {"to": 20, "ov": [{"t": "mark", "i": 17, "at": "l", "c": "gold", "l": ["Nyhet", "News", "Actualité", "خبر"]}], "say": "Varför vill folk plötsligt köpa mer? Det kan vara en bra kvartalsrapport, en räntesänkning, en nyhet om företaget eller bara att priset bryter en nivå som många tittar på. Då rusar många köpare in samtidigt och priset tar fart."}, {"to": 24, "ov": [{"t": "zone", "i0": 20, "i1": 39, "y0": 108.1, "y1": 108.9, "c": "gold", "l": ["Många ordrar", "Lots of orders", "Beaucoup d'ordres", "أوامر كثيرة"]}], "say": "Stora aktörer, som fonder och banker, handlar enorma belopp. De kan inte köpa allt på en gång utan behöver många motparter. Därför dras priset ofta mot ställen där många har ordrar liggande, till exempel strax över ett gammalt toppläge. Sådana ställen kallas likviditet."}, {"to": 32, "ov": [], "say": "Här är det viktigaste att komma ihåg: ingen vet säkert vad som händer härnäst. Inte YouTube-tradern, inte banken och inte jag. Det du kan göra är att läsa vilken sida som verkar starkast och vad som är mest sannolikt, och sedan skydda dig om du har fel."}, {"to": 39, "ov": [{"t": "mark", "i": 16, "at": "h", "c": "pri", "l": ["Ett ljus", "One candle", "Une bougie", "شمعة واحدة"]}], "say": "Låt oss gå på djupet med ett enda ljus. Säg att timmen öppnar på 100 kronor. Köparna trycker upp priset till 104, men säljarna slår tillbaka och timmen stänger på 102. Då blir kroppen grön, från 100 till 102, eftersom priset stängde högre än det öppnade. Den övre veken, från 102 till 104, visar att köparna nådde högre men inte orkade hålla kvar. En lång övre veke betyder alltså att säljarna vann slutet av striden. En lång nedre veke betyder tvärtom att köparna tog tillbaka priset från en lägre nivå. Läs därför alltid kroppen och vekarna tillsammans: kroppen visar vem som vann, vekarna visar hur hårt det var."}, {"to": 39, "ov": [], "say": "Sammanfattning: priset rör sig när köpare och säljare inte är i balans. Nyheter och stora aktörer sätter fart på rörelsen, och priset dras ofta mot likviditet. I nästa video lär du dig läsa trenden med hjälp av marknadsstruktur: toppar och bottnar."}], "quiz": [{"q": "Varför stiger priset?", "o": ["Fler vill köpa än sälja", "Fler vill sälja än köpa", "Börsen bestämmer det", "Det är slumpen, alltid"]}, {"q": "Vad visar vekarna på ett ljus?", "o": ["Hur långt priset trycktes innan det vände", "Vem som äger aktien", "Nästa dags pris", "Volymen"]}, {"q": "Vad kallas ställen där många har ordrar liggande?", "o": ["Likviditet", "Utdelning", "Courtage", "Inflation"]}]}, {"id": "v2", "seed": 2, "n": 48, "a": [[0, 100], [6, 106], [10, 103], [16, 110], [20, 106.5], [26, 114], [30, 110], [34, 113], [38, 107], [42, 109], [47, 102]], "title": "Trend och marknadsstruktur", "desc": "Toppar, bottnar, BOS och CHoCH.", "scenes": [{"to": 10, "ov": [], "say": "Priset går aldrig rakt upp eller rakt ner. Det rör sig i vågor: upp, lite tillbaka, upp igen. Om du lär dig läsa vågorna ser du vem som styr marknaden. Det kallas marknadsstruktur, och det är grunden i nästan all trading, även i ICT."}, {"to": 16, "ov": [{"t": "swings", "pts": [[6, "H", "h"], [10, "HL", "l"], [16, "HH", "h"]]}], "say": "Varje gång priset vänder bildas en topp eller en botten. När varje ny topp är högre än den förra, en Higher High, och varje ny botten är högre än den förra, en Higher Low, då är trenden uppåt. Köparna styr."}, {"to": 16, "ov": [{"t": "swings", "pts": [[6, "H", "h"], [10, "HL", "l"], [16, "HH", "h"]]}, {"t": "bos", "i0": 6, "y": 106, "c": "up", "l": ["BOS", "BOS", "BOS", "BOS"]}], "say": "Titta på stället där priset går över den förra toppen. Det kallas Break of Structure, förkortat BOS. Ett BOS i trendens riktning är ett tecken på att trenden fortsätter. Köparna orkade ta sig förbi säljarna som väntade vid den gamla toppen."}, {"to": 30, "ov": [{"t": "swings", "pts": [[6, "H", "h"], [10, "HL", "l"], [16, "HH", "h"], [20, "HL", "l"], [26, "HH", "h"], [30, "HL", "l"]]}, {"t": "bos", "i0": 16, "y": 110, "c": "up", "l": ["BOS", "BOS", "BOS", "BOS"]}], "say": "Trenden fortsätter: ny högre botten, nytt BOS, ny högre topp. Så länge det här mönstret håller är det oftast klokare att leta efter köp än att försöka gissa var toppen kommer. Att handla mot trenden är som att simma mot strömmen."}, {"to": 34, "ov": [{"t": "swings", "pts": [[16, "HH", "h"], [20, "HL", "l"], [26, "HH", "h"], [30, "HL", "l"], [34, "LH", "h"]]}], "say": "Men titta nu. Den nya toppen blev lägre än den förra. Det kallas en Lower High. Köparna orkar inte längre ta priset lika högt. Det är en första varning, men trenden är inte bruten än. Den sista högre botten håller fortfarande."}, {"to": 38, "ov": [{"t": "swings", "pts": [[26, "HH", "h"], [30, "HL", "l"], [34, "LH", "h"], [38, "LL", "l"]]}, {"t": "bos", "i0": 30, "y": 110, "c": "down", "l": ["CHoCH", "CHoCH", "CHoCH", "CHoCH"]}], "say": "Nu bryter priset under den sista högre botten. Det första brottet mot trenden kallas Change of Character, CHoCH, eller Market Structure Shift. Det betyder att säljarna har tagit över, åtminstone för tillfället. Många ICT-traders väntar på just den här signalen."}, {"to": 47, "ov": [{"t": "swings", "pts": [[34, "LH", "h"], [38, "LL", "l"], [42, "LH", "h"], [47, "LL", "l"]]}, {"t": "bos", "i0": 38, "y": 107, "c": "down", "l": ["BOS", "BOS", "BOS", "BOS"]}], "say": "Efter CHoCH ser vi lägre toppar och lägre bottnar. Nu är trenden nedåt, och ett nytt BOS nedåt bekräftar det. Samma regler gäller fast spegelvänt: i en nedåttrend letar man hellre efter blankning eller håller sig borta än köper."}, {"to": 47, "ov": [], "say": "Ett tips: titta alltid på flera tidsramar. Trenden på dagsgrafen är den stora bilden. Trenden på femminutersgrafen är bara en våg i den. Många börjar med en högre tidsram för riktningen och går ner till en lägre för att hitta exakt var de ska gå in."}, {"to": 47, "ov": [{"t": "swings", "pts": [[34, "LH", "h"], [38, "LL", "l"], [42, "LH", "h"], [47, "LL", "l"]]}, {"t": "bos", "i0": 38, "y": 107, "c": "down", "l": ["BOS", "BOS", "BOS", "BOS"]}], "say": "Fördjupning: hur vet du att ett BOS är på riktigt? Titta på var ljuset stänger, inte bara på veken. Om en veke sticker över den förra toppen men ljuset stänger under, har strukturen inte brutits. Det är ofta bara ett försök som misslyckades. Ett riktigt BOS är när ett ljus stänger över toppen, gärna med en stor kropp. Samma sak gäller CHoCH åt andra hållet: vänta på en stängning under den sista högre botten. Och välj vilka toppar och bottnar du räknar. Små svängningar inne i en större rörelse räknas inte. Börja med de tydliga vändpunkterna som du ser direkt när du zoomar ut."}, {"to": 47, "ov": [], "say": "Sammanfattning: högre toppar och högre bottnar betyder upptrend. BOS bekräftar att trenden fortsätter. CHoCH är det första tecknet på att den vänder. I nästa video tittar vi på stöd, motstånd och likviditet, alltså varför priset vänder där det vänder."}], "quiz": [{"q": "Vad kännetecknar en upptrend?", "o": ["Högre toppar och högre bottnar", "Lägre toppar och lägre bottnar", "Bara gröna ljus", "Hög volym"]}, {"q": "Vad är ett CHoCH?", "o": ["Första brottet mot trenden", "Ett brott med trenden", "En sorts ordertyp", "En nyhet"]}, {"q": "Varför titta på flera tidsramar?", "o": ["Stor bild för riktning, liten för ingång", "För att det ser proffsigt ut", "Det spelar ingen roll", "För att slippa stop-loss"]}]}, {"id": "v3", "seed": 3, "n": 46, "a": [[0, 100], [5, 104], [9, 101], [14, 108], [18, 104], [23, 108], [27, 104.3], [31, 108], [33, 109.6], [36, 105.5], [38, 104.6], [40, 103.6], [45, 99]], "title": "Stöd, motstånd och likviditet", "desc": "Varför priset vänder där det vänder, och stop hunts.", "scenes": [{"to": 18, "ov": [{"t": "h", "y": 104, "c": "up", "l": ["Stöd", "Support", "Support", "دعم"]}], "say": "Ett stöd är en nivå där priset har slutat falla och vänt upp, gärna flera gånger. Varför? För att många köpare minns nivån. De som missade köpet förra gången lägger sina köpordrar där igen. Köptrycket stoppar fallet."}, {"to": 23, "ov": [{"t": "h", "y": 104, "c": "up", "l": ["Stöd", "Support", "Support", "دعم"]}, {"t": "h", "y": 108, "c": "down", "l": ["Motstånd", "Resistance", "Résistance", "مقاومة"]}], "say": "Motstånd är samma sak fast uppåt. Det är en nivå där priset har slutat stiga. Där väntar säljare: folk som köpte högre och vill komma ut utan förlust, och folk som tycker att priset är för högt. Nu ser vi ett intervall mellan stöd och motstånd."}, {"to": 31, "ov": [{"t": "swings", "pts": [[14, "=", "h"], [23, "=", "h"], [31, "=", "h"]]}, {"t": "h", "y": 108, "c": "down", "l": ["Lika toppar", "Equal highs", "Sommets égaux", "قمم متساوية"]}], "say": "Titta på topparna. Priset har nuddat samma nivå tre gånger. Det kallas lika toppar, equal highs. För nybörjare ser det ut som ett starkt motstånd. Men proffsen ser något annat: en hög med ordrar som ligger precis ovanför."}, {"to": 31, "ov": [{"t": "zone", "i0": 14, "i1": 45, "y0": 108.2, "y1": 109.4, "c": "gold", "l": ["Likviditet: stoppar och köpordrar", "Liquidity: stops and buy orders", "Liquidité : stops et ordres d'achat", "السيولة: أوامر وقف وشراء"]}], "say": "Ovanför lika toppar ligger två sorters ordrar. Stop-loss från dem som blankat vid motståndet, och köpordrar från dem som vill köpa när priset bryter uppåt. Båda blir köp när de utlöses. Det kallas buy-side liquidity, köpsidans likviditet."}, {"to": 33, "ov": [{"t": "zone", "i0": 14, "i1": 45, "y0": 108.2, "y1": 109.4, "c": "gold", "l": ["Likviditet", "Liquidity", "Liquidité", "السيولة"]}, {"t": "mark", "i": 33, "at": "h", "c": "down", "l": ["Sweep", "Sweep", "Sweep", "سحب"]}], "say": "Och här händer det. Priset sticker upp över topparna och tar likviditeten. Alla stoppar utlöses och nya köpare hoppar på utbrottet. Det ger en stor aktör möjlighet att sälja mycket till alla dessa köpare. Det kallas en liquidity sweep eller stop hunt."}, {"to": 38, "ov": [{"t": "mark", "i": 33, "at": "h", "c": "down", "l": ["Falskt utbrott", "False breakout", "Fausse cassure", "اختراق كاذب"]}, {"t": "h", "y": 104, "c": "up", "l": ["Stöd", "Support", "Support", "دعم"]}], "say": "Direkt efteråt faller priset tillbaka in i intervallet. Utbrottet var falskt. De som köpte på toppen sitter nu med förlust. Lärdom: ett utbrott över en uppenbar nivå är inte automatiskt en köpsignal. Vänta och se om priset stannar ovanför."}, {"to": 45, "ov": [{"t": "h", "y": 104, "c": "up", "l": ["Stöd", "Support", "Support", "دعم"]}, {"t": "zone", "i0": 18, "i1": 45, "y0": 103.2, "y1": 104, "c": "pri", "l": ["Säljsidans likviditet", "Sell-side liquidity", "Liquidité côté vente", "سيولة جانب البيع"]}], "say": "Samma sak finns under bottnar. Under stödet ligger stoppar från köpare och säljordrar från dem som vill sälja vid ett brott. Det kallas sell-side liquidity. Efter att ha tagit toppen söker priset sig nu ner och tar likviditeten under stödet också."}, {"to": 45, "ov": [], "say": "Vad betyder det för dig? Lägg inte din stop-loss precis där alla andra lägger sin, exakt vid en uppenbar topp eller botten. Ge den lite luft. Och köp inte utbrott blint. Fråga dig: tar priset bara likviditet, eller bryter det på riktigt?"}, {"to": 45, "ov": [{"t": "h", "y": 104, "c": "up", "l": ["Stöd", "Support", "Support", "دعم"]}, {"t": "zone", "i0": 18, "i1": 45, "y0": 103.2, "y1": 104, "c": "pri", "l": ["Säljsidans likviditet", "Sell-side liquidity", "Liquidité côté vente", "سيولة جانب البيع"]}], "say": "Fördjupning: rita zoner, inte tunna linjer. Priset vänder sällan på exakt samma öre. Om bottnarna ligger på 103,80, 104,10 och 104,30 är stödet zonen 103,80 till 104,30, inte en linje på 104. Ju fler gånger priset testar en nivå, desto färre köpare finns kvar där, eftersom deras ordrar redan har fyllts. Därför bryts en nivå ofta på det fjärde eller femte testet. Och när ett stöd väl bryts byter det ofta roll. De som köpte där sitter med förlust och vill sälja när priset kommer tillbaka upp. Då blir det gamla stödet ett nytt motstånd."}, {"to": 45, "ov": [], "say": "Sammanfattning: stöd och motstånd är nivåer där många ordrar ligger. Lika toppar och bottnar drar till sig likviditet, och priset sveper ofta förbi dem innan det vänder. I nästa video lär du dig två ICT-begrepp som många pratar om: order blocks och fair value gaps."}], "quiz": [{"q": "Vad ligger ofta strax över lika toppar?", "o": ["Stop-loss och köpordrar", "Ingenting", "Utdelningar", "Bara säljordrar från banken"]}, {"q": "Vad är en stop hunt?", "o": ["När priset sveper förbi en nivå och tar stopparna", "När du flyttar din stop-loss", "En ny sorts aktie", "En skattefri vinst"]}, {"q": "Var är det oklokt att lägga sin stop-loss?", "o": ["Exakt vid en uppenbar topp eller botten", "Med lite luft bortom nivån", "Där idén är fel", "Enligt din plan"]}]}, {"id": "v4", "seed": 4, "n": 44, "a": [[0, 108], [6, 104], [9, 105.5], [14, 100], [15, 99.5], [19, 107], [22, 108.5], [27, 104.2], [30, 105], [34, 103.8], [38, 110], [43, 113]], "title": "Order blocks och fair value gaps", "desc": "Två ICT-begrepp, förklarade ärligt.", "scenes": [{"to": 15, "ov": [], "say": "ICT står för Inner Circle Trader. Det är ett sätt att läsa grafer som blivit väldigt populärt på YouTube och TikTok. Två av de mest kända begreppen är order blocks och fair value gaps. Jag förklarar båda, och jag är ärlig med var de fungerar och var de inte gör det."}, {"to": 19, "ov": [{"t": "bos", "i0": 9, "y": 105.5, "c": "up", "l": ["BOS", "BOS", "BOS", "BOS"]}], "say": "Titta på det här kraftiga lyftet. Priset rusar uppåt i flera stora gröna ljus och bryter strukturen. En sådan rörelse brukar kallas en impuls eller displacement. Den visar att någon stor köpte mycket och snabbt."}, {"to": 19, "ov": [{"t": "ob", "i": 15, "c": "violet", "l": ["Order block", "Order block", "Order block", "Order block"]}], "say": "Ett order block är det sista röda ljuset innan en sådan impuls uppåt. Tanken är att stora aktörer byggde sin position där, och att det kan ligga kvar ordrar på den nivån. Därför tror många att priset kan reagera om det kommer tillbaka dit."}, {"to": 19, "ov": [{"t": "fvg", "i": 17, "c": "pri", "l": ["Fair value gap", "Fair value gap", "Fair value gap", "Fair value gap"]}], "say": "Ett fair value gap ser du med tre ljus i rad. Om det första ljusets topp och det tredje ljusets botten inte överlappar finns det ett glapp mellan dem. Där handlades nästan ingenting, priset bara flög förbi. Det kallas också imbalance, obalans."}, {"to": 27, "ov": [{"t": "fvg", "i": 17, "c": "pri", "l": ["FVG", "FVG", "FVG", "FVG"]}, {"t": "ob", "i": 15, "c": "violet", "l": ["OB", "OB", "OB", "OB"]}], "say": "Efter impulsen tappar priset fart och börjar falla tillbaka. Det är helt normalt. Ingen trend går rakt upp. Frågan som ICT-traders ställer sig är: var kommer köparna in igen? Svaret de letar efter är ofta i fair value gapet eller i order blocket."}, {"to": 35, "ov": [{"t": "fvg", "i": 17, "c": "pri", "l": ["FVG", "FVG", "FVG", "FVG"]}, {"t": "mark", "i": 34, "at": "l", "c": "up", "l": ["Reaktion", "Reaction", "Réaction", "ارتداد"]}], "say": "Här kommer priset tillbaka ner in i gapet och vänder upp igen. Det kallas att gapet fylls eller att priset balanserar obalansen. För den som väntade på det här stället kunde det vara en bra plats att köpa, med stoppen under zonen."}, {"to": 43, "ov": [{"t": "fvg", "i": 17, "c": "pri", "l": ["FVG", "FVG", "FVG", "FVG"]}, {"t": "ob", "i": 15, "c": "violet", "l": ["OB", "OB", "OB", "OB"]}], "say": "Och priset fortsätter upp. Lägg märke till att det vände i gapet och aldrig nådde ner till order blocket. Det händer ofta. Därför ser många zonerna som områden, inte exakta linjer, och använder order blocket som en sista gräns där idén är fel om priset går under."}, {"to": 43, "ov": [], "say": "Nu den ärliga delen. Order blocks och fair value gaps är populära, men det finns inga starka bevis för att de fungerar bättre än andra metoder. Ibland respekterar priset zonerna, ibland skär det rakt igenom. Därför är de ledtrådar, inte löften, och du behöver alltid en stop-loss."}, {"to": 43, "ov": [{"t": "fvg", "i": 17, "c": "pri", "l": ["Fair value gap", "Fair value gap", "Fair value gap", "Fair value gap"]}], "say": "Fördjupning: så ritar du ett fair value gap exakt. Ta tre ljus i rad under ett kraftigt lyft. Säg att det första ljusets topp är 104,20 och det tredje ljusets botten är 105,00. Mellan 104,20 och 105,00 handlades nästan inget, och det är gapet. Mitten, 104,60, kallas ibland gapets jämvikt, och många tittar extra på den. Är det tredje ljusets botten lägre än det första ljusets topp finns inget gap alls. Ett order block ritar du från det sista röda ljusets botten till dess topp. Kom ihåg: de här zonerna är områden att hålla ögonen på, inte signaler att köpa blint."}, {"to": 43, "ov": [], "say": "Sammanfattning: ett order block är sista motsatta ljuset före en stark impuls. Ett fair value gap är ett glapp mellan ljus ett och tre. Båda är zoner där priset ibland reagerar. I nästa video sätter vi ihop allt: när ska man köpa och när ska man sälja?"}], "quiz": [{"q": "Vad är ett order block i en upptrend?", "o": ["Sista röda ljuset före en stark impuls uppåt", "Första gröna ljuset på dagen", "En spärrad aktie", "Ett stort köp från dig"]}, {"q": "Hur hittar du ett fair value gap?", "o": ["Ljus ett och tre överlappar inte", "Två röda ljus i rad", "Börsen är stängd", "Ett ljus utan veke"]}, {"q": "Fungerar order blocks och FVG alltid?", "o": ["Nej, de är ledtrådar och kräver stop-loss", "Ja, alltid", "Ja, om man har många följare", "Ja, på fredagar"]}]}, {"id": "v5", "seed": 5, "n": 46, "a": [[0, 100], [8, 106], [13, 103], [20, 111], [27, 105.5], [29, 105], [31, 106.6], [38, 112], [45, 115]], "title": "När ska man köpa och sälja?", "desc": "Riktning, zon och bekräftelse, steg för steg.", "scenes": [{"to": 20, "ov": [], "say": "Det här är frågan alla vill ha svar på: när ska jag köpa och när ska jag sälja? Det finns inget magiskt svar, men det finns ett sätt att tänka som de flesta seriösa traders använder. Jag kallar det tre steg: riktning, zon och bekräftelse."}, {"to": 20, "ov": [{"t": "swings", "pts": [[8, "HH", "h"], [13, "HL", "l"], [20, "HH", "h"]]}], "say": "Steg ett: riktning. Vilket håll går trenden åt? Här ser vi högre toppar och högre bottnar, alltså en upptrend. Då letar vi bara efter köp. Vi försöker inte gissa toppen. Det enklaste sättet att förlora pengar är att slåss mot trenden."}, {"to": 24, "ov": [{"t": "range", "i0": 13, "y0": 103, "y1": 111, "l": ["Premium", "Premium", "Premium", "Premium"], "l2": ["Discount", "Discount", "Discount", "Discount"]}], "say": "Steg två: zon. Köp inte när priset just har rusat upp, då köper du dyrt. Vänta på en rekyl. Dra en linje mitt i den senaste rörelsen, från botten till toppen. Under mitten är priset billigt, discount. Över mitten är det dyrt, premium. Vi vill köpa i discount."}, {"to": 29, "ov": [{"t": "range", "i0": 13, "y0": 103, "y1": 111, "l": ["Premium", "Premium", "Premium", "Premium"], "l2": ["Discount", "Discount", "Discount", "Discount"]}, {"t": "h", "y": 106, "c": "up", "l": ["Gammalt motstånd blir stöd", "Old resistance becomes support", "L'ancienne résistance devient support", "المقاومة القديمة تصبح دعمًا"]}], "say": "Nu är priset i discount och dessutom vid en nivå som tidigare var motstånd. Gammalt motstånd blir ofta nytt stöd. Det här är en bra zon. Men att priset är i en bra zon räcker inte. Det kan fortsätta falla rakt igenom."}, {"to": 31, "ov": [{"t": "h", "y": 106, "c": "up", "l": ["Stöd", "Support", "Support", "دعم"]}, {"t": "mark", "i": 31, "at": "l", "c": "up", "l": ["Bekräftelse", "Confirmation", "Confirmation", "تأكيد"]}], "say": "Steg tre: bekräftelse. Vänta tills köparna visar att de är tillbaka. Det kan vara ett starkt grönt ljus som stänger högt, en hammare, eller ett litet CHoCH uppåt på en lägre tidsram. Först nu har vi en anledning att köpa."}, {"to": 31, "ov": [{"t": "trade", "i0": 31, "i1": 45, "e": 106.6, "s": 104.4, "tp": 111.2}], "say": "Så här ser köpet ut. Ingång strax efter bekräftelsen. Stop-loss under botten i zonen, med lite luft, för om priset går dit var idén fel. Mål vid den gamla toppen, där köpsidans likviditet ligger. Planen är klar innan vi klickar."}, {"to": 38, "ov": [{"t": "trade", "i0": 31, "i1": 45, "e": 106.6, "s": 104.4, "tp": 111.2}], "say": "När ska man sälja? På två ställen som du bestämt i förväg. Antingen når priset målet, och du tar vinsten. Eller så når det stoppen, och du tar en liten förlust. Du säljer inte för att du blir nervös, och du flyttar aldrig ner stoppen."}, {"to": 45, "ov": [], "say": "Och när ska man inte handla alls? När trenden är otydlig. När priset är mitt i ingenstans, varken i en zon eller vid en nivå. Precis innan stora nyheter. Och när du är trött, arg eller vill vinna tillbaka en förlust. Att avstå är också ett beslut."}, {"to": 45, "ov": [{"t": "range", "i0": 13, "y0": 103, "y1": 111, "l": ["Premium", "Premium", "Premium", "Premium"], "l2": ["Discount", "Discount", "Discount", "Discount"]}], "say": "Fördjupning: så räknar du premium och discount. Ta den senaste rörelsen från botten till toppen. Här gick priset från 103 till 111. Skillnaden är 8 kronor, och mitten ligger 4 kronor upp, på 107. Allt över 107 är premium, dyrt. Allt under 107 är discount, billigt. I en upptrend vill du köpa i discount, helst där det också finns ett gammalt motstånd som kan bli stöd, som här runt 106. Mitten är ingen magisk linje. Den hjälper dig bara att undvika att köpa på toppen av en rörelse. Gör toppen ny behöver du räkna om mitten."}, {"to": 45, "ov": [], "say": "Sammanfattning: riktning först, sedan en bra zon, sedan bekräftelse. Bestäm ingång, stopp och mål innan du klickar. Sälj vid målet eller stoppen, inte på känsla. I nästa video räknar vi på en trade: hur stor ska den vara och vad händer med pengarna?"}], "quiz": [{"q": "Vilka är de tre stegen?", "o": ["Riktning, zon, bekräftelse", "Köp, sälj, köp igen", "Nyhet, hype, köp", "Gissa, hoppas, vänta"]}, {"q": "I en upptrend, var vill man helst köpa?", "o": ["I discount, efter en rekyl", "På toppen efter ett rusning", "Var som helst", "När någon på TikTok säger det"]}, {"q": "När säljer du enligt planen?", "o": ["Vid målet eller stoppen", "När du blir nervös", "Aldrig", "När en vän säljer"]}]}, {"id": "v6", "seed": 6, "n": 44, "a": [[0, 100], [10, 104], [16, 101.5], [24, 107], [30, 104], [33, 103.6], [35, 105], [43, 109.4]], "title": "Gå in i en trade", "desc": "Ingång, stopp, mål, risk/belöning och positionsstorlek.", "scenes": [{"to": 30, "ov": [], "say": "Du har hittat ett läge. Nu kommer delen som avgör om du överlever som trader: hur du går in i traden. De flesta nybörjare tänker bara på var de ska köpa. Proffs tänker först på hur mycket de kan förlora."}, {"to": 35, "ov": [{"t": "mark", "i": 35, "at": "l", "c": "up", "l": ["Ingång 105", "Entry 105", "Entrée 105", "دخول 105"]}], "say": "Ingången. Du kan köpa direkt till marknadspris med en marknadsorder. Eller lägga en limitorder på det pris du vill ha och vänta. Limit ger bättre pris men du kan missa traden. Här köper vi på 105 kronor när bekräftelsen kommer."}, {"to": 35, "ov": [{"t": "trade", "i0": 35, "i1": 43, "e": 105, "s": 103, "tp": 0}], "say": "Stop-lossen. Den ska ligga där din idé är fel, inte där det känns bekvämt. Vår idé är att stödet håller. Om priset går under botten vid 103,60 har vi fel. Vi lägger stoppen på 103 kronor, med lite luft. Risken per aktie blir 2 kronor."}, {"to": 35, "ov": [{"t": "trade", "i0": 35, "i1": 43, "e": 105, "s": 103, "tp": 109}], "say": "Målet. Vi siktar på 109 kronor, strax under den gamla toppen. Vinsten per aktie blir då 4 kronor. Vi riskerar alltså 2 för att kunna tjäna 4. Det kallas risk/belöning ett till två. Med ett till två kan du ha fel oftare än rätt och ändå gå plus."}, {"to": 35, "ov": [{"t": "trade", "i0": 35, "i1": 43, "e": 105, "s": 103, "tp": 109}], "say": "Räkna så här. Tio trades med ett till två. Du har rätt fyra gånger och fel sex gånger. Fyra vinster gånger 4 kronor blir 16. Sex förluster gånger 2 kronor blir 12. Du har ändå tjänat 4 kronor per aktie, trots att du hade fel oftast."}, {"to": 35, "ov": [{"t": "trade", "i0": 35, "i1": 43, "e": 105, "s": 103, "tp": 109}], "say": "Positionsstorlek. Bestäm hur mycket av kontot du får förlora på en trade, till exempel 1 procent. Har du 10 000 kronor är det 100 kronor. Risken per aktie är 2 kronor. 100 delat med 2 blir 50 aktier. Det är hela regeln: risk i kronor delat med risk per aktie."}, {"to": 43, "ov": [{"t": "trade", "i0": 35, "i1": 43, "e": 105, "s": 103, "tp": 109}], "say": "Och traden går vår väg. Priset når målet och vi säljer 50 aktier med 4 kronors vinst, alltså 200 kronor. Om stoppen hade slagits ut hade vi förlorat 100 kronor, bara 1 procent av kontot. Med den regeln kan du ha flera förluster i rad utan att kontot försvinner."}, {"to": 43, "ov": [{"t": "trade", "i0": 35, "i1": 43, "e": 105, "s": 103, "tp": 109}], "say": "Fördjupning: positionsstorlek steg för steg. Ditt konto är 10 000 kronor och du riskerar 1 procent, alltså 100 kronor. Ingången är 105 och stoppen 103, så avståndet är 2 kronor per aktie. 100 delat med 2 är 50. Du köper alltså 50 aktier, värda 5 250 kronor. Om stoppen slås ut förlorar du 100 kronor plus courtage, inte mer. Lägg märke till att det är stoppens avstånd som bestämmer antalet aktier, inte hur säker du känner dig. Ligger stoppen längre bort köper du färre aktier, så att risken i kronor blir densamma varje gång."}, {"to": 43, "ov": [], "say": "Sammanfattning: stoppen ligger där idén är fel. Målet ger minst dubbelt så mycket som risken. Positionsstorleken räknar du fram så att en förlust bara kostar 1 procent. I sista videon följer vi två hela trades från början till slut, en vinst och en förlust."}], "quiz": [{"q": "Ingång 105, stopp 103, mål 109. Vad är risk/belöning?", "o": ["1 till 2", "1 till 1", "2 till 1", "1 till 4"]}, {"q": "Konto 10 000 kr, risk 1 %, risk per aktie 2 kr. Hur många aktier?", "o": ["50", "100", "10", "500"]}, {"q": "Var ska stop-lossen ligga?", "o": ["Där idén är fel", "Där det känns bekvämt", "Ingenstans", "Precis på köppriset"]}]}, {"id": "v7", "seed": 7, "n": 56, "a": [[0, 100], [7, 105], [11, 102.5], [18, 109], [23, 105.5], [25, 105.2], [30, 111.5], [34, 113], [38, 109.8], [41, 110.6], [44, 108.2], [50, 104], [55, 106]], "title": "En hel trade från början till slut", "desc": "En vinst, en förlust och vad du lär dig av båda.", "scenes": [{"to": 18, "ov": [{"t": "swings", "pts": [[7, "HH", "h"], [11, "HL", "l"], [18, "HH", "h"]]}], "say": "I den här sista videon gör vi allt i ordning, som en riktig trader. Först riktningen. Dagsgrafen visar högre toppar och högre bottnar. Trenden är upp, så vi letar bara efter köp. Vi skriver ner det i tradingdagboken innan vi gör något annat."}, {"to": 25, "ov": [{"t": "range", "i0": 11, "y0": 102.5, "y1": 109, "l": ["Premium", "Premium", "Premium", "Premium"], "l2": ["Discount", "Discount", "Discount", "Discount"]}], "say": "Sedan zonen. Priset rekylerar ner i discount, under mitten av den senaste rörelsen, och når området runt 105 där det tidigare var motstånd. Vi gör ingenting än. Vi väntar på att köparna ska visa sig."}, {"to": 26, "ov": [{"t": "trade", "i0": 26, "i1": 34, "e": 106.6, "s": 104.6, "tp": 110.8}], "say": "Bekräftelse: två starka gröna ljus. Nu planerar vi. Ingång 106,60. Stopp 104,60 under botten. Mål 110,80 vid den gamla toppen. Risk 2 kronor, möjlig vinst drygt 4. Kontot är 10 000 kronor och vi riskerar 1 procent, alltså 50 aktier."}, {"to": 31, "ov": [{"t": "trade", "i0": 26, "i1": 34, "e": 106.6, "s": 104.6, "tp": 110.8}, {"t": "mark", "i": 30, "at": "h", "c": "up", "l": ["Mål nått +210 kr", "Target hit +210 kr", "Objectif atteint +210 couronnes", "تحقق الهدف ‎+210 كرونة"]}], "say": "Priset stiger och når målet. Vi säljer och tar vinsten, ungefär 210 kronor. Vi flyttade inte målet för att det kändes som att det kunde gå högre. Planen sa sälj, så vi sålde. Det låter tråkigt, men det är så man håller sig vid liv länge."}, {"to": 41, "ov": [{"t": "h", "y": 110, "c": "up", "l": ["Stöd?", "Support?", "Support ?", "دعم؟"]}, {"t": "trade", "i0": 41, "i1": 55, "e": 110.6, "s": 109.4, "tp": 113}], "say": "Nu en andra trade. Priset faller tillbaka till ungefär 110, den gamla toppen. Vi tror att den blir stöd. Ingång 110,60, stopp 109,40, mål 113. Lägg märke till att bekräftelsen var svagare den här gången. Det är vanligt att man ändå går in."}, {"to": 45, "ov": [{"t": "trade", "i0": 41, "i1": 55, "e": 110.6, "s": 109.4, "tp": 113}, {"t": "mark", "i": 44, "at": "l", "c": "down", "l": ["Stopp −100 kr", "Stopped −100 kr", "Stop −100 couronnes", "وقف ‎−100 كرونة"]}], "say": "Priset faller rakt igenom stödet och slår ut stoppen. Vi förlorar 100 kronor, exakt 1 procent som planerat. Det gör ont, men det är en liten skada. Om vi inte hade haft en stopp hade priset tagit med sig mycket mer."}, {"to": 55, "ov": [{"t": "swings", "pts": [[34, "HH", "h"], [38, "HL", "l"], [41, "LH", "h"], [44, "LL", "l"]]}], "say": "Titta vad som hände sen. Priset fortsatte ner mot 104. Strukturen gav en varning: en lägre topp och sedan ett brott under den sista högre botten, ett CHoCH. Det här är vad dagboken är till för. Vi skriver: gick in trots svag bekräftelse och en lägre topp."}, {"to": 55, "ov": [], "say": "Resultat: en vinst på 210 och en förlust på 100. Totalt plus 110 kronor, trots att hälften av traderna var fel. Det är så trading fungerar: inte att ha rätt hela tiden, utan att förlora lite när man har fel och vinna mer när man har rätt."}, {"to": 55, "ov": [], "say": "Fördjupning: skriv en tradingdagbok. Efter varje trade antecknar du fem saker. Ett: varför du gick in, med en mening. Två: ingång, stopp och mål. Tre: resultatet i kronor och i R, alltså hur många gånger risken du vann eller förlorade. Vår första trade blev ungefär plus 2 R, den andra minus 1 R. Fyra: följde du planen, ja eller nej? Fem: hur kändes det? Efter tjugo trades läser du dagboken. Då ser du mönster du aldrig märker i stunden, till exempel att dina förluster nästan alltid kommer när du bröt mot planen."}, {"to": 55, "ov": [], "say": "Till sist, ärligt: de flesta som daytradar förlorar pengar, särskilt med hävstång. Öva därför först i Wickis handelssimulator med låtsaspengar. Skriv dagbok. Använd bara pengar du har råd att förlora. Och kom ihåg: Wicki lär ut kunskap, inte investeringsråd. Lycka till, och vi ses i nästa lektion!"}], "quiz": [{"q": "En vinst på 210 kr och en förlust på 100 kr. Vad blir resultatet?", "o": ["+110 kr", "−110 kr", "+310 kr", "0 kr"]}, {"q": "Vad var varningen före den förlorande traden?", "o": ["En lägre topp och svag bekräftelse", "Ett starkt grönt ljus", "En högre botten", "Ingenting"]}, {"q": "Var är det klokt att öva först?", "o": ["I en simulator med låtsaspengar", "Med lånade pengar", "Med hela sparkontot", "Med hävstång"]}]}, {"id": "v8", "seed": 8, "n": 44, "a": [[0, 100], [10, 103], [16, 110], [18, 112], [20, 108], [24, 104.5], [28, 106], [32, 103], [36, 101.5], [43, 104]], "title": "Vanliga nybörjarmisstag", "desc": "FOMO, ingen stopp, hämndtrading och för stora positioner.", "scenes": [{"to": 10, "ov": [], "say": "Den här bonusvideon handlar om misstagen nästan alla nybörjare gör. De flesta förlorar inte pengar för att de inte kan läsa en graf. De förlorar för att de bryter sina egna regler när känslorna tar över. Låt oss gå igenom de vanligaste, så att du känner igen dem."}, {"to": 18, "ov": [{"t": "mark", "i": 18, "at": "h", "c": "down", "l": ["Köpte här (FOMO)", "Bought here (FOMO)", "Acheté ici (FOMO)", "اشترى هنا (FOMO)"]}], "say": "Misstag ett: att jaga priset. Aktien har stigit i flera dagar, alla pratar om den och du är rädd att missa. Du köper på toppen, efter att rörelsen redan har hänt. Det är FOMO, och det är ofta precis där de tidiga köparna säljer till dig."}, {"to": 24, "ov": [{"t": "mark", "i": 18, "at": "h", "c": "down", "l": ["Köp 112", "Buy 112", "Achat 112", "شراء 112"]}, {"t": "mark", "i": 24, "at": "l", "c": "down", "l": ["−7 %", "−7%", "−7 %", "‎−7٪"]}], "say": "Misstag två: ingen stop-loss. Priset faller och du tänker att det kommer tillbaka. Det faller mer. Nu är förlusten så stor att det känns omöjligt att sälja. Utan stopp kan en liten förlust växa till en stor. Bestäm alltid stoppen innan du köper."}, {"to": 28, "ov": [], "say": "Misstag tre: att flytta stoppen. Priset närmar sig din stopp och du flyttar ner den lite, sedan lite till. Det är samma sak som att inte ha någon stopp alls. Stoppen var planen när du var lugn. Lita på den, inte på känslan i stunden."}, {"to": 32, "ov": [], "say": "Misstag fyra: hämndtrading. Efter en förlust vill du vinna tillbaka pengarna direkt. Du tar nästa trade utan ett riktigt läge, kanske med dubbelt så stor position. Det slutar ofta med en ännu större förlust. Efter två förluster i rad: ta en paus."}, {"to": 36, "ov": [], "say": "Misstag fem: för stora positioner. Om du riskerar 20 procent av kontot på en trade räcker det med fem förluster för att allt är borta. Med 1 procent kan du ha tjugo förluster i rad och fortfarande ha det mesta kvar. Små positioner håller dig kvar i spelet."}, {"to": 40, "ov": [], "say": "Misstag sex: att handla för ofta. Det finns inte ett bra läge varje timme. Varje affär kostar courtage och varje snabbt beslut ökar risken för fel. De bästa traders väntar mycket och handlar lite. Tålamod är en del av strategin."}, {"to": 43, "ov": [], "say": "Misstag sju: att tro på den som säljer drömmen. Kurser och signalgrupper som lovar snabba, säkra vinster tjänar oftast mer på dig än på trading. Ingen seriös person lovar säker vinst. Lär dig grunderna själv, som du gör nu, och var skeptisk."}, {"to": 43, "ov": [], "say": "Fördjupning: en checklista före varje trade. Läs den högt innan du klickar. Ett: vilken är trenden på den högre tidsramen? Två: är priset i en zon jag planerat, eller jagar jag? Tre: har jag sett en bekräftelse? Fyra: var ligger stoppen, och är den där idén är fel? Fem: är målet minst dubbelt så långt bort som stoppen? Sex: hur många aktier ger 1 procents risk? Sju: är jag lugn, eller vill jag vinna tillbaka något? Om svaret på någon fråga är fel eller osäkert, låt bli. Det kostar ingenting att avstå från en trade."}, {"to": 43, "ov": [], "say": "Sammanfattning: köp inte på FOMO, ha alltid en stopp och flytta den inte, ta paus efter förluster, riskera lite per trade, handla mindre och var skeptisk mot drömförsäljare. Om du undviker de här sju misstagen ligger du redan före de flesta nybörjare."}], "quiz": [{"q": "Vad är FOMO i trading?", "o": ["Att köpa sent av rädsla att missa", "En säker strategi", "En typ av order", "Att ta en paus"]}, {"q": "Vad bör du göra efter två förluster i rad?", "o": ["Ta en paus", "Dubbla positionen", "Ta bort stoppen", "Köpa en kurs"]}, {"q": "Hur många förluster i rad tål du med 20 % risk per trade?", "o": ["Ungefär fem", "Hundra", "Tjugo", "Oändligt många"]}]}];
export const VDICT: Record<string, Record<string, string>> = {"en": {"Varför rör sig priset?": "Why does the price move?", "Köpare, säljare och varför ljusen ser ut som de gör.": "Buyers, sellers and why candles look the way they do.", "Välkommen till Wickis videoskola. Jag är Wicki, och i de här videorna lär du dig det som traders faktiskt vill förstå: varför priset rör sig, när man köper, när man säljer och hur man går in i en trade. Vi börjar med den viktigaste frågan av alla: varför rör sig priset över huvud taget?": "Welcome to Wicki's video school. I'm Wicki, and in these videos you'll learn what traders actually want to understand: why the price moves, when to buy, when to sell and how to enter a trade. We start with the most important question of all: why does the price move at all?", "Varje gång någon köper en aktie måste någon annan sälja den. Priset är helt enkelt den nivå där en köpare och en säljare möts just nu. Så länge båda sidor är ungefär lika starka står priset nästan still.": "Every time someone buys a share, someone else has to sell it. The price is simply the level where a buyer and a seller meet right now. As long as both sides are about equally strong, the price barely moves.", "Men när fler vill köpa än sälja händer något. Köparna måste erbjuda ett högre pris för att någon ska vilja sälja till dem. Då stiger priset. Det är därför du ser gröna ljus staplas på varandra uppåt.": "But when more people want to buy than sell, something happens. Buyers have to offer a higher price to get anyone to sell to them. So the price rises. That's why you see green candles stacking upwards.", "Och tvärtom. När fler vill sälja än köpa måste säljarna sänka priset för att hitta köpare. Då faller priset och du ser röda ljus. Priset rör sig alltså mot den sida där det finns minst motstånd.": "And the other way round. When more people want to sell than buy, sellers have to lower the price to find buyers. So the price falls and you see red candles. In other words, price moves towards the side with the least resistance.", "Varje ljus är en sammanfattning av striden under en viss tid, till exempel en timme. Kroppen visar var priset öppnade och stängde. Vekarna visar hur långt köpare och säljare lyckades trycka priset innan motparten tryckte tillbaka.": "Every candle is a summary of the fight over a certain time, for example one hour. The body shows where the price opened and closed. The wicks show how far buyers and sellers managed to push before the other side pushed back.", "Varför vill folk plötsligt köpa mer? Det kan vara en bra kvartalsrapport, en räntesänkning, en nyhet om företaget eller bara att priset bryter en nivå som många tittar på. Då rusar många köpare in samtidigt och priset tar fart.": "Why do people suddenly want to buy more? It could be a strong quarterly report, an interest rate cut, company news or simply the price breaking a level that many people are watching. Then lots of buyers rush in at once and the price speeds up.", "Stora aktörer, som fonder och banker, handlar enorma belopp. De kan inte köpa allt på en gång utan behöver många motparter. Därför dras priset ofta mot ställen där många har ordrar liggande, till exempel strax över ett gammalt toppläge. Sådana ställen kallas likviditet.": "Big players, like funds and banks, trade huge amounts. They can't buy everything at once and need lots of counterparties. That's why price is often drawn to places where many people have orders waiting, for example just above an old high. Those places are called liquidity.", "Här är det viktigaste att komma ihåg: ingen vet säkert vad som händer härnäst. Inte YouTube-tradern, inte banken och inte jag. Det du kan göra är att läsa vilken sida som verkar starkast och vad som är mest sannolikt, och sedan skydda dig om du har fel.": "Here's the most important thing to remember: no one knows for sure what happens next. Not the YouTube trader, not the bank and not me. What you can do is read which side looks strongest and what is most likely, and then protect yourself if you're wrong.", "Låt oss gå på djupet med ett enda ljus. Säg att timmen öppnar på 100 kronor. Köparna trycker upp priset till 104, men säljarna slår tillbaka och timmen stänger på 102. Då blir kroppen grön, från 100 till 102, eftersom priset stängde högre än det öppnade. Den övre veken, från 102 till 104, visar att köparna nådde högre men inte orkade hålla kvar. En lång övre veke betyder alltså att säljarna vann slutet av striden. En lång nedre veke betyder tvärtom att köparna tog tillbaka priset från en lägre nivå. Läs därför alltid kroppen och vekarna tillsammans: kroppen visar vem som vann, vekarna visar hur hårt det var.": "Let's go deep on a single candle. Say the hour opens at 100 kronor. Buyers push the price up to 104, but sellers fight back and the hour closes at 102. The body is green, from 100 to 102, because price closed higher than it opened. The upper wick, from 102 to 104, shows that buyers reached higher but couldn't hold it. So a long upper wick means sellers won the end of the fight. A long lower wick means the opposite: buyers pulled price back up from a lower level. Always read the body and the wicks together: the body shows who won, the wicks show how hard it was.", "Sammanfattning: priset rör sig när köpare och säljare inte är i balans. Nyheter och stora aktörer sätter fart på rörelsen, och priset dras ofta mot likviditet. I nästa video lär du dig läsa trenden med hjälp av marknadsstruktur: toppar och bottnar.": "Summary: price moves when buyers and sellers are out of balance. News and big players speed up the move, and price is often drawn towards liquidity. In the next video you'll learn to read the trend using market structure: highs and lows.", "Varför stiger priset?": "Why does the price rise?", "Fler vill köpa än sälja": "More people want to buy than sell", "Fler vill sälja än köpa": "More people want to sell than buy", "Börsen bestämmer det": "The stock exchange decides", "Det är slumpen, alltid": "It's always random", "Vad visar vekarna på ett ljus?": "What do a candle's wicks show?", "Hur långt priset trycktes innan det vände": "How far price was pushed before it turned", "Vem som äger aktien": "Who owns the share", "Nästa dags pris": "Tomorrow's price", "Volymen": "The volume", "Vad kallas ställen där många har ordrar liggande?": "What are places where many orders are waiting called?", "Likviditet": "Liquidity", "Utdelning": "Dividend", "Courtage": "Brokerage", "Inflation": "Inflation", "Trend och marknadsstruktur": "Trend and market structure", "Toppar, bottnar, BOS och CHoCH.": "Highs, lows, BOS and CHoCH.", "Priset går aldrig rakt upp eller rakt ner. Det rör sig i vågor: upp, lite tillbaka, upp igen. Om du lär dig läsa vågorna ser du vem som styr marknaden. Det kallas marknadsstruktur, och det är grunden i nästan all trading, även i ICT.": "Price never goes straight up or straight down. It moves in waves: up, a little back, up again. If you learn to read the waves, you can see who is in control of the market. This is called market structure, and it's the foundation of almost all trading, including ICT.", "Varje gång priset vänder bildas en topp eller en botten. När varje ny topp är högre än den förra, en Higher High, och varje ny botten är högre än den förra, en Higher Low, då är trenden uppåt. Köparna styr.": "Every time price turns, a high or a low is formed. When each new high is higher than the last, a Higher High, and each new low is higher than the last, a Higher Low, the trend is up. Buyers are in control.", "Titta på stället där priset går över den förra toppen. Det kallas Break of Structure, förkortat BOS. Ett BOS i trendens riktning är ett tecken på att trenden fortsätter. Köparna orkade ta sig förbi säljarna som väntade vid den gamla toppen.": "Look at the spot where price goes above the previous high. That's called a Break of Structure, or BOS. A BOS in the direction of the trend is a sign that the trend continues. The buyers managed to get past the sellers waiting at the old high.", "Trenden fortsätter: ny högre botten, nytt BOS, ny högre topp. Så länge det här mönstret håller är det oftast klokare att leta efter köp än att försöka gissa var toppen kommer. Att handla mot trenden är som att simma mot strömmen.": "The trend continues: new higher low, new BOS, new higher high. As long as this pattern holds, it's usually wiser to look for buys than to try to guess where the top will be. Trading against the trend is like swimming against the current.", "Men titta nu. Den nya toppen blev lägre än den förra. Det kallas en Lower High. Köparna orkar inte längre ta priset lika högt. Det är en första varning, men trenden är inte bruten än. Den sista högre botten håller fortfarande.": "But look now. The new high is lower than the previous one. That's called a Lower High. Buyers can no longer push the price as high. It's a first warning, but the trend isn't broken yet. The last higher low is still holding.", "Nu bryter priset under den sista högre botten. Det första brottet mot trenden kallas Change of Character, CHoCH, eller Market Structure Shift. Det betyder att säljarna har tagit över, åtminstone för tillfället. Många ICT-traders väntar på just den här signalen.": "Now price breaks below the last higher low. The first break against the trend is called a Change of Character, CHoCH, or a Market Structure Shift. It means sellers have taken over, at least for now. Many ICT traders wait for exactly this signal.", "Efter CHoCH ser vi lägre toppar och lägre bottnar. Nu är trenden nedåt, och ett nytt BOS nedåt bekräftar det. Samma regler gäller fast spegelvänt: i en nedåttrend letar man hellre efter blankning eller håller sig borta än köper.": "After the CHoCH we see lower highs and lower lows. Now the trend is down, and a new BOS downwards confirms it. The same rules apply, just mirrored: in a downtrend you'd rather look for shorts or stay out than buy.", "Ett tips: titta alltid på flera tidsramar. Trenden på dagsgrafen är den stora bilden. Trenden på femminutersgrafen är bara en våg i den. Många börjar med en högre tidsram för riktningen och går ner till en lägre för att hitta exakt var de ska gå in.": "A tip: always look at several timeframes. The trend on the daily chart is the big picture. The trend on the five-minute chart is just one wave inside it. Many traders start with a higher timeframe for direction and go down to a lower one to find exactly where to enter.", "Fördjupning: hur vet du att ett BOS är på riktigt? Titta på var ljuset stänger, inte bara på veken. Om en veke sticker över den förra toppen men ljuset stänger under, har strukturen inte brutits. Det är ofta bara ett försök som misslyckades. Ett riktigt BOS är när ett ljus stänger över toppen, gärna med en stor kropp. Samma sak gäller CHoCH åt andra hållet: vänta på en stängning under den sista högre botten. Och välj vilka toppar och bottnar du räknar. Små svängningar inne i en större rörelse räknas inte. Börja med de tydliga vändpunkterna som du ser direkt när du zoomar ut.": "Deep dive: how do you know a BOS is real? Look at where the candle closes, not just the wick. If a wick pokes above the previous high but the candle closes below it, structure hasn't broken. That's often just a failed attempt. A real BOS is when a candle closes above the high, ideally with a big body. The same goes for a CHoCH the other way: wait for a close below the last higher low. And choose which highs and lows you count. Small wiggles inside a bigger move don't count. Start with the clear turning points you see straight away when you zoom out.", "Sammanfattning: högre toppar och högre bottnar betyder upptrend. BOS bekräftar att trenden fortsätter. CHoCH är det första tecknet på att den vänder. I nästa video tittar vi på stöd, motstånd och likviditet, alltså varför priset vänder där det vänder.": "Summary: higher highs and higher lows mean an uptrend. A BOS confirms the trend continues. A CHoCH is the first sign it's turning. In the next video we look at support, resistance and liquidity, in other words why price turns where it turns.", "Vad kännetecknar en upptrend?": "What defines an uptrend?", "Högre toppar och högre bottnar": "Higher highs and higher lows", "Lägre toppar och lägre bottnar": "Lower highs and lower lows", "Bara gröna ljus": "Only green candles", "Hög volym": "High volume", "Vad är ett CHoCH?": "What is a CHoCH?", "Första brottet mot trenden": "The first break against the trend", "Ett brott med trenden": "A break with the trend", "En sorts ordertyp": "A type of order", "En nyhet": "A piece of news", "Varför titta på flera tidsramar?": "Why look at several timeframes?", "Stor bild för riktning, liten för ingång": "Big picture for direction, small for entry", "För att det ser proffsigt ut": "Because it looks professional", "Det spelar ingen roll": "It doesn't matter", "För att slippa stop-loss": "To avoid a stop-loss", "Stöd, motstånd och likviditet": "Support, resistance and liquidity", "Varför priset vänder där det vänder, och stop hunts.": "Why price turns where it does, and stop hunts.", "Ett stöd är en nivå där priset har slutat falla och vänt upp, gärna flera gånger. Varför? För att många köpare minns nivån. De som missade köpet förra gången lägger sina köpordrar där igen. Köptrycket stoppar fallet.": "A support is a level where price has stopped falling and turned up, ideally several times. Why? Because many buyers remember the level. Those who missed the buy last time place their buy orders there again. The buying pressure stops the fall.", "Motstånd är samma sak fast uppåt. Det är en nivå där priset har slutat stiga. Där väntar säljare: folk som köpte högre och vill komma ut utan förlust, och folk som tycker att priset är för högt. Nu ser vi ett intervall mellan stöd och motstånd.": "Resistance is the same thing upwards. It's a level where price has stopped rising. Sellers wait there: people who bought higher and want out without a loss, and people who think the price is too high. Now we see a range between support and resistance.", "Titta på topparna. Priset har nuddat samma nivå tre gånger. Det kallas lika toppar, equal highs. För nybörjare ser det ut som ett starkt motstånd. Men proffsen ser något annat: en hög med ordrar som ligger precis ovanför.": "Look at the highs. Price has touched the same level three times. Those are called equal highs. To beginners it looks like strong resistance. But professionals see something else: a pile of orders sitting just above.", "Ovanför lika toppar ligger två sorters ordrar. Stop-loss från dem som blankat vid motståndet, och köpordrar från dem som vill köpa när priset bryter uppåt. Båda blir köp när de utlöses. Det kallas buy-side liquidity, köpsidans likviditet.": "Above equal highs there are two kinds of orders. Stop-losses from people who shorted at resistance, and buy orders from people who want to buy when price breaks out. Both become buys when triggered. This is called buy-side liquidity.", "Och här händer det. Priset sticker upp över topparna och tar likviditeten. Alla stoppar utlöses och nya köpare hoppar på utbrottet. Det ger en stor aktör möjlighet att sälja mycket till alla dessa köpare. Det kallas en liquidity sweep eller stop hunt.": "And here it happens. Price spikes above the highs and takes the liquidity. All the stops trigger and new buyers jump on the breakout. That gives a big player the chance to sell a lot to all those buyers. This is called a liquidity sweep or a stop hunt.", "Direkt efteråt faller priset tillbaka in i intervallet. Utbrottet var falskt. De som köpte på toppen sitter nu med förlust. Lärdom: ett utbrott över en uppenbar nivå är inte automatiskt en köpsignal. Vänta och se om priset stannar ovanför.": "Right after that, price falls back into the range. The breakout was false. Those who bought at the top are now losing. Lesson: a breakout above an obvious level is not automatically a buy signal. Wait and see if price stays above.", "Samma sak finns under bottnar. Under stödet ligger stoppar från köpare och säljordrar från dem som vill sälja vid ett brott. Det kallas sell-side liquidity. Efter att ha tagit toppen söker priset sig nu ner och tar likviditeten under stödet också.": "The same exists under lows. Below support there are stops from buyers and sell orders from people who want to sell on a break. That's called sell-side liquidity. After taking the high, price now heads down and takes the liquidity below support as well.", "Vad betyder det för dig? Lägg inte din stop-loss precis där alla andra lägger sin, exakt vid en uppenbar topp eller botten. Ge den lite luft. Och köp inte utbrott blint. Fråga dig: tar priset bara likviditet, eller bryter det på riktigt?": "What does this mean for you? Don't put your stop-loss exactly where everyone else does, right at an obvious high or low. Give it some room. And don't buy breakouts blindly. Ask yourself: is price just taking liquidity, or is it really breaking out?", "Fördjupning: rita zoner, inte tunna linjer. Priset vänder sällan på exakt samma öre. Om bottnarna ligger på 103,80, 104,10 och 104,30 är stödet zonen 103,80 till 104,30, inte en linje på 104. Ju fler gånger priset testar en nivå, desto färre köpare finns kvar där, eftersom deras ordrar redan har fyllts. Därför bryts en nivå ofta på det fjärde eller femte testet. Och när ett stöd väl bryts byter det ofta roll. De som köpte där sitter med förlust och vill sälja när priset kommer tillbaka upp. Då blir det gamla stödet ett nytt motstånd.": "Deep dive: draw zones, not thin lines. Price rarely turns at exactly the same cent. If the lows are at 103.80, 104.10 and 104.30, the support is the zone 103.80 to 104.30, not a line at 104. The more times price tests a level, the fewer buyers are left there, because their orders have already been filled. That's why a level often breaks on the fourth or fifth test. And once support breaks, it often switches roles. Those who bought there are sitting on a loss and want to sell when price comes back up. Then the old support becomes new resistance.", "Sammanfattning: stöd och motstånd är nivåer där många ordrar ligger. Lika toppar och bottnar drar till sig likviditet, och priset sveper ofta förbi dem innan det vänder. I nästa video lär du dig två ICT-begrepp som många pratar om: order blocks och fair value gaps.": "Summary: support and resistance are levels where many orders sit. Equal highs and lows attract liquidity, and price often sweeps past them before turning. In the next video you'll learn two ICT concepts many people talk about: order blocks and fair value gaps.", "Vad ligger ofta strax över lika toppar?": "What often sits just above equal highs?", "Stop-loss och köpordrar": "Stop-losses and buy orders", "Ingenting": "Nothing", "Utdelningar": "Dividends", "Bara säljordrar från banken": "Only the bank's sell orders", "Vad är en stop hunt?": "What is a stop hunt?", "När priset sveper förbi en nivå och tar stopparna": "When price sweeps past a level and takes the stops", "När du flyttar din stop-loss": "When you move your stop-loss", "En ny sorts aktie": "A new kind of share", "En skattefri vinst": "A tax-free profit", "Var är det oklokt att lägga sin stop-loss?": "Where is it unwise to put your stop-loss?", "Exakt vid en uppenbar topp eller botten": "Exactly at an obvious high or low", "Med lite luft bortom nivån": "With some room beyond the level", "Där idén är fel": "Where the idea is wrong", "Enligt din plan": "According to your plan", "Order blocks och fair value gaps": "Order blocks and fair value gaps", "Två ICT-begrepp, förklarade ärligt.": "Two ICT concepts, explained honestly.", "ICT står för Inner Circle Trader. Det är ett sätt att läsa grafer som blivit väldigt populärt på YouTube och TikTok. Två av de mest kända begreppen är order blocks och fair value gaps. Jag förklarar båda, och jag är ärlig med var de fungerar och var de inte gör det.": "ICT stands for Inner Circle Trader. It's a way of reading charts that has become very popular on YouTube and TikTok. Two of the best-known concepts are order blocks and fair value gaps. I'll explain both, and I'll be honest about where they work and where they don't.", "Titta på det här kraftiga lyftet. Priset rusar uppåt i flera stora gröna ljus och bryter strukturen. En sådan rörelse brukar kallas en impuls eller displacement. Den visar att någon stor köpte mycket och snabbt.": "Look at this strong move up. Price rushes up in several big green candles and breaks structure. A move like this is often called an impulse or displacement. It shows that someone big bought a lot, fast.", "Ett order block är det sista röda ljuset innan en sådan impuls uppåt. Tanken är att stora aktörer byggde sin position där, och att det kan ligga kvar ordrar på den nivån. Därför tror många att priset kan reagera om det kommer tillbaka dit.": "An order block is the last red candle before such an impulse up. The idea is that big players built their position there, and that orders may still be waiting at that level. That's why many people think price may react if it comes back there.", "Ett fair value gap ser du med tre ljus i rad. Om det första ljusets topp och det tredje ljusets botten inte överlappar finns det ett glapp mellan dem. Där handlades nästan ingenting, priset bara flög förbi. Det kallas också imbalance, obalans.": "You spot a fair value gap with three candles in a row. If the top of the first candle and the bottom of the third don't overlap, there's a gap between them. Almost nothing traded there, price just flew past. It's also called an imbalance.", "Efter impulsen tappar priset fart och börjar falla tillbaka. Det är helt normalt. Ingen trend går rakt upp. Frågan som ICT-traders ställer sig är: var kommer köparna in igen? Svaret de letar efter är ofta i fair value gapet eller i order blocket.": "After the impulse, price loses steam and starts to pull back. That's completely normal. No trend goes straight up. The question ICT traders ask is: where will buyers come back in? The answer they look for is often in the fair value gap or the order block.", "Här kommer priset tillbaka ner in i gapet och vänder upp igen. Det kallas att gapet fylls eller att priset balanserar obalansen. För den som väntade på det här stället kunde det vara en bra plats att köpa, med stoppen under zonen.": "Here price comes back down into the gap and turns up again. That's called filling the gap, or price rebalancing the imbalance. For someone waiting at this spot, it could have been a good place to buy, with the stop below the zone.", "Och priset fortsätter upp. Lägg märke till att det vände i gapet och aldrig nådde ner till order blocket. Det händer ofta. Därför ser många zonerna som områden, inte exakta linjer, och använder order blocket som en sista gräns där idén är fel om priset går under.": "And price continues up. Notice that it turned in the gap and never reached the order block. That happens often. That's why many people treat the zones as areas, not exact lines, and use the order block as a last line where the idea is wrong if price goes below.", "Nu den ärliga delen. Order blocks och fair value gaps är populära, men det finns inga starka bevis för att de fungerar bättre än andra metoder. Ibland respekterar priset zonerna, ibland skär det rakt igenom. Därför är de ledtrådar, inte löften, och du behöver alltid en stop-loss.": "Now the honest part. Order blocks and fair value gaps are popular, but there's no strong evidence that they work better than other methods. Sometimes price respects the zones, sometimes it cuts straight through. So they are clues, not promises, and you always need a stop-loss.", "Fördjupning: så ritar du ett fair value gap exakt. Ta tre ljus i rad under ett kraftigt lyft. Säg att det första ljusets topp är 104,20 och det tredje ljusets botten är 105,00. Mellan 104,20 och 105,00 handlades nästan inget, och det är gapet. Mitten, 104,60, kallas ibland gapets jämvikt, och många tittar extra på den. Är det tredje ljusets botten lägre än det första ljusets topp finns inget gap alls. Ett order block ritar du från det sista röda ljusets botten till dess topp. Kom ihåg: de här zonerna är områden att hålla ögonen på, inte signaler att köpa blint.": "Deep dive: how to draw a fair value gap precisely. Take three candles in a row during a strong rally. Say the first candle's high is 104.20 and the third candle's low is 105.00. Between 104.20 and 105.00 almost nothing traded, and that's the gap. The middle, 104.60, is sometimes called the gap's equilibrium, and many traders watch it closely. If the third candle's low is below the first candle's high, there is no gap at all. You draw an order block from the last red candle's low to its high. Remember: these zones are areas to watch, not signals to buy blindly.", "Sammanfattning: ett order block är sista motsatta ljuset före en stark impuls. Ett fair value gap är ett glapp mellan ljus ett och tre. Båda är zoner där priset ibland reagerar. I nästa video sätter vi ihop allt: när ska man köpa och när ska man sälja?": "Summary: an order block is the last opposite candle before a strong impulse. A fair value gap is a gap between candles one and three. Both are zones where price sometimes reacts. In the next video we put it all together: when should you buy and when should you sell?", "Vad är ett order block i en upptrend?": "What is an order block in an uptrend?", "Sista röda ljuset före en stark impuls uppåt": "The last red candle before a strong move up", "Första gröna ljuset på dagen": "The first green candle of the day", "En spärrad aktie": "A blocked share", "Ett stort köp från dig": "A big buy from you", "Hur hittar du ett fair value gap?": "How do you find a fair value gap?", "Ljus ett och tre överlappar inte": "Candles one and three don't overlap", "Två röda ljus i rad": "Two red candles in a row", "Börsen är stängd": "The market is closed", "Ett ljus utan veke": "A candle without a wick", "Fungerar order blocks och FVG alltid?": "Do order blocks and FVGs always work?", "Nej, de är ledtrådar och kräver stop-loss": "No, they're clues and need a stop-loss", "Ja, alltid": "Yes, always", "Ja, om man har många följare": "Yes, if you have many followers", "Ja, på fredagar": "Yes, on Fridays", "När ska man köpa och sälja?": "When should you buy and sell?", "Riktning, zon och bekräftelse, steg för steg.": "Direction, zone and confirmation, step by step.", "Det här är frågan alla vill ha svar på: när ska jag köpa och när ska jag sälja? Det finns inget magiskt svar, men det finns ett sätt att tänka som de flesta seriösa traders använder. Jag kallar det tre steg: riktning, zon och bekräftelse.": "This is the question everyone wants answered: when should I buy and when should I sell? There's no magic answer, but there's a way of thinking most serious traders use. I call it three steps: direction, zone and confirmation.", "Steg ett: riktning. Vilket håll går trenden åt? Här ser vi högre toppar och högre bottnar, alltså en upptrend. Då letar vi bara efter köp. Vi försöker inte gissa toppen. Det enklaste sättet att förlora pengar är att slåss mot trenden.": "Step one: direction. Which way is the trend going? Here we see higher highs and higher lows, so an uptrend. So we only look for buys. We don't try to guess the top. The easiest way to lose money is to fight the trend.", "Steg två: zon. Köp inte när priset just har rusat upp, då köper du dyrt. Vänta på en rekyl. Dra en linje mitt i den senaste rörelsen, från botten till toppen. Under mitten är priset billigt, discount. Över mitten är det dyrt, premium. Vi vill köpa i discount.": "Step two: zone. Don't buy right after price has rushed up, because then you're buying expensive. Wait for a pullback. Draw a line in the middle of the last move, from low to high. Below the middle, price is cheap, discount. Above the middle, it's expensive, premium. We want to buy in discount.", "Nu är priset i discount och dessutom vid en nivå som tidigare var motstånd. Gammalt motstånd blir ofta nytt stöd. Det här är en bra zon. Men att priset är i en bra zon räcker inte. Det kan fortsätta falla rakt igenom.": "Now price is in discount and also at a level that used to be resistance. Old resistance often becomes new support. This is a good zone. But price being in a good zone isn't enough. It can keep falling straight through.", "Steg tre: bekräftelse. Vänta tills köparna visar att de är tillbaka. Det kan vara ett starkt grönt ljus som stänger högt, en hammare, eller ett litet CHoCH uppåt på en lägre tidsram. Först nu har vi en anledning att köpa.": "Step three: confirmation. Wait until buyers show they're back. It could be a strong green candle closing high, a hammer, or a small CHoCH upwards on a lower timeframe. Only now do we have a reason to buy.", "Så här ser köpet ut. Ingång strax efter bekräftelsen. Stop-loss under botten i zonen, med lite luft, för om priset går dit var idén fel. Mål vid den gamla toppen, där köpsidans likviditet ligger. Planen är klar innan vi klickar.": "This is what the buy looks like. Entry right after the confirmation. Stop-loss below the low in the zone, with some room, because if price goes there, the idea was wrong. Target at the old high, where the buy-side liquidity sits. The plan is ready before we click.", "När ska man sälja? På två ställen som du bestämt i förväg. Antingen når priset målet, och du tar vinsten. Eller så når det stoppen, och du tar en liten förlust. Du säljer inte för att du blir nervös, och du flyttar aldrig ner stoppen.": "When should you sell? At two places you decided in advance. Either price reaches the target and you take the profit. Or it hits the stop and you take a small loss. You don't sell because you get nervous, and you never move the stop down.", "Och när ska man inte handla alls? När trenden är otydlig. När priset är mitt i ingenstans, varken i en zon eller vid en nivå. Precis innan stora nyheter. Och när du är trött, arg eller vill vinna tillbaka en förlust. Att avstå är också ett beslut.": "And when shouldn't you trade at all? When the trend is unclear. When price is in the middle of nowhere, neither in a zone nor at a level. Right before big news. And when you're tired, angry or want to win back a loss. Staying out is a decision too.", "Fördjupning: så räknar du premium och discount. Ta den senaste rörelsen från botten till toppen. Här gick priset från 103 till 111. Skillnaden är 8 kronor, och mitten ligger 4 kronor upp, på 107. Allt över 107 är premium, dyrt. Allt under 107 är discount, billigt. I en upptrend vill du köpa i discount, helst där det också finns ett gammalt motstånd som kan bli stöd, som här runt 106. Mitten är ingen magisk linje. Den hjälper dig bara att undvika att köpa på toppen av en rörelse. Gör toppen ny behöver du räkna om mitten.": "Deep dive: how to calculate premium and discount. Take the latest move from low to high. Here price went from 103 to 111. The difference is 8 kronor, and the midpoint is 4 kronor up, at 107. Everything above 107 is premium, expensive. Everything below 107 is discount, cheap. In an uptrend you want to buy in discount, ideally where old resistance can turn into support, like here around 106. The midpoint isn't a magic line. It just helps you avoid buying at the top of a move. If a new high forms, recalculate the midpoint.", "Sammanfattning: riktning först, sedan en bra zon, sedan bekräftelse. Bestäm ingång, stopp och mål innan du klickar. Sälj vid målet eller stoppen, inte på känsla. I nästa video räknar vi på en trade: hur stor ska den vara och vad händer med pengarna?": "Summary: direction first, then a good zone, then confirmation. Decide entry, stop and target before you click. Sell at the target or the stop, not on a feeling. In the next video we do the maths of a trade: how big should it be and what happens to the money?", "Vilka är de tre stegen?": "What are the three steps?", "Riktning, zon, bekräftelse": "Direction, zone, confirmation", "Köp, sälj, köp igen": "Buy, sell, buy again", "Nyhet, hype, köp": "News, hype, buy", "Gissa, hoppas, vänta": "Guess, hope, wait", "I en upptrend, var vill man helst köpa?": "In an uptrend, where do you prefer to buy?", "I discount, efter en rekyl": "In discount, after a pullback", "På toppen efter ett rusning": "At the top after a spike", "Var som helst": "Anywhere", "När någon på TikTok säger det": "When someone on TikTok says so", "När säljer du enligt planen?": "When do you sell according to the plan?", "Vid målet eller stoppen": "At the target or the stop", "När du blir nervös": "When you get nervous", "Aldrig": "Never", "När en vän säljer": "When a friend sells", "Gå in i en trade": "Entering a trade", "Ingång, stopp, mål, risk/belöning och positionsstorlek.": "Entry, stop, target, risk/reward and position size.", "Du har hittat ett läge. Nu kommer delen som avgör om du överlever som trader: hur du går in i traden. De flesta nybörjare tänker bara på var de ska köpa. Proffs tänker först på hur mycket de kan förlora.": "You've found a setup. Now comes the part that decides whether you survive as a trader: how you enter the trade. Most beginners only think about where to buy. Professionals first think about how much they can lose.", "Ingången. Du kan köpa direkt till marknadspris med en marknadsorder. Eller lägga en limitorder på det pris du vill ha och vänta. Limit ger bättre pris men du kan missa traden. Här köper vi på 105 kronor när bekräftelsen kommer.": "The entry. You can buy straight away at the market price with a market order. Or place a limit order at the price you want and wait. A limit gives a better price but you might miss the trade. Here we buy at 105 kronor when the confirmation comes.", "Stop-lossen. Den ska ligga där din idé är fel, inte där det känns bekvämt. Vår idé är att stödet håller. Om priset går under botten vid 103,60 har vi fel. Vi lägger stoppen på 103 kronor, med lite luft. Risken per aktie blir 2 kronor.": "The stop-loss. It should be where your idea is wrong, not where it feels comfortable. Our idea is that support holds. If price goes below the low at 103.60, we're wrong. We put the stop at 103 kronor, with some room. The risk per share is 2 kronor.", "Målet. Vi siktar på 109 kronor, strax under den gamla toppen. Vinsten per aktie blir då 4 kronor. Vi riskerar alltså 2 för att kunna tjäna 4. Det kallas risk/belöning ett till två. Med ett till två kan du ha fel oftare än rätt och ändå gå plus.": "The target. We aim for 109 kronor, just below the old high. The profit per share is then 4 kronor. So we risk 2 to make 4. That's called a risk/reward of one to two. With one to two, you can be wrong more often than right and still come out ahead.", "Räkna så här. Tio trades med ett till två. Du har rätt fyra gånger och fel sex gånger. Fyra vinster gånger 4 kronor blir 16. Sex förluster gånger 2 kronor blir 12. Du har ändå tjänat 4 kronor per aktie, trots att du hade fel oftast.": "Do the maths like this. Ten trades at one to two. You're right four times and wrong six times. Four wins times 4 kronor is 16. Six losses times 2 kronor is 12. You've still made 4 kronor per share, even though you were wrong most of the time.", "Positionsstorlek. Bestäm hur mycket av kontot du får förlora på en trade, till exempel 1 procent. Har du 10 000 kronor är det 100 kronor. Risken per aktie är 2 kronor. 100 delat med 2 blir 50 aktier. Det är hela regeln: risk i kronor delat med risk per aktie.": "Position size. Decide how much of your account you may lose on one trade, for example 1 percent. If you have 10,000 kronor, that's 100 kronor. The risk per share is 2 kronor. 100 divided by 2 is 50 shares. That's the whole rule: risk in kronor divided by risk per share.", "Och traden går vår väg. Priset når målet och vi säljer 50 aktier med 4 kronors vinst, alltså 200 kronor. Om stoppen hade slagits ut hade vi förlorat 100 kronor, bara 1 procent av kontot. Med den regeln kan du ha flera förluster i rad utan att kontot försvinner.": "And the trade goes our way. Price reaches the target and we sell 50 shares with a 4 kronor profit, so 200 kronor. If the stop had been hit, we'd have lost 100 kronor, only 1 percent of the account. With this rule you can have several losses in a row without the account disappearing.", "Fördjupning: positionsstorlek steg för steg. Ditt konto är 10 000 kronor och du riskerar 1 procent, alltså 100 kronor. Ingången är 105 och stoppen 103, så avståndet är 2 kronor per aktie. 100 delat med 2 är 50. Du köper alltså 50 aktier, värda 5 250 kronor. Om stoppen slås ut förlorar du 100 kronor plus courtage, inte mer. Lägg märke till att det är stoppens avstånd som bestämmer antalet aktier, inte hur säker du känner dig. Ligger stoppen längre bort köper du färre aktier, så att risken i kronor blir densamma varje gång.": "Deep dive: position size step by step. Your account is 10,000 kronor and you risk 1 percent, which is 100 kronor. The entry is 105 and the stop 103, so the distance is 2 kronor per share. 100 divided by 2 is 50. So you buy 50 shares, worth 5,250 kronor. If the stop is hit you lose 100 kronor plus commission, no more. Notice that the stop distance decides the number of shares, not how confident you feel. If the stop is further away you buy fewer shares, so the risk in kronor is the same every time.", "Sammanfattning: stoppen ligger där idén är fel. Målet ger minst dubbelt så mycket som risken. Positionsstorleken räknar du fram så att en förlust bara kostar 1 procent. I sista videon följer vi två hela trades från början till slut, en vinst och en förlust.": "Summary: the stop goes where the idea is wrong. The target gives at least twice the risk. You calculate the position size so a loss only costs 1 percent. In the last video we follow two full trades from start to finish, one win and one loss.", "Ingång 105, stopp 103, mål 109. Vad är risk/belöning?": "Entry 105, stop 103, target 109. What is the risk/reward?", "1 till 2": "1 to 2", "1 till 1": "1 to 1", "2 till 1": "2 to 1", "1 till 4": "1 to 4", "Konto 10 000 kr, risk 1 %, risk per aktie 2 kr. Hur många aktier?": "Account 10,000 kr, risk 1%, risk per share 2 kr. How many shares?", "50": "50", "100": "100", "10": "10", "500": "500", "Var ska stop-lossen ligga?": "Where should the stop-loss go?", "Där det känns bekvämt": "Where it feels comfortable", "Ingenstans": "Nowhere", "Precis på köppriset": "Right at the buy price", "En hel trade från början till slut": "A full trade from start to finish", "En vinst, en förlust och vad du lär dig av båda.": "One win, one loss and what you learn from both.", "I den här sista videon gör vi allt i ordning, som en riktig trader. Först riktningen. Dagsgrafen visar högre toppar och högre bottnar. Trenden är upp, så vi letar bara efter köp. Vi skriver ner det i tradingdagboken innan vi gör något annat.": "In this last video we do everything in order, like a real trader. First, direction. The daily chart shows higher highs and higher lows. The trend is up, so we only look for buys. We write that in the trading journal before doing anything else.", "Sedan zonen. Priset rekylerar ner i discount, under mitten av den senaste rörelsen, och når området runt 105 där det tidigare var motstånd. Vi gör ingenting än. Vi väntar på att köparna ska visa sig.": "Then the zone. Price pulls back into discount, below the middle of the last move, and reaches the area around 105 that used to be resistance. We don't do anything yet. We wait for buyers to show up.", "Bekräftelse: två starka gröna ljus. Nu planerar vi. Ingång 106,60. Stopp 104,60 under botten. Mål 110,80 vid den gamla toppen. Risk 2 kronor, möjlig vinst drygt 4. Kontot är 10 000 kronor och vi riskerar 1 procent, alltså 50 aktier.": "Confirmation: two strong green candles. Now we plan. Entry 106.60. Stop 104.60 below the low. Target 110.80 at the old high. Risk 2 kronor, possible profit just over 4. The account is 10,000 kronor and we risk 1 percent, so 50 shares.", "Priset stiger och når målet. Vi säljer och tar vinsten, ungefär 210 kronor. Vi flyttade inte målet för att det kändes som att det kunde gå högre. Planen sa sälj, så vi sålde. Det låter tråkigt, men det är så man håller sig vid liv länge.": "Price rises and reaches the target. We sell and take the profit, about 210 kronor. We didn't move the target because it felt like it could go higher. The plan said sell, so we sold. It sounds boring, but that's how you survive for a long time.", "Nu en andra trade. Priset faller tillbaka till ungefär 110, den gamla toppen. Vi tror att den blir stöd. Ingång 110,60, stopp 109,40, mål 113. Lägg märke till att bekräftelsen var svagare den här gången. Det är vanligt att man ändå går in.": "Now a second trade. Price falls back to about 110, the old high. We think it will become support. Entry 110.60, stop 109.40, target 113. Notice the confirmation was weaker this time. It's common to go in anyway.", "Priset faller rakt igenom stödet och slår ut stoppen. Vi förlorar 100 kronor, exakt 1 procent som planerat. Det gör ont, men det är en liten skada. Om vi inte hade haft en stopp hade priset tagit med sig mycket mer.": "Price falls straight through support and hits the stop. We lose 100 kronor, exactly 1 percent as planned. It hurts, but it's small damage. If we hadn't had a stop, price would have taken much more with it.", "Titta vad som hände sen. Priset fortsatte ner mot 104. Strukturen gav en varning: en lägre topp och sedan ett brott under den sista högre botten, ett CHoCH. Det här är vad dagboken är till för. Vi skriver: gick in trots svag bekräftelse och en lägre topp.": "Look at what happened next. Price kept falling towards 104. The structure gave a warning: a lower high and then a break below the last higher low, a CHoCH. This is what the journal is for. We write: entered despite weak confirmation and a lower high.", "Resultat: en vinst på 210 och en förlust på 100. Totalt plus 110 kronor, trots att hälften av traderna var fel. Det är så trading fungerar: inte att ha rätt hela tiden, utan att förlora lite när man har fel och vinna mer när man har rätt.": "Result: one win of 210 and one loss of 100. In total plus 110 kronor, even though half the trades were wrong. That's how trading works: not being right all the time, but losing a little when you're wrong and winning more when you're right.", "Fördjupning: skriv en tradingdagbok. Efter varje trade antecknar du fem saker. Ett: varför du gick in, med en mening. Två: ingång, stopp och mål. Tre: resultatet i kronor och i R, alltså hur många gånger risken du vann eller förlorade. Vår första trade blev ungefär plus 2 R, den andra minus 1 R. Fyra: följde du planen, ja eller nej? Fem: hur kändes det? Efter tjugo trades läser du dagboken. Då ser du mönster du aldrig märker i stunden, till exempel att dina förluster nästan alltid kommer när du bröt mot planen.": "Deep dive: keep a trading journal. After every trade, write down five things. One: why you entered, in one sentence. Two: entry, stop and target. Three: the result in kronor and in R, meaning how many times your risk you won or lost. Our first trade was about plus 2 R, the second minus 1 R. Four: did you follow the plan, yes or no? Five: how did it feel? After twenty trades, read the journal. You'll see patterns you never notice in the moment, for example that your losses almost always come when you broke the plan.", "Till sist, ärligt: de flesta som daytradar förlorar pengar, särskilt med hävstång. Öva därför först i Wickis handelssimulator med låtsaspengar. Skriv dagbok. Använd bara pengar du har råd att förlora. Och kom ihåg: Wicki lär ut kunskap, inte investeringsråd. Lycka till, och vi ses i nästa lektion!": "Finally, honestly: most people who day trade lose money, especially with leverage. So practise first in Wicki's trading simulator with pretend money. Keep a journal. Only use money you can afford to lose. And remember: Wicki teaches knowledge, not investment advice. Good luck, and see you in the next lesson!", "En vinst på 210 kr och en förlust på 100 kr. Vad blir resultatet?": "One win of 210 kr and one loss of 100 kr. What's the result?", "+110 kr": "+110 kr", "−110 kr": "−110 kr", "+310 kr": "+310 kr", "0 kr": "0 kr", "Vad var varningen före den förlorande traden?": "What was the warning before the losing trade?", "En lägre topp och svag bekräftelse": "A lower high and weak confirmation", "Ett starkt grönt ljus": "A strong green candle", "En högre botten": "A higher low", "Var är det klokt att öva först?": "Where is it wise to practise first?", "I en simulator med låtsaspengar": "In a simulator with pretend money", "Med lånade pengar": "With borrowed money", "Med hela sparkontot": "With your whole savings", "Med hävstång": "With leverage", "Vanliga nybörjarmisstag": "Common beginner mistakes", "FOMO, ingen stopp, hämndtrading och för stora positioner.": "FOMO, no stop, revenge trading and positions that are too big.", "Den här bonusvideon handlar om misstagen nästan alla nybörjare gör. De flesta förlorar inte pengar för att de inte kan läsa en graf. De förlorar för att de bryter sina egna regler när känslorna tar över. Låt oss gå igenom de vanligaste, så att du känner igen dem.": "This bonus video is about the mistakes almost every beginner makes. Most people don't lose money because they can't read a chart. They lose because they break their own rules when emotions take over. Let's go through the most common ones, so you recognise them.", "Misstag ett: att jaga priset. Aktien har stigit i flera dagar, alla pratar om den och du är rädd att missa. Du köper på toppen, efter att rörelsen redan har hänt. Det är FOMO, och det är ofta precis där de tidiga köparna säljer till dig.": "Mistake one: chasing the price. The share has risen for days, everyone is talking about it and you're afraid to miss out. You buy at the top, after the move has already happened. That's FOMO, and it's often exactly where the early buyers sell to you.", "Misstag två: ingen stop-loss. Priset faller och du tänker att det kommer tillbaka. Det faller mer. Nu är förlusten så stor att det känns omöjligt att sälja. Utan stopp kan en liten förlust växa till en stor. Bestäm alltid stoppen innan du köper.": "Mistake two: no stop-loss. Price falls and you think it'll come back. It falls further. Now the loss is so big that selling feels impossible. Without a stop, a small loss can grow into a big one. Always decide the stop before you buy.", "Misstag tre: att flytta stoppen. Priset närmar sig din stopp och du flyttar ner den lite, sedan lite till. Det är samma sak som att inte ha någon stopp alls. Stoppen var planen när du var lugn. Lita på den, inte på känslan i stunden.": "Mistake three: moving the stop. Price gets close to your stop and you move it down a little, then a little more. That's the same as having no stop at all. The stop was the plan when you were calm. Trust it, not the feeling in the moment.", "Misstag fyra: hämndtrading. Efter en förlust vill du vinna tillbaka pengarna direkt. Du tar nästa trade utan ett riktigt läge, kanske med dubbelt så stor position. Det slutar ofta med en ännu större förlust. Efter två förluster i rad: ta en paus.": "Mistake four: revenge trading. After a loss you want to win the money back straight away. You take the next trade without a real setup, maybe with twice the position size. It often ends in an even bigger loss. After two losses in a row: take a break.", "Misstag fem: för stora positioner. Om du riskerar 20 procent av kontot på en trade räcker det med fem förluster för att allt är borta. Med 1 procent kan du ha tjugo förluster i rad och fortfarande ha det mesta kvar. Små positioner håller dig kvar i spelet.": "Mistake five: positions that are too big. If you risk 20 percent of the account on one trade, five losses are enough to wipe everything out. With 1 percent you can have twenty losses in a row and still have most of it left. Small positions keep you in the game.", "Misstag sex: att handla för ofta. Det finns inte ett bra läge varje timme. Varje affär kostar courtage och varje snabbt beslut ökar risken för fel. De bästa traders väntar mycket och handlar lite. Tålamod är en del av strategin.": "Mistake six: trading too often. There isn't a good setup every hour. Every trade costs fees and every quick decision raises the risk of mistakes. The best traders wait a lot and trade a little. Patience is part of the strategy.", "Misstag sju: att tro på den som säljer drömmen. Kurser och signalgrupper som lovar snabba, säkra vinster tjänar oftast mer på dig än på trading. Ingen seriös person lovar säker vinst. Lär dig grunderna själv, som du gör nu, och var skeptisk.": "Mistake seven: believing the person selling the dream. Courses and signal groups promising fast, safe profits usually make more money from you than from trading. No serious person promises safe profits. Learn the basics yourself, like you're doing now, and stay sceptical.", "Fördjupning: en checklista före varje trade. Läs den högt innan du klickar. Ett: vilken är trenden på den högre tidsramen? Två: är priset i en zon jag planerat, eller jagar jag? Tre: har jag sett en bekräftelse? Fyra: var ligger stoppen, och är den där idén är fel? Fem: är målet minst dubbelt så långt bort som stoppen? Sex: hur många aktier ger 1 procents risk? Sju: är jag lugn, eller vill jag vinna tillbaka något? Om svaret på någon fråga är fel eller osäkert, låt bli. Det kostar ingenting att avstå från en trade.": "Deep dive: a checklist before every trade. Read it out loud before you click. One: what is the trend on the higher timeframe? Two: is price in a zone I planned, or am I chasing? Three: have I seen confirmation? Four: where is the stop, and is it where the idea is wrong? Five: is the target at least twice as far as the stop? Six: how many shares give 1 percent risk? Seven: am I calm, or do I want to win something back? If the answer to any question is wrong or unsure, skip it. It costs nothing to pass on a trade.", "Sammanfattning: köp inte på FOMO, ha alltid en stopp och flytta den inte, ta paus efter förluster, riskera lite per trade, handla mindre och var skeptisk mot drömförsäljare. Om du undviker de här sju misstagen ligger du redan före de flesta nybörjare.": "Summary: don't buy on FOMO, always have a stop and don't move it, take a break after losses, risk little per trade, trade less and be sceptical of dream sellers. If you avoid these seven mistakes, you're already ahead of most beginners.", "Vad är FOMO i trading?": "What is FOMO in trading?", "Att köpa sent av rädsla att missa": "Buying late out of fear of missing out", "En säker strategi": "A safe strategy", "En typ av order": "A type of order", "Att ta en paus": "Taking a break", "Vad bör du göra efter två förluster i rad?": "What should you do after two losses in a row?", "Ta en paus": "Take a break", "Dubbla positionen": "Double the position", "Ta bort stoppen": "Remove the stop", "Köpa en kurs": "Buy a course", "Hur många förluster i rad tål du med 20 % risk per trade?": "How many losses in a row can you take at 20% risk per trade?", "Ungefär fem": "About five", "Hundra": "A hundred", "Tjugo": "Twenty", "Oändligt många": "Infinitely many", "Köpare": "Buyers", "Säljare": "Sellers", "Animerad graf": "Animated chart", "Videoskolan": "Video school", "Se trading förklaras på grafen, med röst.": "Watch trading explained on the chart, with voice.", "klara": "done", "Video": "Video", "Rösten är datorgenererad och läser på ditt språk.": "The voice is computer-generated and reads in your language.", "Testa dig själv · 3 frågor": "Test yourself · 3 questions", "Nästa video:": "Next video:", "Föregående": "Previous", "Spela upp": "Play", "Nästa": "Next", "Ljud": "Sound", "8 videor om varför priset rör sig, när man köper och säljer.": "8 videos on why price moves and when to buy and sell.", "Fortsätt titta": "Keep watching", "Jag vill lära mig trading": "I want to learn trading", "Börja med videor om hur priset rör sig": "Start with videos on how price moves", "min": "min"}, "fr": {"Varför rör sig priset?": "Pourquoi le prix bouge-t-il ?", "Köpare, säljare och varför ljusen ser ut som de gör.": "Acheteurs, vendeurs et pourquoi les bougies ont cette forme.", "Välkommen till Wickis videoskola. Jag är Wicki, och i de här videorna lär du dig det som traders faktiskt vill förstå: varför priset rör sig, när man köper, när man säljer och hur man går in i en trade. Vi börjar med den viktigaste frågan av alla: varför rör sig priset över huvud taget?": "Bienvenue à l'école vidéo de Wicki. Je suis Wicki, et dans ces vidéos tu vas apprendre ce que les traders veulent vraiment comprendre : pourquoi le prix bouge, quand acheter, quand vendre et comment entrer dans un trade. On commence par la question la plus importante : pourquoi le prix bouge-t-il ?", "Varje gång någon köper en aktie måste någon annan sälja den. Priset är helt enkelt den nivå där en köpare och en säljare möts just nu. Så länge båda sidor är ungefär lika starka står priset nästan still.": "Chaque fois que quelqu'un achète une action, quelqu'un d'autre doit la vendre. Le prix, c'est simplement le niveau où un acheteur et un vendeur se rencontrent à cet instant. Tant que les deux camps sont à peu près aussi forts, le prix bouge à peine.", "Men när fler vill köpa än sälja händer något. Köparna måste erbjuda ett högre pris för att någon ska vilja sälja till dem. Då stiger priset. Det är därför du ser gröna ljus staplas på varandra uppåt.": "Mais quand plus de gens veulent acheter que vendre, il se passe quelque chose. Les acheteurs doivent proposer un prix plus élevé pour que quelqu'un accepte de leur vendre. Alors le prix monte. C'est pour ça que tu vois des bougies vertes s'empiler vers le haut.", "Och tvärtom. När fler vill sälja än köpa måste säljarna sänka priset för att hitta köpare. Då faller priset och du ser röda ljus. Priset rör sig alltså mot den sida där det finns minst motstånd.": "Et inversement. Quand plus de gens veulent vendre qu'acheter, les vendeurs doivent baisser le prix pour trouver des acheteurs. Le prix baisse et tu vois des bougies rouges. Le prix va donc du côté où il y a le moins de résistance.", "Varje ljus är en sammanfattning av striden under en viss tid, till exempel en timme. Kroppen visar var priset öppnade och stängde. Vekarna visar hur långt köpare och säljare lyckades trycka priset innan motparten tryckte tillbaka.": "Chaque bougie résume la bataille pendant une période, par exemple une heure. Le corps montre où le prix a ouvert et clôturé. Les mèches montrent jusqu'où acheteurs et vendeurs ont réussi à pousser avant que l'autre camp ne repousse.", "Varför vill folk plötsligt köpa mer? Det kan vara en bra kvartalsrapport, en räntesänkning, en nyhet om företaget eller bara att priset bryter en nivå som många tittar på. Då rusar många köpare in samtidigt och priset tar fart.": "Pourquoi les gens veulent-ils soudain acheter plus ? Ça peut être un bon rapport trimestriel, une baisse des taux, une nouvelle sur l'entreprise, ou simplement le prix qui casse un niveau que beaucoup surveillent. Beaucoup d'acheteurs arrivent en même temps et le prix accélère.", "Stora aktörer, som fonder och banker, handlar enorma belopp. De kan inte köpa allt på en gång utan behöver många motparter. Därför dras priset ofta mot ställen där många har ordrar liggande, till exempel strax över ett gammalt toppläge. Sådana ställen kallas likviditet.": "Les gros acteurs, comme les fonds et les banques, échangent des montants énormes. Ils ne peuvent pas tout acheter d'un coup et ont besoin de beaucoup de contreparties. C'est pourquoi le prix est souvent attiré là où beaucoup d'ordres attendent, par exemple juste au-dessus d'un ancien sommet. On appelle ces endroits la liquidité.", "Här är det viktigaste att komma ihåg: ingen vet säkert vad som händer härnäst. Inte YouTube-tradern, inte banken och inte jag. Det du kan göra är att läsa vilken sida som verkar starkast och vad som är mest sannolikt, och sedan skydda dig om du har fel.": "Voici le plus important à retenir : personne ne sait avec certitude ce qui va se passer. Ni le trader de YouTube, ni la banque, ni moi. Ce que tu peux faire, c'est lire quel camp semble le plus fort et ce qui est le plus probable, puis te protéger si tu te trompes.", "Låt oss gå på djupet med ett enda ljus. Säg att timmen öppnar på 100 kronor. Köparna trycker upp priset till 104, men säljarna slår tillbaka och timmen stänger på 102. Då blir kroppen grön, från 100 till 102, eftersom priset stängde högre än det öppnade. Den övre veken, från 102 till 104, visar att köparna nådde högre men inte orkade hålla kvar. En lång övre veke betyder alltså att säljarna vann slutet av striden. En lång nedre veke betyder tvärtom att köparna tog tillbaka priset från en lägre nivå. Läs därför alltid kroppen och vekarna tillsammans: kroppen visar vem som vann, vekarna visar hur hårt det var.": "Allons dans le détail avec une seule bougie. Disons que l'heure ouvre à 100 couronnes. Les acheteurs poussent le prix jusqu'à 104, mais les vendeurs répliquent et l'heure clôture à 102. Le corps est vert, de 100 à 102, car le prix a clôturé plus haut qu'il n'a ouvert. La mèche haute, de 102 à 104, montre que les acheteurs sont montés plus haut sans pouvoir tenir. Une longue mèche haute signifie donc que les vendeurs ont gagné la fin du combat. Une longue mèche basse signifie l'inverse : les acheteurs ont fait remonter le prix depuis plus bas. Lis toujours le corps et les mèches ensemble : le corps montre qui a gagné, les mèches montrent à quel point c'était dur.", "Sammanfattning: priset rör sig när köpare och säljare inte är i balans. Nyheter och stora aktörer sätter fart på rörelsen, och priset dras ofta mot likviditet. I nästa video lär du dig läsa trenden med hjälp av marknadsstruktur: toppar och bottnar.": "Résumé : le prix bouge quand acheteurs et vendeurs ne sont pas en équilibre. Les nouvelles et les gros acteurs accélèrent le mouvement, et le prix est souvent attiré par la liquidité. Dans la prochaine vidéo, tu apprendras à lire la tendance grâce à la structure de marché : les sommets et les creux.", "Varför stiger priset?": "Pourquoi le prix monte-t-il ?", "Fler vill köpa än sälja": "Plus de gens veulent acheter que vendre", "Fler vill sälja än köpa": "Plus de gens veulent vendre qu'acheter", "Börsen bestämmer det": "La Bourse le décide", "Det är slumpen, alltid": "C'est toujours le hasard", "Vad visar vekarna på ett ljus?": "Que montrent les mèches d'une bougie ?", "Hur långt priset trycktes innan det vände": "Jusqu'où le prix a été poussé avant de se retourner", "Vem som äger aktien": "Qui possède l'action", "Nästa dags pris": "Le prix de demain", "Volymen": "Le volume", "Vad kallas ställen där många har ordrar liggande?": "Comment appelle-t-on les endroits où beaucoup d'ordres attendent ?", "Likviditet": "La liquidité", "Utdelning": "Le dividende", "Courtage": "Le courtage", "Inflation": "L'inflation", "Trend och marknadsstruktur": "Tendance et structure de marché", "Toppar, bottnar, BOS och CHoCH.": "Sommets, creux, BOS et CHoCH.", "Priset går aldrig rakt upp eller rakt ner. Det rör sig i vågor: upp, lite tillbaka, upp igen. Om du lär dig läsa vågorna ser du vem som styr marknaden. Det kallas marknadsstruktur, och det är grunden i nästan all trading, även i ICT.": "Le prix ne monte jamais tout droit et ne descend jamais tout droit. Il bouge par vagues : il monte, recule un peu, remonte. Si tu apprends à lire les vagues, tu vois qui contrôle le marché. On appelle ça la structure de marché, et c'est la base de presque tout le trading, y compris ICT.", "Varje gång priset vänder bildas en topp eller en botten. När varje ny topp är högre än den förra, en Higher High, och varje ny botten är högre än den förra, en Higher Low, då är trenden uppåt. Köparna styr.": "Chaque fois que le prix se retourne, il forme un sommet ou un creux. Quand chaque nouveau sommet est plus haut que le précédent, un Higher High, et chaque nouveau creux plus haut que le précédent, un Higher Low, la tendance est haussière. Les acheteurs contrôlent.", "Titta på stället där priset går över den förra toppen. Det kallas Break of Structure, förkortat BOS. Ett BOS i trendens riktning är ett tecken på att trenden fortsätter. Köparna orkade ta sig förbi säljarna som väntade vid den gamla toppen.": "Regarde l'endroit où le prix dépasse le sommet précédent. On appelle ça un Break of Structure, ou BOS. Un BOS dans le sens de la tendance indique que la tendance continue. Les acheteurs ont réussi à passer les vendeurs qui attendaient au vieux sommet.", "Trenden fortsätter: ny högre botten, nytt BOS, ny högre topp. Så länge det här mönstret håller är det oftast klokare att leta efter köp än att försöka gissa var toppen kommer. Att handla mot trenden är som att simma mot strömmen.": "La tendance continue : nouveau creux plus haut, nouveau BOS, nouveau sommet plus haut. Tant que ce schéma tient, il est généralement plus sage de chercher des achats que de deviner où sera le sommet. Trader contre la tendance, c'est nager à contre-courant.", "Men titta nu. Den nya toppen blev lägre än den förra. Det kallas en Lower High. Köparna orkar inte längre ta priset lika högt. Det är en första varning, men trenden är inte bruten än. Den sista högre botten håller fortfarande.": "Mais regarde maintenant. Le nouveau sommet est plus bas que le précédent. On appelle ça un Lower High. Les acheteurs n'arrivent plus à pousser le prix aussi haut. C'est un premier avertissement, mais la tendance n'est pas encore cassée. Le dernier creux plus haut tient toujours.", "Nu bryter priset under den sista högre botten. Det första brottet mot trenden kallas Change of Character, CHoCH, eller Market Structure Shift. Det betyder att säljarna har tagit över, åtminstone för tillfället. Många ICT-traders väntar på just den här signalen.": "Maintenant le prix casse sous le dernier creux plus haut. La première cassure contre la tendance s'appelle un Change of Character, CHoCH, ou Market Structure Shift. Ça veut dire que les vendeurs ont pris le dessus, au moins pour l'instant. Beaucoup de traders ICT attendent exactement ce signal.", "Efter CHoCH ser vi lägre toppar och lägre bottnar. Nu är trenden nedåt, och ett nytt BOS nedåt bekräftar det. Samma regler gäller fast spegelvänt: i en nedåttrend letar man hellre efter blankning eller håller sig borta än köper.": "Après le CHoCH, on voit des sommets plus bas et des creux plus bas. La tendance est maintenant baissière, et un nouveau BOS vers le bas le confirme. Mêmes règles, mais à l'envers : en tendance baissière, on cherche plutôt des ventes à découvert ou on reste dehors au lieu d'acheter.", "Ett tips: titta alltid på flera tidsramar. Trenden på dagsgrafen är den stora bilden. Trenden på femminutersgrafen är bara en våg i den. Många börjar med en högre tidsram för riktningen och går ner till en lägre för att hitta exakt var de ska gå in.": "Un conseil : regarde toujours plusieurs unités de temps. La tendance sur le graphique journalier, c'est la vue d'ensemble. La tendance en cinq minutes n'est qu'une vague à l'intérieur. Beaucoup commencent par une unité de temps plus grande pour la direction, puis descendent plus bas pour trouver exactement où entrer.", "Fördjupning: hur vet du att ett BOS är på riktigt? Titta på var ljuset stänger, inte bara på veken. Om en veke sticker över den förra toppen men ljuset stänger under, har strukturen inte brutits. Det är ofta bara ett försök som misslyckades. Ett riktigt BOS är när ett ljus stänger över toppen, gärna med en stor kropp. Samma sak gäller CHoCH åt andra hållet: vänta på en stängning under den sista högre botten. Och välj vilka toppar och bottnar du räknar. Små svängningar inne i en större rörelse räknas inte. Börja med de tydliga vändpunkterna som du ser direkt när du zoomar ut.": "Approfondissement : comment savoir si un BOS est réel ? Regarde où la bougie clôture, pas seulement la mèche. Si une mèche dépasse le dernier sommet mais que la bougie clôture en dessous, la structure n'est pas cassée. C'est souvent juste une tentative ratée. Un vrai BOS, c'est une bougie qui clôture au-dessus du sommet, idéalement avec un gros corps. Même chose pour un CHoCH dans l'autre sens : attends une clôture sous le dernier creux plus haut. Et choisis quels sommets et creux tu comptes. Les petites oscillations dans un mouvement plus large ne comptent pas. Commence par les points de retournement évidents quand tu dézoomes.", "Sammanfattning: högre toppar och högre bottnar betyder upptrend. BOS bekräftar att trenden fortsätter. CHoCH är det första tecknet på att den vänder. I nästa video tittar vi på stöd, motstånd och likviditet, alltså varför priset vänder där det vänder.": "Résumé : des sommets et des creux plus hauts signifient une tendance haussière. Un BOS confirme que la tendance continue. Un CHoCH est le premier signe d'un retournement. Dans la prochaine vidéo, on regarde les supports, les résistances et la liquidité, c'est-à-dire pourquoi le prix se retourne là où il se retourne.", "Vad kännetecknar en upptrend?": "Qu'est-ce qui caractérise une tendance haussière ?", "Högre toppar och högre bottnar": "Sommets et creux plus hauts", "Lägre toppar och lägre bottnar": "Sommets et creux plus bas", "Bara gröna ljus": "Seulement des bougies vertes", "Hög volym": "Un gros volume", "Vad är ett CHoCH?": "Qu'est-ce qu'un CHoCH ?", "Första brottet mot trenden": "La première cassure contre la tendance", "Ett brott med trenden": "Une cassure dans le sens de la tendance", "En sorts ordertyp": "Un type d'ordre", "En nyhet": "Une actualité", "Varför titta på flera tidsramar?": "Pourquoi regarder plusieurs unités de temps ?", "Stor bild för riktning, liten för ingång": "Grande vue pour la direction, petite pour l'entrée", "För att det ser proffsigt ut": "Parce que ça fait pro", "Det spelar ingen roll": "Ça n'a pas d'importance", "För att slippa stop-loss": "Pour éviter le stop-loss", "Stöd, motstånd och likviditet": "Supports, résistances et liquidité", "Varför priset vänder där det vänder, och stop hunts.": "Pourquoi le prix se retourne là où il se retourne, et les chasses aux stops.", "Ett stöd är en nivå där priset har slutat falla och vänt upp, gärna flera gånger. Varför? För att många köpare minns nivån. De som missade köpet förra gången lägger sina köpordrar där igen. Köptrycket stoppar fallet.": "Un support est un niveau où le prix a cessé de baisser et est remonté, idéalement plusieurs fois. Pourquoi ? Parce que beaucoup d'acheteurs se souviennent du niveau. Ceux qui ont raté l'achat la dernière fois y placent à nouveau leurs ordres. La pression acheteuse stoppe la baisse.", "Motstånd är samma sak fast uppåt. Det är en nivå där priset har slutat stiga. Där väntar säljare: folk som köpte högre och vill komma ut utan förlust, och folk som tycker att priset är för högt. Nu ser vi ett intervall mellan stöd och motstånd.": "La résistance, c'est la même chose vers le haut. C'est un niveau où le prix a cessé de monter. Des vendeurs y attendent : ceux qui ont acheté plus haut et veulent sortir sans perte, et ceux qui trouvent le prix trop élevé. On voit maintenant un range entre support et résistance.", "Titta på topparna. Priset har nuddat samma nivå tre gånger. Det kallas lika toppar, equal highs. För nybörjare ser det ut som ett starkt motstånd. Men proffsen ser något annat: en hög med ordrar som ligger precis ovanför.": "Regarde les sommets. Le prix a touché le même niveau trois fois. On appelle ça des sommets égaux, equal highs. Pour les débutants, ça ressemble à une forte résistance. Mais les pros voient autre chose : un tas d'ordres juste au-dessus.", "Ovanför lika toppar ligger två sorters ordrar. Stop-loss från dem som blankat vid motståndet, och köpordrar från dem som vill köpa när priset bryter uppåt. Båda blir köp när de utlöses. Det kallas buy-side liquidity, köpsidans likviditet.": "Au-dessus des sommets égaux, il y a deux types d'ordres. Les stop-loss de ceux qui ont vendu à découvert sur la résistance, et les ordres d'achat de ceux qui veulent acheter à la cassure. Les deux deviennent des achats quand ils se déclenchent. On appelle ça la liquidité côté achat, buy-side liquidity.", "Och här händer det. Priset sticker upp över topparna och tar likviditeten. Alla stoppar utlöses och nya köpare hoppar på utbrottet. Det ger en stor aktör möjlighet att sälja mycket till alla dessa köpare. Det kallas en liquidity sweep eller stop hunt.": "Et voilà. Le prix pique au-dessus des sommets et prend la liquidité. Tous les stops se déclenchent et de nouveaux acheteurs sautent sur la cassure. Ça permet à un gros acteur de vendre beaucoup à tous ces acheteurs. On appelle ça un liquidity sweep ou une chasse aux stops.", "Direkt efteråt faller priset tillbaka in i intervallet. Utbrottet var falskt. De som köpte på toppen sitter nu med förlust. Lärdom: ett utbrott över en uppenbar nivå är inte automatiskt en köpsignal. Vänta och se om priset stannar ovanför.": "Juste après, le prix retombe dans le range. La cassure était fausse. Ceux qui ont acheté en haut sont maintenant en perte. Leçon : une cassure au-dessus d'un niveau évident n'est pas automatiquement un signal d'achat. Attends de voir si le prix reste au-dessus.", "Samma sak finns under bottnar. Under stödet ligger stoppar från köpare och säljordrar från dem som vill sälja vid ett brott. Det kallas sell-side liquidity. Efter att ha tagit toppen söker priset sig nu ner och tar likviditeten under stödet också.": "C'est pareil sous les creux. Sous le support, il y a les stops des acheteurs et les ordres de vente de ceux qui veulent vendre à la cassure. On appelle ça la liquidité côté vente, sell-side liquidity. Après avoir pris le sommet, le prix descend et prend aussi la liquidité sous le support.", "Vad betyder det för dig? Lägg inte din stop-loss precis där alla andra lägger sin, exakt vid en uppenbar topp eller botten. Ge den lite luft. Och köp inte utbrott blint. Fråga dig: tar priset bara likviditet, eller bryter det på riktigt?": "Qu'est-ce que ça veut dire pour toi ? Ne place pas ton stop-loss exactement là où tout le monde le met, pile sur un sommet ou un creux évident. Laisse-lui de la marge. Et n'achète pas les cassures à l'aveugle. Demande-toi : le prix prend-il juste la liquidité, ou casse-t-il vraiment ?", "Fördjupning: rita zoner, inte tunna linjer. Priset vänder sällan på exakt samma öre. Om bottnarna ligger på 103,80, 104,10 och 104,30 är stödet zonen 103,80 till 104,30, inte en linje på 104. Ju fler gånger priset testar en nivå, desto färre köpare finns kvar där, eftersom deras ordrar redan har fyllts. Därför bryts en nivå ofta på det fjärde eller femte testet. Och när ett stöd väl bryts byter det ofta roll. De som köpte där sitter med förlust och vill sälja när priset kommer tillbaka upp. Då blir det gamla stödet ett nytt motstånd.": "Approfondissement : trace des zones, pas des lignes fines. Le prix se retourne rarement exactement au même centime. Si les creux sont à 103,80, 104,10 et 104,30, le support est la zone de 103,80 à 104,30, pas une ligne à 104. Plus le prix teste un niveau, moins il reste d'acheteurs, car leurs ordres ont déjà été exécutés. C'est pourquoi un niveau casse souvent au quatrième ou cinquième test. Et une fois cassé, un support change souvent de rôle. Ceux qui ont acheté là sont en perte et veulent vendre quand le prix remonte. L'ancien support devient alors une nouvelle résistance.", "Sammanfattning: stöd och motstånd är nivåer där många ordrar ligger. Lika toppar och bottnar drar till sig likviditet, och priset sveper ofta förbi dem innan det vänder. I nästa video lär du dig två ICT-begrepp som många pratar om: order blocks och fair value gaps.": "Résumé : supports et résistances sont des niveaux où se trouvent beaucoup d'ordres. Les sommets et creux égaux attirent la liquidité, et le prix les balaie souvent avant de se retourner. Dans la prochaine vidéo, tu découvriras deux notions ICT dont beaucoup parlent : les order blocks et les fair value gaps.", "Vad ligger ofta strax över lika toppar?": "Qu'y a-t-il souvent juste au-dessus des sommets égaux ?", "Stop-loss och köpordrar": "Des stop-loss et des ordres d'achat", "Ingenting": "Rien", "Utdelningar": "Des dividendes", "Bara säljordrar från banken": "Seulement des ordres de vente de la banque", "Vad är en stop hunt?": "Qu'est-ce qu'une chasse aux stops ?", "När priset sveper förbi en nivå och tar stopparna": "Quand le prix balaie un niveau et prend les stops", "När du flyttar din stop-loss": "Quand tu déplaces ton stop-loss", "En ny sorts aktie": "Un nouveau type d'action", "En skattefri vinst": "Un gain non imposable", "Var är det oklokt att lägga sin stop-loss?": "Où est-il imprudent de placer son stop-loss ?", "Exakt vid en uppenbar topp eller botten": "Pile sur un sommet ou un creux évident", "Med lite luft bortom nivån": "Avec un peu de marge au-delà du niveau", "Där idén är fel": "Là où l'idée est fausse", "Enligt din plan": "Selon ton plan", "Order blocks och fair value gaps": "Order blocks et fair value gaps", "Två ICT-begrepp, förklarade ärligt.": "Deux notions ICT, expliquées honnêtement.", "ICT står för Inner Circle Trader. Det är ett sätt att läsa grafer som blivit väldigt populärt på YouTube och TikTok. Två av de mest kända begreppen är order blocks och fair value gaps. Jag förklarar båda, och jag är ärlig med var de fungerar och var de inte gör det.": "ICT signifie Inner Circle Trader. C'est une façon de lire les graphiques devenue très populaire sur YouTube et TikTok. Deux des notions les plus connues sont les order blocks et les fair value gaps. Je t'explique les deux, et je suis honnête sur où elles marchent et où elles ne marchent pas.", "Titta på det här kraftiga lyftet. Priset rusar uppåt i flera stora gröna ljus och bryter strukturen. En sådan rörelse brukar kallas en impuls eller displacement. Den visar att någon stor köpte mycket och snabbt.": "Regarde cette forte hausse. Le prix monte en flèche en plusieurs grandes bougies vertes et casse la structure. Un tel mouvement s'appelle souvent une impulsion ou un displacement. Il montre que quelqu'un de gros a acheté beaucoup, vite.", "Ett order block är det sista röda ljuset innan en sådan impuls uppåt. Tanken är att stora aktörer byggde sin position där, och att det kan ligga kvar ordrar på den nivån. Därför tror många att priset kan reagera om det kommer tillbaka dit.": "Un order block, c'est la dernière bougie rouge avant une telle impulsion haussière. L'idée, c'est que les gros acteurs y ont construit leur position et qu'il peut rester des ordres à ce niveau. C'est pourquoi beaucoup pensent que le prix peut réagir s'il y revient.", "Ett fair value gap ser du med tre ljus i rad. Om det första ljusets topp och det tredje ljusets botten inte överlappar finns det ett glapp mellan dem. Där handlades nästan ingenting, priset bara flög förbi. Det kallas också imbalance, obalans.": "Tu repères un fair value gap avec trois bougies d'affilée. Si le haut de la première et le bas de la troisième ne se chevauchent pas, il y a un trou entre elles. Presque rien ne s'y est échangé, le prix est juste passé en vitesse. On l'appelle aussi un déséquilibre, imbalance.", "Efter impulsen tappar priset fart och börjar falla tillbaka. Det är helt normalt. Ingen trend går rakt upp. Frågan som ICT-traders ställer sig är: var kommer köparna in igen? Svaret de letar efter är ofta i fair value gapet eller i order blocket.": "Après l'impulsion, le prix s'essouffle et commence à reculer. C'est tout à fait normal. Aucune tendance ne monte en ligne droite. La question que se posent les traders ICT : où les acheteurs vont-ils revenir ? Ils cherchent souvent la réponse dans le fair value gap ou l'order block.", "Här kommer priset tillbaka ner in i gapet och vänder upp igen. Det kallas att gapet fylls eller att priset balanserar obalansen. För den som väntade på det här stället kunde det vara en bra plats att köpa, med stoppen under zonen.": "Ici, le prix redescend dans le trou et remonte. On dit que le gap se comble, ou que le prix rééquilibre le déséquilibre. Pour celui qui attendait à cet endroit, ça pouvait être un bon point d'achat, avec le stop sous la zone.", "Och priset fortsätter upp. Lägg märke till att det vände i gapet och aldrig nådde ner till order blocket. Det händer ofta. Därför ser många zonerna som områden, inte exakta linjer, och använder order blocket som en sista gräns där idén är fel om priset går under.": "Et le prix continue de monter. Remarque qu'il s'est retourné dans le gap sans jamais atteindre l'order block. Ça arrive souvent. C'est pourquoi beaucoup voient les zones comme des espaces, pas des lignes exactes, et utilisent l'order block comme dernière limite : si le prix passe dessous, l'idée est fausse.", "Nu den ärliga delen. Order blocks och fair value gaps är populära, men det finns inga starka bevis för att de fungerar bättre än andra metoder. Ibland respekterar priset zonerna, ibland skär det rakt igenom. Därför är de ledtrådar, inte löften, och du behöver alltid en stop-loss.": "Maintenant, la partie honnête. Les order blocks et les fair value gaps sont populaires, mais il n'y a pas de preuves solides qu'ils marchent mieux que d'autres méthodes. Parfois le prix respecte les zones, parfois il les traverse. Ce sont donc des indices, pas des promesses, et il te faut toujours un stop-loss.", "Fördjupning: så ritar du ett fair value gap exakt. Ta tre ljus i rad under ett kraftigt lyft. Säg att det första ljusets topp är 104,20 och det tredje ljusets botten är 105,00. Mellan 104,20 och 105,00 handlades nästan inget, och det är gapet. Mitten, 104,60, kallas ibland gapets jämvikt, och många tittar extra på den. Är det tredje ljusets botten lägre än det första ljusets topp finns inget gap alls. Ett order block ritar du från det sista röda ljusets botten till dess topp. Kom ihåg: de här zonerna är områden att hålla ögonen på, inte signaler att köpa blint.": "Approfondissement : comment tracer précisément un fair value gap. Prends trois bougies de suite pendant une forte hausse. Disons que le haut de la première est 104,20 et le bas de la troisième 105,00. Entre 104,20 et 105,00 presque rien ne s'est échangé : c'est le gap. Le milieu, 104,60, est parfois appelé l'équilibre du gap, et beaucoup le surveillent. Si le bas de la troisième bougie est sous le haut de la première, il n'y a pas de gap. Un order block se trace du bas au haut de la dernière bougie rouge. Rappelle-toi : ces zones sont à surveiller, ce ne sont pas des signaux d'achat aveugles.", "Sammanfattning: ett order block är sista motsatta ljuset före en stark impuls. Ett fair value gap är ett glapp mellan ljus ett och tre. Båda är zoner där priset ibland reagerar. I nästa video sätter vi ihop allt: när ska man köpa och när ska man sälja?": "Résumé : un order block est la dernière bougie opposée avant une forte impulsion. Un fair value gap est un trou entre les bougies un et trois. Ce sont des zones où le prix réagit parfois. Dans la prochaine vidéo, on assemble tout : quand acheter et quand vendre ?", "Vad är ett order block i en upptrend?": "Qu'est-ce qu'un order block en tendance haussière ?", "Sista röda ljuset före en stark impuls uppåt": "La dernière bougie rouge avant une forte hausse", "Första gröna ljuset på dagen": "La première bougie verte du jour", "En spärrad aktie": "Une action bloquée", "Ett stort köp från dig": "Un gros achat de ta part", "Hur hittar du ett fair value gap?": "Comment repérer un fair value gap ?", "Ljus ett och tre överlappar inte": "Les bougies un et trois ne se chevauchent pas", "Två röda ljus i rad": "Deux bougies rouges d'affilée", "Börsen är stängd": "La Bourse est fermée", "Ett ljus utan veke": "Une bougie sans mèche", "Fungerar order blocks och FVG alltid?": "Les order blocks et FVG marchent-ils toujours ?", "Nej, de är ledtrådar och kräver stop-loss": "Non, ce sont des indices qui demandent un stop-loss", "Ja, alltid": "Oui, toujours", "Ja, om man har många följare": "Oui, si on a beaucoup d'abonnés", "Ja, på fredagar": "Oui, le vendredi", "När ska man köpa och sälja?": "Quand acheter et quand vendre ?", "Riktning, zon och bekräftelse, steg för steg.": "Direction, zone et confirmation, étape par étape.", "Det här är frågan alla vill ha svar på: när ska jag köpa och när ska jag sälja? Det finns inget magiskt svar, men det finns ett sätt att tänka som de flesta seriösa traders använder. Jag kallar det tre steg: riktning, zon och bekräftelse.": "C'est la question à laquelle tout le monde veut une réponse : quand acheter et quand vendre ? Il n'y a pas de réponse magique, mais il y a une façon de penser que la plupart des traders sérieux utilisent. Je l'appelle trois étapes : direction, zone et confirmation.", "Steg ett: riktning. Vilket håll går trenden åt? Här ser vi högre toppar och högre bottnar, alltså en upptrend. Då letar vi bara efter köp. Vi försöker inte gissa toppen. Det enklaste sättet att förlora pengar är att slåss mot trenden.": "Étape un : la direction. Dans quel sens va la tendance ? Ici, on voit des sommets et des creux plus hauts, donc une tendance haussière. On ne cherche alors que des achats. On n'essaie pas de deviner le sommet. Le moyen le plus simple de perdre de l'argent, c'est de lutter contre la tendance.", "Steg två: zon. Köp inte när priset just har rusat upp, då köper du dyrt. Vänta på en rekyl. Dra en linje mitt i den senaste rörelsen, från botten till toppen. Under mitten är priset billigt, discount. Över mitten är det dyrt, premium. Vi vill köpa i discount.": "Étape deux : la zone. N'achète pas juste après que le prix a flambé, tu achètes cher. Attends un repli. Trace une ligne au milieu du dernier mouvement, du creux au sommet. Sous le milieu, le prix est bon marché, discount. Au-dessus, il est cher, premium. On veut acheter en discount.", "Nu är priset i discount och dessutom vid en nivå som tidigare var motstånd. Gammalt motstånd blir ofta nytt stöd. Det här är en bra zon. Men att priset är i en bra zon räcker inte. Det kan fortsätta falla rakt igenom.": "Le prix est maintenant en discount et en plus sur un niveau qui était une résistance. Une ancienne résistance devient souvent un nouveau support. C'est une bonne zone. Mais être dans une bonne zone ne suffit pas. Le prix peut continuer à tomber à travers.", "Steg tre: bekräftelse. Vänta tills köparna visar att de är tillbaka. Det kan vara ett starkt grönt ljus som stänger högt, en hammare, eller ett litet CHoCH uppåt på en lägre tidsram. Först nu har vi en anledning att köpa.": "Étape trois : la confirmation. Attends que les acheteurs montrent qu'ils sont de retour. Ça peut être une forte bougie verte qui clôture haut, un marteau, ou un petit CHoCH haussier sur une unité de temps plus petite. Seulement maintenant, on a une raison d'acheter.", "Så här ser köpet ut. Ingång strax efter bekräftelsen. Stop-loss under botten i zonen, med lite luft, för om priset går dit var idén fel. Mål vid den gamla toppen, där köpsidans likviditet ligger. Planen är klar innan vi klickar.": "Voici à quoi ressemble l'achat. Entrée juste après la confirmation. Stop-loss sous le creux de la zone, avec un peu de marge, car si le prix y va, l'idée était fausse. Objectif au vieux sommet, là où se trouve la liquidité côté achat. Le plan est prêt avant de cliquer.", "När ska man sälja? På två ställen som du bestämt i förväg. Antingen når priset målet, och du tar vinsten. Eller så når det stoppen, och du tar en liten förlust. Du säljer inte för att du blir nervös, och du flyttar aldrig ner stoppen.": "Quand vendre ? À deux endroits décidés à l'avance. Soit le prix atteint l'objectif et tu prends le gain. Soit il touche le stop et tu prends une petite perte. Tu ne vends pas parce que tu stresses, et tu ne descends jamais ton stop.", "Och när ska man inte handla alls? När trenden är otydlig. När priset är mitt i ingenstans, varken i en zon eller vid en nivå. Precis innan stora nyheter. Och när du är trött, arg eller vill vinna tillbaka en förlust. Att avstå är också ett beslut.": "Et quand ne pas trader du tout ? Quand la tendance n'est pas claire. Quand le prix est au milieu de nulle part, ni dans une zone ni sur un niveau. Juste avant de grosses nouvelles. Et quand tu es fatigué, en colère ou que tu veux te refaire. Rester dehors, c'est aussi une décision.", "Fördjupning: så räknar du premium och discount. Ta den senaste rörelsen från botten till toppen. Här gick priset från 103 till 111. Skillnaden är 8 kronor, och mitten ligger 4 kronor upp, på 107. Allt över 107 är premium, dyrt. Allt under 107 är discount, billigt. I en upptrend vill du köpa i discount, helst där det också finns ett gammalt motstånd som kan bli stöd, som här runt 106. Mitten är ingen magisk linje. Den hjälper dig bara att undvika att köpa på toppen av en rörelse. Gör toppen ny behöver du räkna om mitten.": "Approfondissement : comment calculer premium et discount. Prends le dernier mouvement du creux au sommet. Ici le prix est passé de 103 à 111. L'écart est de 8 couronnes, et le milieu est 4 couronnes plus haut, à 107. Tout ce qui est au-dessus de 107 est premium, cher. Tout ce qui est en dessous est discount, bon marché. En tendance haussière, tu veux acheter en discount, idéalement là où une ancienne résistance peut devenir support, comme ici vers 106. Le milieu n'est pas une ligne magique. Il t'aide juste à éviter d'acheter au sommet. Si un nouveau sommet se forme, recalcule le milieu.", "Sammanfattning: riktning först, sedan en bra zon, sedan bekräftelse. Bestäm ingång, stopp och mål innan du klickar. Sälj vid målet eller stoppen, inte på känsla. I nästa video räknar vi på en trade: hur stor ska den vara och vad händer med pengarna?": "Résumé : d'abord la direction, puis une bonne zone, puis la confirmation. Décide l'entrée, le stop et l'objectif avant de cliquer. Vends à l'objectif ou au stop, pas au feeling. Dans la prochaine vidéo, on calcule un trade : quelle taille et que devient l'argent ?", "Vilka är de tre stegen?": "Quelles sont les trois étapes ?", "Riktning, zon, bekräftelse": "Direction, zone, confirmation", "Köp, sälj, köp igen": "Acheter, vendre, racheter", "Nyhet, hype, köp": "Actualité, emballement, achat", "Gissa, hoppas, vänta": "Deviner, espérer, attendre", "I en upptrend, var vill man helst köpa?": "En tendance haussière, où préfère-t-on acheter ?", "I discount, efter en rekyl": "En discount, après un repli", "På toppen efter ett rusning": "Au sommet après une flambée", "Var som helst": "N'importe où", "När någon på TikTok säger det": "Quand quelqu'un le dit sur TikTok", "När säljer du enligt planen?": "Quand vends-tu selon le plan ?", "Vid målet eller stoppen": "À l'objectif ou au stop", "När du blir nervös": "Quand tu stresses", "Aldrig": "Jamais", "När en vän säljer": "Quand un ami vend", "Gå in i en trade": "Entrer dans un trade", "Ingång, stopp, mål, risk/belöning och positionsstorlek.": "Entrée, stop, objectif, risque/rendement et taille de position.", "Du har hittat ett läge. Nu kommer delen som avgör om du överlever som trader: hur du går in i traden. De flesta nybörjare tänker bara på var de ska köpa. Proffs tänker först på hur mycket de kan förlora.": "Tu as trouvé une opportunité. Maintenant vient la partie qui décide si tu survis comme trader : comment tu entres dans le trade. La plupart des débutants ne pensent qu'à où acheter. Les pros pensent d'abord à combien ils peuvent perdre.", "Ingången. Du kan köpa direkt till marknadspris med en marknadsorder. Eller lägga en limitorder på det pris du vill ha och vänta. Limit ger bättre pris men du kan missa traden. Här köper vi på 105 kronor när bekräftelsen kommer.": "L'entrée. Tu peux acheter tout de suite au prix du marché avec un ordre au marché. Ou placer un ordre limite au prix voulu et attendre. La limite donne un meilleur prix mais tu peux rater le trade. Ici, on achète à 105 couronnes quand arrive la confirmation.", "Stop-lossen. Den ska ligga där din idé är fel, inte där det känns bekvämt. Vår idé är att stödet håller. Om priset går under botten vid 103,60 har vi fel. Vi lägger stoppen på 103 kronor, med lite luft. Risken per aktie blir 2 kronor.": "Le stop-loss. Il doit être là où ton idée est fausse, pas là où c'est confortable. Notre idée : le support tient. Si le prix passe sous le creux à 103,60, on a tort. On met le stop à 103 couronnes, avec un peu de marge. Le risque par action est de 2 couronnes.", "Målet. Vi siktar på 109 kronor, strax under den gamla toppen. Vinsten per aktie blir då 4 kronor. Vi riskerar alltså 2 för att kunna tjäna 4. Det kallas risk/belöning ett till två. Med ett till två kan du ha fel oftare än rätt och ändå gå plus.": "L'objectif. On vise 109 couronnes, juste sous l'ancien sommet. Le gain par action est alors de 4 couronnes. On risque donc 2 pour gagner 4. C'est un rapport risque/rendement de un pour deux. Avec un pour deux, tu peux avoir tort plus souvent que raison et rester gagnant.", "Räkna så här. Tio trades med ett till två. Du har rätt fyra gånger och fel sex gånger. Fyra vinster gånger 4 kronor blir 16. Sex förluster gånger 2 kronor blir 12. Du har ändå tjänat 4 kronor per aktie, trots att du hade fel oftast.": "Calcule comme ça. Dix trades à un pour deux. Tu as raison quatre fois et tort six fois. Quatre gains fois 4 couronnes font 16. Six pertes fois 2 couronnes font 12. Tu as quand même gagné 4 couronnes par action, alors que tu avais tort la plupart du temps.", "Positionsstorlek. Bestäm hur mycket av kontot du får förlora på en trade, till exempel 1 procent. Har du 10 000 kronor är det 100 kronor. Risken per aktie är 2 kronor. 100 delat med 2 blir 50 aktier. Det är hela regeln: risk i kronor delat med risk per aktie.": "La taille de position. Décide combien de ton compte tu peux perdre sur un trade, par exemple 1 pour cent. Avec 10 000 couronnes, c'est 100 couronnes. Le risque par action est de 2 couronnes. 100 divisé par 2, ça fait 50 actions. Voilà toute la règle : le risque en couronnes divisé par le risque par action.", "Och traden går vår väg. Priset når målet och vi säljer 50 aktier med 4 kronors vinst, alltså 200 kronor. Om stoppen hade slagits ut hade vi förlorat 100 kronor, bara 1 procent av kontot. Med den regeln kan du ha flera förluster i rad utan att kontot försvinner.": "Et le trade va dans notre sens. Le prix atteint l'objectif et on vend 50 actions avec 4 couronnes de gain, soit 200 couronnes. Si le stop avait sauté, on aurait perdu 100 couronnes, seulement 1 pour cent du compte. Avec cette règle, tu peux enchaîner plusieurs pertes sans que le compte disparaisse.", "Fördjupning: positionsstorlek steg för steg. Ditt konto är 10 000 kronor och du riskerar 1 procent, alltså 100 kronor. Ingången är 105 och stoppen 103, så avståndet är 2 kronor per aktie. 100 delat med 2 är 50. Du köper alltså 50 aktier, värda 5 250 kronor. Om stoppen slås ut förlorar du 100 kronor plus courtage, inte mer. Lägg märke till att det är stoppens avstånd som bestämmer antalet aktier, inte hur säker du känner dig. Ligger stoppen längre bort köper du färre aktier, så att risken i kronor blir densamma varje gång.": "Approfondissement : la taille de position étape par étape. Ton compte fait 10 000 couronnes et tu risques 1 %, soit 100 couronnes. L'entrée est à 105 et le stop à 103, l'écart est donc de 2 couronnes par action. 100 divisé par 2 font 50. Tu achètes donc 50 actions, pour 5 250 couronnes. Si le stop est touché, tu perds 100 couronnes plus le courtage, pas plus. Note que c'est la distance du stop qui fixe le nombre d'actions, pas ta confiance. Si le stop est plus loin, tu achètes moins d'actions pour que le risque en couronnes reste le même à chaque fois.", "Sammanfattning: stoppen ligger där idén är fel. Målet ger minst dubbelt så mycket som risken. Positionsstorleken räknar du fram så att en förlust bara kostar 1 procent. I sista videon följer vi två hela trades från början till slut, en vinst och en förlust.": "Résumé : le stop va là où l'idée est fausse. L'objectif rapporte au moins deux fois le risque. Tu calcules la taille de position pour qu'une perte ne coûte que 1 pour cent. Dans la dernière vidéo, on suit deux trades complets du début à la fin, un gagnant et un perdant.", "Ingång 105, stopp 103, mål 109. Vad är risk/belöning?": "Entrée 105, stop 103, objectif 109. Quel est le risque/rendement ?", "1 till 2": "1 pour 2", "1 till 1": "1 pour 1", "2 till 1": "2 pour 1", "1 till 4": "1 pour 4", "Konto 10 000 kr, risk 1 %, risk per aktie 2 kr. Hur många aktier?": "Compte 10 000 couronnes, risque 1 %, risque par action 2 couronnes. Combien d'actions ?", "50": "50", "100": "100", "10": "10", "500": "500", "Var ska stop-lossen ligga?": "Où doit se placer le stop-loss ?", "Där det känns bekvämt": "Là où c'est confortable", "Ingenstans": "Nulle part", "Precis på köppriset": "Pile au prix d'achat", "En hel trade från början till slut": "Un trade complet du début à la fin", "En vinst, en förlust och vad du lär dig av båda.": "Un gain, une perte et ce que tu apprends des deux.", "I den här sista videon gör vi allt i ordning, som en riktig trader. Först riktningen. Dagsgrafen visar högre toppar och högre bottnar. Trenden är upp, så vi letar bara efter köp. Vi skriver ner det i tradingdagboken innan vi gör något annat.": "Dans cette dernière vidéo, on fait tout dans l'ordre, comme un vrai trader. D'abord la direction. Le graphique journalier montre des sommets et des creux plus hauts. La tendance est haussière, donc on ne cherche que des achats. On l'écrit dans le journal de trading avant toute chose.", "Sedan zonen. Priset rekylerar ner i discount, under mitten av den senaste rörelsen, och når området runt 105 där det tidigare var motstånd. Vi gör ingenting än. Vi väntar på att köparna ska visa sig.": "Ensuite la zone. Le prix recule en discount, sous le milieu du dernier mouvement, et atteint la zone autour de 105 qui était une résistance. On ne fait encore rien. On attend que les acheteurs se montrent.", "Bekräftelse: två starka gröna ljus. Nu planerar vi. Ingång 106,60. Stopp 104,60 under botten. Mål 110,80 vid den gamla toppen. Risk 2 kronor, möjlig vinst drygt 4. Kontot är 10 000 kronor och vi riskerar 1 procent, alltså 50 aktier.": "Confirmation : deux fortes bougies vertes. Maintenant on planifie. Entrée 106,60. Stop 104,60 sous le creux. Objectif 110,80 à l'ancien sommet. Risque 2 couronnes, gain possible d'un peu plus de 4. Le compte fait 10 000 couronnes et on risque 1 pour cent, donc 50 actions.", "Priset stiger och når målet. Vi säljer och tar vinsten, ungefär 210 kronor. Vi flyttade inte målet för att det kändes som att det kunde gå högre. Planen sa sälj, så vi sålde. Det låter tråkigt, men det är så man håller sig vid liv länge.": "Le prix monte et atteint l'objectif. On vend et on prend le gain, environ 210 couronnes. On n'a pas déplacé l'objectif parce qu'on sentait que ça pouvait monter plus. Le plan disait vendre, alors on a vendu. Ça paraît ennuyeux, mais c'est comme ça qu'on tient longtemps.", "Nu en andra trade. Priset faller tillbaka till ungefär 110, den gamla toppen. Vi tror att den blir stöd. Ingång 110,60, stopp 109,40, mål 113. Lägg märke till att bekräftelsen var svagare den här gången. Det är vanligt att man ändå går in.": "Maintenant un deuxième trade. Le prix redescend vers 110, l'ancien sommet. On pense qu'il deviendra un support. Entrée 110,60, stop 109,40, objectif 113. Remarque que la confirmation était plus faible cette fois. C'est courant d'entrer quand même.", "Priset faller rakt igenom stödet och slår ut stoppen. Vi förlorar 100 kronor, exakt 1 procent som planerat. Det gör ont, men det är en liten skada. Om vi inte hade haft en stopp hade priset tagit med sig mycket mer.": "Le prix traverse le support et touche le stop. On perd 100 couronnes, exactement 1 pour cent comme prévu. Ça fait mal, mais les dégâts sont petits. Sans stop, le prix aurait emporté bien plus.", "Titta vad som hände sen. Priset fortsatte ner mot 104. Strukturen gav en varning: en lägre topp och sedan ett brott under den sista högre botten, ett CHoCH. Det här är vad dagboken är till för. Vi skriver: gick in trots svag bekräftelse och en lägre topp.": "Regarde ce qui s'est passé ensuite. Le prix a continué vers 104. La structure avait prévenu : un sommet plus bas puis une cassure sous le dernier creux plus haut, un CHoCH. C'est à ça que sert le journal. On note : entré malgré une confirmation faible et un sommet plus bas.", "Resultat: en vinst på 210 och en förlust på 100. Totalt plus 110 kronor, trots att hälften av traderna var fel. Det är så trading fungerar: inte att ha rätt hela tiden, utan att förlora lite när man har fel och vinna mer när man har rätt.": "Résultat : un gain de 210 et une perte de 100. Au total plus 110 couronnes, alors que la moitié des trades étaient faux. C'est comme ça que marche le trading : pas avoir raison tout le temps, mais perdre peu quand on a tort et gagner plus quand on a raison.", "Fördjupning: skriv en tradingdagbok. Efter varje trade antecknar du fem saker. Ett: varför du gick in, med en mening. Två: ingång, stopp och mål. Tre: resultatet i kronor och i R, alltså hur många gånger risken du vann eller förlorade. Vår första trade blev ungefär plus 2 R, den andra minus 1 R. Fyra: följde du planen, ja eller nej? Fem: hur kändes det? Efter tjugo trades läser du dagboken. Då ser du mönster du aldrig märker i stunden, till exempel att dina förluster nästan alltid kommer när du bröt mot planen.": "Approfondissement : tiens un journal de trading. Après chaque trade, note cinq choses. Un : pourquoi tu es entré, en une phrase. Deux : entrée, stop et objectif. Trois : le résultat en couronnes et en R, c'est-à-dire combien de fois ton risque tu as gagné ou perdu. Notre premier trade a fait environ plus 2 R, le second moins 1 R. Quatre : as-tu suivi le plan, oui ou non ? Cinq : qu'as-tu ressenti ? Après vingt trades, relis le journal. Tu verras des schémas invisibles sur le moment, par exemple que tes pertes arrivent presque toujours quand tu as enfreint le plan.", "Till sist, ärligt: de flesta som daytradar förlorar pengar, särskilt med hävstång. Öva därför först i Wickis handelssimulator med låtsaspengar. Skriv dagbok. Använd bara pengar du har råd att förlora. Och kom ihåg: Wicki lär ut kunskap, inte investeringsråd. Lycka till, och vi ses i nästa lektion!": "Enfin, honnêtement : la plupart des day traders perdent de l'argent, surtout avec effet de levier. Entraîne-toi donc d'abord dans le simulateur de Wicki avec de l'argent fictif. Tiens un journal. N'utilise que de l'argent que tu peux te permettre de perdre. Et souviens-toi : Wicki enseigne des connaissances, pas des conseils en investissement. Bonne chance, et à la prochaine leçon !", "En vinst på 210 kr och en förlust på 100 kr. Vad blir resultatet?": "Un gain de 210 et une perte de 100 couronnes. Quel résultat ?", "+110 kr": "+110 couronnes", "−110 kr": "−110 couronnes", "+310 kr": "+310 couronnes", "0 kr": "0 couronne", "Vad var varningen före den förlorande traden?": "Quel était l'avertissement avant le trade perdant ?", "En lägre topp och svag bekräftelse": "Un sommet plus bas et une confirmation faible", "Ett starkt grönt ljus": "Une forte bougie verte", "En högre botten": "Un creux plus haut", "Var är det klokt att öva först?": "Où est-il sage de s'entraîner d'abord ?", "I en simulator med låtsaspengar": "Dans un simulateur avec de l'argent fictif", "Med lånade pengar": "Avec de l'argent emprunté", "Med hela sparkontot": "Avec toute ton épargne", "Med hävstång": "Avec effet de levier", "Vanliga nybörjarmisstag": "Erreurs courantes des débutants", "FOMO, ingen stopp, hämndtrading och för stora positioner.": "FOMO, pas de stop, trading de revanche et positions trop grosses.", "Den här bonusvideon handlar om misstagen nästan alla nybörjare gör. De flesta förlorar inte pengar för att de inte kan läsa en graf. De förlorar för att de bryter sina egna regler när känslorna tar över. Låt oss gå igenom de vanligaste, så att du känner igen dem.": "Cette vidéo bonus parle des erreurs que presque tous les débutants font. La plupart ne perdent pas parce qu'ils ne savent pas lire un graphique. Ils perdent parce qu'ils enfreignent leurs propres règles quand les émotions prennent le dessus. Passons en revue les plus courantes, pour que tu les reconnaisses.", "Misstag ett: att jaga priset. Aktien har stigit i flera dagar, alla pratar om den och du är rädd att missa. Du köper på toppen, efter att rörelsen redan har hänt. Det är FOMO, och det är ofta precis där de tidiga köparna säljer till dig.": "Erreur un : courir après le prix. L'action monte depuis des jours, tout le monde en parle et tu as peur de rater ça. Tu achètes au sommet, une fois le mouvement fait. C'est le FOMO, et c'est souvent précisément là que les premiers acheteurs te vendent.", "Misstag två: ingen stop-loss. Priset faller och du tänker att det kommer tillbaka. Det faller mer. Nu är förlusten så stor att det känns omöjligt att sälja. Utan stopp kan en liten förlust växa till en stor. Bestäm alltid stoppen innan du köper.": "Erreur deux : pas de stop-loss. Le prix baisse et tu te dis qu'il va remonter. Il baisse encore. La perte devient si grosse que vendre semble impossible. Sans stop, une petite perte peut devenir énorme. Décide toujours ton stop avant d'acheter.", "Misstag tre: att flytta stoppen. Priset närmar sig din stopp och du flyttar ner den lite, sedan lite till. Det är samma sak som att inte ha någon stopp alls. Stoppen var planen när du var lugn. Lita på den, inte på känslan i stunden.": "Erreur trois : déplacer le stop. Le prix approche de ton stop et tu le descends un peu, puis encore un peu. C'est comme ne pas avoir de stop du tout. Le stop, c'était le plan quand tu étais calme. Fais-lui confiance, pas à l'émotion du moment.", "Misstag fyra: hämndtrading. Efter en förlust vill du vinna tillbaka pengarna direkt. Du tar nästa trade utan ett riktigt läge, kanske med dubbelt så stor position. Det slutar ofta med en ännu större förlust. Efter två förluster i rad: ta en paus.": "Erreur quatre : le trading de revanche. Après une perte, tu veux te refaire tout de suite. Tu prends le trade suivant sans vraie opportunité, peut-être avec une position deux fois plus grosse. Ça finit souvent par une perte encore plus grande. Après deux pertes d'affilée : fais une pause.", "Misstag fem: för stora positioner. Om du riskerar 20 procent av kontot på en trade räcker det med fem förluster för att allt är borta. Med 1 procent kan du ha tjugo förluster i rad och fortfarande ha det mesta kvar. Små positioner håller dig kvar i spelet.": "Erreur cinq : des positions trop grosses. Si tu risques 20 pour cent du compte sur un trade, cinq pertes suffisent à tout perdre. Avec 1 pour cent, tu peux enchaîner vingt pertes et garder l'essentiel. Les petites positions te gardent dans la partie.", "Misstag sex: att handla för ofta. Det finns inte ett bra läge varje timme. Varje affär kostar courtage och varje snabbt beslut ökar risken för fel. De bästa traders väntar mycket och handlar lite. Tålamod är en del av strategin.": "Erreur six : trader trop souvent. Il n'y a pas une bonne opportunité toutes les heures. Chaque opération coûte des frais et chaque décision rapide augmente le risque d'erreur. Les meilleurs traders attendent beaucoup et tradent peu. La patience fait partie de la stratégie.", "Misstag sju: att tro på den som säljer drömmen. Kurser och signalgrupper som lovar snabba, säkra vinster tjänar oftast mer på dig än på trading. Ingen seriös person lovar säker vinst. Lär dig grunderna själv, som du gör nu, och var skeptisk.": "Erreur sept : croire celui qui vend du rêve. Les formations et groupes de signaux qui promettent des gains rapides et sûrs gagnent souvent plus grâce à toi que grâce au trading. Aucune personne sérieuse ne promet des gains sûrs. Apprends les bases toi-même, comme maintenant, et reste sceptique.", "Fördjupning: en checklista före varje trade. Läs den högt innan du klickar. Ett: vilken är trenden på den högre tidsramen? Två: är priset i en zon jag planerat, eller jagar jag? Tre: har jag sett en bekräftelse? Fyra: var ligger stoppen, och är den där idén är fel? Fem: är målet minst dubbelt så långt bort som stoppen? Sex: hur många aktier ger 1 procents risk? Sju: är jag lugn, eller vill jag vinna tillbaka något? Om svaret på någon fråga är fel eller osäkert, låt bli. Det kostar ingenting att avstå från en trade.": "Approfondissement : une checklist avant chaque trade. Lis-la à voix haute avant de cliquer. Un : quelle est la tendance sur l'unité de temps supérieure ? Deux : le prix est-il dans une zone prévue, ou est-ce que je cours après ? Trois : ai-je vu une confirmation ? Quatre : où est le stop, et est-il là où l'idée est fausse ? Cinq : l'objectif est-il au moins deux fois plus loin que le stop ? Six : combien d'actions donnent 1 % de risque ? Sept : suis-je calme, ou ai-je envie de me refaire ? Si une réponse est mauvaise ou incertaine, passe ton tour. Renoncer à un trade ne coûte rien.", "Sammanfattning: köp inte på FOMO, ha alltid en stopp och flytta den inte, ta paus efter förluster, riskera lite per trade, handla mindre och var skeptisk mot drömförsäljare. Om du undviker de här sju misstagen ligger du redan före de flesta nybörjare.": "Résumé : n'achète pas par FOMO, aie toujours un stop et ne le déplace pas, fais une pause après les pertes, risque peu par trade, trade moins et méfie-toi des vendeurs de rêve. Si tu évites ces sept erreurs, tu es déjà devant la plupart des débutants.", "Vad är FOMO i trading?": "Qu'est-ce que le FOMO en trading ?", "Att köpa sent av rädsla att missa": "Acheter tard par peur de rater", "En säker strategi": "Une stratégie sûre", "En typ av order": "Un type d'ordre", "Att ta en paus": "Faire une pause", "Vad bör du göra efter två förluster i rad?": "Que faire après deux pertes d'affilée ?", "Ta en paus": "Faire une pause", "Dubbla positionen": "Doubler la position", "Ta bort stoppen": "Retirer le stop", "Köpa en kurs": "Acheter une formation", "Hur många förluster i rad tål du med 20 % risk per trade?": "Combien de pertes d'affilée peux-tu encaisser avec 20 % de risque par trade ?", "Ungefär fem": "Environ cinq", "Hundra": "Cent", "Tjugo": "Vingt", "Oändligt många": "Une infinité", "Köpare": "Acheteurs", "Säljare": "Vendeurs", "Animerad graf": "Graphique animé", "Videoskolan": "École vidéo", "Se trading förklaras på grafen, med röst.": "Regarde le trading expliqué sur le graphique, avec la voix.", "klara": "terminées", "Video": "Vidéo", "Rösten är datorgenererad och läser på ditt språk.": "La voix est générée par ordinateur et lit dans ta langue.", "Testa dig själv · 3 frågor": "Teste-toi · 3 questions", "Nästa video:": "Vidéo suivante :", "Föregående": "Précédent", "Spela upp": "Lecture", "Nästa": "Suivant", "Ljud": "Son", "8 videor om varför priset rör sig, när man köper och säljer.": "8 vidéos sur pourquoi le prix bouge, quand acheter et vendre.", "Fortsätt titta": "Continuer", "Jag vill lära mig trading": "Je veux apprendre le trading", "Börja med videor om hur priset rör sig": "Commencer par des vidéos sur les mouvements du prix", "min": "min"}, "ar": {"Varför rör sig priset?": "لماذا يتحرك السعر؟", "Köpare, säljare och varför ljusen ser ut som de gör.": "المشترون والبائعون ولماذا تبدو الشموع هكذا.", "Välkommen till Wickis videoskola. Jag är Wicki, och i de här videorna lär du dig det som traders faktiskt vill förstå: varför priset rör sig, när man köper, när man säljer och hur man går in i en trade. Vi börjar med den viktigaste frågan av alla: varför rör sig priset över huvud taget?": "مرحبًا بك في مدرسة Wicki بالفيديو. أنا Wicki، وفي هذه الفيديوهات ستتعلم ما يريد المتداولون فهمه فعلًا: لماذا يتحرك السعر، ومتى تشتري، ومتى تبيع، وكيف تدخل صفقة. نبدأ بأهم سؤال على الإطلاق: لماذا يتحرك السعر أصلًا؟", "Varje gång någon köper en aktie måste någon annan sälja den. Priset är helt enkelt den nivå där en köpare och en säljare möts just nu. Så länge båda sidor är ungefär lika starka står priset nästan still.": "في كل مرة يشتري فيها شخص سهمًا يجب أن يبيعه شخص آخر. السعر ببساطة هو المستوى الذي يلتقي عنده مشترٍ وبائع في هذه اللحظة. وطالما الطرفان متساويان تقريبًا في القوة، فبالكاد يتحرك السعر.", "Men när fler vill köpa än sälja händer något. Köparna måste erbjuda ett högre pris för att någon ska vilja sälja till dem. Då stiger priset. Det är därför du ser gröna ljus staplas på varandra uppåt.": "لكن عندما يريد عدد أكبر الشراء مقارنة بالبيع يحدث شيء ما. يضطر المشترون إلى عرض سعر أعلى ليقبل أحد البيع لهم. فيرتفع السعر. لهذا ترى الشموع الخضراء تتراكم صعودًا.", "Och tvärtom. När fler vill sälja än köpa måste säljarna sänka priset för att hitta köpare. Då faller priset och du ser röda ljus. Priset rör sig alltså mot den sida där det finns minst motstånd.": "والعكس صحيح. عندما يريد عدد أكبر البيع مقارنة بالشراء يضطر البائعون إلى خفض السعر ليجدوا مشترين. فينخفض السعر وترى شموعًا حمراء. أي أن السعر يتحرك نحو الجهة الأقل مقاومة.", "Varje ljus är en sammanfattning av striden under en viss tid, till exempel en timme. Kroppen visar var priset öppnade och stängde. Vekarna visar hur långt köpare och säljare lyckades trycka priset innan motparten tryckte tillbaka.": "كل شمعة هي ملخص للمعركة خلال فترة معينة، مثلًا ساعة. يُظهر الجسم أين افتتح السعر وأين أغلق. وتُظهر الفتائل إلى أي حد نجح المشترون والبائعون في دفع السعر قبل أن يردّه الطرف الآخر.", "Varför vill folk plötsligt köpa mer? Det kan vara en bra kvartalsrapport, en räntesänkning, en nyhet om företaget eller bara att priset bryter en nivå som många tittar på. Då rusar många köpare in samtidigt och priset tar fart.": "لماذا يريد الناس فجأة شراء المزيد؟ قد يكون تقريرًا فصليًا قويًا، أو خفضًا للفائدة، أو خبرًا عن الشركة، أو ببساطة كسر السعر لمستوى يراقبه كثيرون. فيندفع مشترون كثر في وقت واحد ويتسارع السعر.", "Stora aktörer, som fonder och banker, handlar enorma belopp. De kan inte köpa allt på en gång utan behöver många motparter. Därför dras priset ofta mot ställen där många har ordrar liggande, till exempel strax över ett gammalt toppläge. Sådana ställen kallas likviditet.": "يتداول اللاعبون الكبار مثل الصناديق والبنوك مبالغ ضخمة. لا يستطيعون شراء كل شيء دفعة واحدة ويحتاجون إلى أطراف مقابلة كثيرة. لهذا ينجذب السعر غالبًا إلى أماكن تنتظر فيها أوامر كثيرة، مثل ما فوق قمة قديمة مباشرة. تُسمى هذه الأماكن السيولة.", "Här är det viktigaste att komma ihåg: ingen vet säkert vad som händer härnäst. Inte YouTube-tradern, inte banken och inte jag. Det du kan göra är att läsa vilken sida som verkar starkast och vad som är mest sannolikt, och sedan skydda dig om du har fel.": "إليك أهم ما يجب تذكره: لا أحد يعرف يقينًا ما سيحدث بعد ذلك. لا متداول يوتيوب ولا البنك ولا أنا. ما يمكنك فعله هو قراءة أي طرف يبدو أقوى وما هو الأرجح، ثم حماية نفسك إن كنت مخطئًا.", "Låt oss gå på djupet med ett enda ljus. Säg att timmen öppnar på 100 kronor. Köparna trycker upp priset till 104, men säljarna slår tillbaka och timmen stänger på 102. Då blir kroppen grön, från 100 till 102, eftersom priset stängde högre än det öppnade. Den övre veken, från 102 till 104, visar att köparna nådde högre men inte orkade hålla kvar. En lång övre veke betyder alltså att säljarna vann slutet av striden. En lång nedre veke betyder tvärtom att köparna tog tillbaka priset från en lägre nivå. Läs därför alltid kroppen och vekarna tillsammans: kroppen visar vem som vann, vekarna visar hur hårt det var.": "لنتعمق في شمعة واحدة. لنفترض أن الساعة تفتح عند 100 كرونة. يدفع المشترون السعر إلى 104، لكن البائعين يردون وتغلق الساعة عند 102. يكون الجسم أخضر من 100 إلى 102، لأن السعر أغلق أعلى مما افتتح. الفتيل العلوي من 102 إلى 104 يُظهر أن المشترين وصلوا أعلى لكنهم لم يستطيعوا الثبات. لذلك يعني الفتيل العلوي الطويل أن البائعين ربحوا نهاية المعركة. والفتيل السفلي الطويل يعني العكس: المشترون أعادوا السعر من مستوى أدنى. اقرأ دائمًا الجسم والفتائل معًا: الجسم يُظهر من فاز، والفتائل تُظهر مدى صعوبة المعركة.", "Sammanfattning: priset rör sig när köpare och säljare inte är i balans. Nyheter och stora aktörer sätter fart på rörelsen, och priset dras ofta mot likviditet. I nästa video lär du dig läsa trenden med hjälp av marknadsstruktur: toppar och bottnar.": "الخلاصة: يتحرك السعر عندما يختل التوازن بين المشترين والبائعين. الأخبار واللاعبون الكبار يسرّعون الحركة، وغالبًا ينجذب السعر نحو السيولة. في الفيديو التالي ستتعلم قراءة الاتجاه باستخدام بنية السوق: القمم والقيعان.", "Varför stiger priset?": "لماذا يرتفع السعر؟", "Fler vill köpa än sälja": "عدد أكبر يريد الشراء مقارنة بالبيع", "Fler vill sälja än köpa": "عدد أكبر يريد البيع مقارنة بالشراء", "Börsen bestämmer det": "البورصة تقرر ذلك", "Det är slumpen, alltid": "إنه عشوائي دائمًا", "Vad visar vekarna på ett ljus?": "ماذا تُظهر فتائل الشمعة؟", "Hur långt priset trycktes innan det vände": "إلى أي حد دُفع السعر قبل أن ينعكس", "Vem som äger aktien": "من يملك السهم", "Nästa dags pris": "سعر الغد", "Volymen": "الحجم", "Vad kallas ställen där många har ordrar liggande?": "ماذا تُسمى الأماكن التي تنتظر فيها أوامر كثيرة؟", "Likviditet": "السيولة", "Utdelning": "التوزيعات", "Courtage": "العمولة", "Inflation": "التضخم", "Trend och marknadsstruktur": "الاتجاه وبنية السوق", "Toppar, bottnar, BOS och CHoCH.": "القمم والقيعان وBOS وCHoCH.", "Priset går aldrig rakt upp eller rakt ner. Det rör sig i vågor: upp, lite tillbaka, upp igen. Om du lär dig läsa vågorna ser du vem som styr marknaden. Det kallas marknadsstruktur, och det är grunden i nästan all trading, även i ICT.": "السعر لا يصعد أبدًا بخط مستقيم ولا يهبط كذلك. إنه يتحرك على شكل موجات: صعود، ثم تراجع قليل، ثم صعود مجددًا. إذا تعلمت قراءة الموجات سترى من يتحكم في السوق. يُسمى هذا بنية السوق، وهو أساس معظم التداول، بما فيه ICT.", "Varje gång priset vänder bildas en topp eller en botten. När varje ny topp är högre än den förra, en Higher High, och varje ny botten är högre än den förra, en Higher Low, då är trenden uppåt. Köparna styr.": "في كل مرة ينعكس فيها السعر تتشكل قمة أو قاع. عندما تكون كل قمة جديدة أعلى من السابقة، أي Higher High، وكل قاع جديد أعلى من السابق، أي Higher Low، يكون الاتجاه صاعدًا. المشترون هم المسيطرون.", "Titta på stället där priset går över den förra toppen. Det kallas Break of Structure, förkortat BOS. Ett BOS i trendens riktning är ett tecken på att trenden fortsätter. Köparna orkade ta sig förbi säljarna som väntade vid den gamla toppen.": "انظر إلى المكان الذي يتجاوز فيه السعر القمة السابقة. يُسمى هذا كسر البنية، أو BOS. وجود BOS في اتجاه الترند علامة على استمراره. لقد تمكن المشترون من تجاوز البائعين الذين كانوا ينتظرون عند القمة القديمة.", "Trenden fortsätter: ny högre botten, nytt BOS, ny högre topp. Så länge det här mönstret håller är det oftast klokare att leta efter köp än att försöka gissa var toppen kommer. Att handla mot trenden är som att simma mot strömmen.": "يستمر الاتجاه: قاع أعلى جديد، وBOS جديد، وقمة أعلى جديدة. طالما استمر هذا النمط فغالبًا ما يكون البحث عن فرص شراء أحكم من محاولة تخمين مكان القمة. التداول عكس الاتجاه يشبه السباحة عكس التيار.", "Men titta nu. Den nya toppen blev lägre än den förra. Det kallas en Lower High. Köparna orkar inte längre ta priset lika högt. Det är en första varning, men trenden är inte bruten än. Den sista högre botten håller fortfarande.": "لكن انظر الآن. جاءت القمة الجديدة أدنى من السابقة. يُسمى هذا Lower High. لم يعد المشترون قادرين على دفع السعر بالارتفاع نفسه. إنه تحذير أول، لكن الاتجاه لم ينكسر بعد. ما زال آخر قاع أعلى صامدًا.", "Nu bryter priset under den sista högre botten. Det första brottet mot trenden kallas Change of Character, CHoCH, eller Market Structure Shift. Det betyder att säljarna har tagit över, åtminstone för tillfället. Många ICT-traders väntar på just den här signalen.": "الآن يكسر السعر أسفل آخر قاع أعلى. أول كسر عكس الاتجاه يُسمى تغيّر الطابع، CHoCH، أو تحوّل بنية السوق. وهذا يعني أن البائعين سيطروا، على الأقل حاليًا. كثير من متداولي ICT ينتظرون هذه الإشارة بالذات.", "Efter CHoCH ser vi lägre toppar och lägre bottnar. Nu är trenden nedåt, och ett nytt BOS nedåt bekräftar det. Samma regler gäller fast spegelvänt: i en nedåttrend letar man hellre efter blankning eller håller sig borta än köper.": "بعد CHoCH نرى قممًا أدنى وقيعانًا أدنى. الآن أصبح الاتجاه هابطًا، وBOS جديد للأسفل يؤكد ذلك. القواعد نفسها تنطبق لكن معكوسة: في الاتجاه الهابط يُفضّل البحث عن البيع على المكشوف أو البقاء خارج السوق بدل الشراء.", "Ett tips: titta alltid på flera tidsramar. Trenden på dagsgrafen är den stora bilden. Trenden på femminutersgrafen är bara en våg i den. Många börjar med en högre tidsram för riktningen och går ner till en lägre för att hitta exakt var de ska gå in.": "نصيحة: انظر دائمًا إلى عدة أطر زمنية. الاتجاه على الرسم اليومي هو الصورة الكبيرة، والاتجاه على رسم الخمس دقائق مجرد موجة داخله. يبدأ كثيرون بإطار زمني أكبر لتحديد الاتجاه ثم ينزلون إلى إطار أصغر ليجدوا بالضبط أين يدخلون.", "Fördjupning: hur vet du att ett BOS är på riktigt? Titta på var ljuset stänger, inte bara på veken. Om en veke sticker över den förra toppen men ljuset stänger under, har strukturen inte brutits. Det är ofta bara ett försök som misslyckades. Ett riktigt BOS är när ett ljus stänger över toppen, gärna med en stor kropp. Samma sak gäller CHoCH åt andra hållet: vänta på en stängning under den sista högre botten. Och välj vilka toppar och bottnar du räknar. Små svängningar inne i en större rörelse räknas inte. Börja med de tydliga vändpunkterna som du ser direkt när du zoomar ut.": "تعمق: كيف تعرف أن كسر الهيكل حقيقي؟ انظر إلى أين تغلق الشمعة، لا إلى الفتيل فقط. إذا تجاوز الفتيل القمة السابقة لكن الشمعة أغلقت تحتها، فالهيكل لم يُكسر. غالبًا ما يكون ذلك مجرد محاولة فاشلة. الكسر الحقيقي هو عندما تغلق شمعة فوق القمة، ويُفضل بجسم كبير. والأمر نفسه ينطبق على تغيّر الطابع في الاتجاه المعاكس: انتظر إغلاقًا تحت آخر قاع أعلى. واختر القمم والقيعان التي تحسبها. التذبذبات الصغيرة داخل حركة أكبر لا تُحسب. ابدأ بنقاط الانعطاف الواضحة التي تراها فورًا عندما تصغّر الرسم.", "Sammanfattning: högre toppar och högre bottnar betyder upptrend. BOS bekräftar att trenden fortsätter. CHoCH är det första tecknet på att den vänder. I nästa video tittar vi på stöd, motstånd och likviditet, alltså varför priset vänder där det vänder.": "الخلاصة: القمم الأعلى والقيعان الأعلى تعني اتجاهًا صاعدًا. BOS يؤكد استمرار الاتجاه. CHoCH أول علامة على الانعكاس. في الفيديو التالي ننظر إلى الدعم والمقاومة والسيولة، أي لماذا ينعكس السعر حيث ينعكس.", "Vad kännetecknar en upptrend?": "ما الذي يميز الاتجاه الصاعد؟", "Högre toppar och högre bottnar": "قمم أعلى وقيعان أعلى", "Lägre toppar och lägre bottnar": "قمم أدنى وقيعان أدنى", "Bara gröna ljus": "شموع خضراء فقط", "Hög volym": "حجم مرتفع", "Vad är ett CHoCH?": "ما هو CHoCH؟", "Första brottet mot trenden": "أول كسر عكس الاتجاه", "Ett brott med trenden": "كسر مع الاتجاه", "En sorts ordertyp": "نوع من الأوامر", "En nyhet": "خبر", "Varför titta på flera tidsramar?": "لماذا تنظر إلى عدة أطر زمنية؟", "Stor bild för riktning, liten för ingång": "صورة كبيرة للاتجاه وصغيرة للدخول", "För att det ser proffsigt ut": "لأنه يبدو احترافيًا", "Det spelar ingen roll": "لا يهم", "För att slippa stop-loss": "لتجنب وقف الخسارة", "Stöd, motstånd och likviditet": "الدعم والمقاومة والسيولة", "Varför priset vänder där det vänder, och stop hunts.": "لماذا ينعكس السعر حيث ينعكس، وصيد أوامر الوقف.", "Ett stöd är en nivå där priset har slutat falla och vänt upp, gärna flera gånger. Varför? För att många köpare minns nivån. De som missade köpet förra gången lägger sina köpordrar där igen. Köptrycket stoppar fallet.": "الدعم مستوى توقف عنده السعر عن الهبوط وارتد للأعلى، ويفضّل أن يتكرر ذلك. لماذا؟ لأن مشترين كثيرين يتذكرون المستوى. ومن فاته الشراء في المرة السابقة يضع أوامر الشراء هناك مجددًا، فيوقف ضغط الشراء الهبوط.", "Motstånd är samma sak fast uppåt. Det är en nivå där priset har slutat stiga. Där väntar säljare: folk som köpte högre och vill komma ut utan förlust, och folk som tycker att priset är för högt. Nu ser vi ett intervall mellan stöd och motstånd.": "المقاومة هي الشيء نفسه لكن للأعلى. إنها مستوى توقف عنده السعر عن الصعود. هناك ينتظر البائعون: من اشتروا أعلى ويريدون الخروج دون خسارة، ومن يرون السعر مرتفعًا جدًا. نرى الآن نطاقًا بين الدعم والمقاومة.", "Titta på topparna. Priset har nuddat samma nivå tre gånger. Det kallas lika toppar, equal highs. För nybörjare ser det ut som ett starkt motstånd. Men proffsen ser något annat: en hög med ordrar som ligger precis ovanför.": "انظر إلى القمم. لمس السعر المستوى نفسه ثلاث مرات. تُسمى هذه القمم المتساوية، equal highs. يراها المبتدئون مقاومة قوية، لكن المحترفين يرون شيئًا آخر: كومة من الأوامر فوقها مباشرة.", "Ovanför lika toppar ligger två sorters ordrar. Stop-loss från dem som blankat vid motståndet, och köpordrar från dem som vill köpa när priset bryter uppåt. Båda blir köp när de utlöses. Det kallas buy-side liquidity, köpsidans likviditet.": "فوق القمم المتساوية نوعان من الأوامر: أوامر وقف الخسارة لمن باعوا على المكشوف عند المقاومة، وأوامر شراء لمن يريدون الشراء عند الاختراق. كلاهما يتحول إلى شراء عند تفعيله. تُسمى هذه سيولة جانب الشراء، buy-side liquidity.", "Och här händer det. Priset sticker upp över topparna och tar likviditeten. Alla stoppar utlöses och nya köpare hoppar på utbrottet. Det ger en stor aktör möjlighet att sälja mycket till alla dessa köpare. Det kallas en liquidity sweep eller stop hunt.": "وهنا يحدث ذلك. يقفز السعر فوق القمم ويأخذ السيولة. تتفعل كل أوامر الوقف ويقفز مشترون جدد على الاختراق. وهذا يمنح لاعبًا كبيرًا فرصة لبيع كمية كبيرة لكل هؤلاء المشترين. يُسمى هذا سحب السيولة أو صيد أوامر الوقف.", "Direkt efteråt faller priset tillbaka in i intervallet. Utbrottet var falskt. De som köpte på toppen sitter nu med förlust. Lärdom: ett utbrott över en uppenbar nivå är inte automatiskt en köpsignal. Vänta och se om priset stannar ovanför.": "مباشرة بعد ذلك يعود السعر إلى داخل النطاق. كان الاختراق كاذبًا، ومن اشترى عند القمة خاسر الآن. الدرس: الاختراق فوق مستوى واضح ليس تلقائيًا إشارة شراء. انتظر لترى إن كان السعر سيبقى فوقه.", "Samma sak finns under bottnar. Under stödet ligger stoppar från köpare och säljordrar från dem som vill sälja vid ett brott. Det kallas sell-side liquidity. Efter att ha tagit toppen söker priset sig nu ner och tar likviditeten under stödet också.": "الأمر نفسه موجود تحت القيعان. تحت الدعم توجد أوامر وقف المشترين وأوامر بيع لمن يريدون البيع عند الكسر. تُسمى هذه سيولة جانب البيع، sell-side liquidity. وبعد أن أخذ القمة، يتجه السعر الآن للأسفل ويأخذ السيولة تحت الدعم أيضًا.", "Vad betyder det för dig? Lägg inte din stop-loss precis där alla andra lägger sin, exakt vid en uppenbar topp eller botten. Ge den lite luft. Och köp inte utbrott blint. Fråga dig: tar priset bara likviditet, eller bryter det på riktigt?": "ماذا يعني هذا لك؟ لا تضع وقف الخسارة بالضبط حيث يضعه الجميع، عند قمة أو قاع واضح تمامًا. أعطه مساحة. ولا تشترِ الاختراقات بشكل أعمى. اسأل نفسك: هل يأخذ السعر السيولة فقط، أم يخترق فعلًا؟", "Fördjupning: rita zoner, inte tunna linjer. Priset vänder sällan på exakt samma öre. Om bottnarna ligger på 103,80, 104,10 och 104,30 är stödet zonen 103,80 till 104,30, inte en linje på 104. Ju fler gånger priset testar en nivå, desto färre köpare finns kvar där, eftersom deras ordrar redan har fyllts. Därför bryts en nivå ofta på det fjärde eller femte testet. Och när ett stöd väl bryts byter det ofta roll. De som köpte där sitter med förlust och vill sälja när priset kommer tillbaka upp. Då blir det gamla stödet ett nytt motstånd.": "تعمق: ارسم مناطق لا خطوطًا رفيعة. نادرًا ما ينعكس السعر عند السنت نفسه تمامًا. إذا كانت القيعان عند 103.80 و104.10 و104.30، فالدعم هو المنطقة من 103.80 إلى 104.30، لا خط عند 104. كلما اختبر السعر مستوى ما مرات أكثر قلّ عدد المشترين الباقين هناك، لأن أوامرهم نُفذت بالفعل. لهذا ينكسر المستوى غالبًا في الاختبار الرابع أو الخامس. وعندما ينكسر الدعم يتبدل دوره غالبًا. من اشتروا هناك يجلسون على خسارة ويريدون البيع عندما يعود السعر للأعلى. عندها يصبح الدعم القديم مقاومة جديدة.", "Sammanfattning: stöd och motstånd är nivåer där många ordrar ligger. Lika toppar och bottnar drar till sig likviditet, och priset sveper ofta förbi dem innan det vänder. I nästa video lär du dig två ICT-begrepp som många pratar om: order blocks och fair value gaps.": "الخلاصة: الدعم والمقاومة مستويات تتجمع عندها أوامر كثيرة. القمم والقيعان المتساوية تجذب السيولة، وغالبًا ما يتجاوزها السعر قبل أن ينعكس. في الفيديو التالي ستتعلم مفهومين من ICT يتحدث عنهما كثيرون: order blocks وfair value gaps.", "Vad ligger ofta strax över lika toppar?": "ما الذي يوجد غالبًا فوق القمم المتساوية مباشرة؟", "Stop-loss och köpordrar": "أوامر وقف خسارة وأوامر شراء", "Ingenting": "لا شيء", "Utdelningar": "توزيعات أرباح", "Bara säljordrar från banken": "أوامر بيع البنك فقط", "Vad är en stop hunt?": "ما صيد أوامر الوقف؟", "När priset sveper förbi en nivå och tar stopparna": "عندما يتجاوز السعر مستوى ويأخذ أوامر الوقف", "När du flyttar din stop-loss": "عندما تحرك وقف خسارتك", "En ny sorts aktie": "نوع جديد من الأسهم", "En skattefri vinst": "ربح معفى من الضريبة", "Var är det oklokt att lägga sin stop-loss?": "أين من غير الحكمة وضع وقف الخسارة؟", "Exakt vid en uppenbar topp eller botten": "بالضبط عند قمة أو قاع واضح", "Med lite luft bortom nivån": "مع بعض المساحة بعد المستوى", "Där idén är fel": "حيث تصبح الفكرة خاطئة", "Enligt din plan": "وفق خطتك", "Order blocks och fair value gaps": "Order blocks وFair value gaps", "Två ICT-begrepp, förklarade ärligt.": "مفهومان من ICT بشرح صادق.", "ICT står för Inner Circle Trader. Det är ett sätt att läsa grafer som blivit väldigt populärt på YouTube och TikTok. Två av de mest kända begreppen är order blocks och fair value gaps. Jag förklarar båda, och jag är ärlig med var de fungerar och var de inte gör det.": "ICT اختصار لـ Inner Circle Trader. إنها طريقة لقراءة الرسوم أصبحت شائعة جدًا على يوتيوب وتيك توك. ومن أشهر مفاهيمها order blocks وfair value gaps. سأشرح الاثنين، وسأكون صادقًا بشأن متى ينجحان ومتى لا.", "Titta på det här kraftiga lyftet. Priset rusar uppåt i flera stora gröna ljus och bryter strukturen. En sådan rörelse brukar kallas en impuls eller displacement. Den visar att någon stor köpte mycket och snabbt.": "انظر إلى هذا الصعود القوي. يندفع السعر للأعلى في عدة شموع خضراء كبيرة ويكسر البنية. تُسمى هذه الحركة غالبًا الاندفاع أو displacement. وهي تُظهر أن لاعبًا كبيرًا اشترى كثيرًا وبسرعة.", "Ett order block är det sista röda ljuset innan en sådan impuls uppåt. Tanken är att stora aktörer byggde sin position där, och att det kan ligga kvar ordrar på den nivån. Därför tror många att priset kan reagera om det kommer tillbaka dit.": "الـ order block هو آخر شمعة حمراء قبل مثل هذا الاندفاع الصاعد. الفكرة أن اللاعبين الكبار بنوا مراكزهم هناك، وقد تبقى أوامر عند ذلك المستوى. لهذا يعتقد كثيرون أن السعر قد يتفاعل إذا عاد إليه.", "Ett fair value gap ser du med tre ljus i rad. Om det första ljusets topp och det tredje ljusets botten inte överlappar finns det ett glapp mellan dem. Där handlades nästan ingenting, priset bara flög förbi. Det kallas också imbalance, obalans.": "تكتشف الـ fair value gap من ثلاث شموع متتالية. إذا لم تتداخل قمة الشمعة الأولى مع قاع الشمعة الثالثة فهناك فجوة بينهما. لم يُتداول هناك شيء تقريبًا، بل عبر السعر بسرعة. ويُسمى أيضًا عدم التوازن، imbalance.", "Efter impulsen tappar priset fart och börjar falla tillbaka. Det är helt normalt. Ingen trend går rakt upp. Frågan som ICT-traders ställer sig är: var kommer köparna in igen? Svaret de letar efter är ofta i fair value gapet eller i order blocket.": "بعد الاندفاع يفقد السعر زخمه ويبدأ بالتراجع. هذا طبيعي تمامًا، فلا اتجاه يصعد بخط مستقيم. السؤال الذي يطرحه متداولو ICT: أين سيعود المشترون؟ والجواب الذي يبحثون عنه غالبًا في الـ fair value gap أو الـ order block.", "Här kommer priset tillbaka ner in i gapet och vänder upp igen. Det kallas att gapet fylls eller att priset balanserar obalansen. För den som väntade på det här stället kunde det vara en bra plats att köpa, med stoppen under zonen.": "هنا يعود السعر للأسفل إلى داخل الفجوة ثم يرتد صعودًا. يُسمى هذا ملء الفجوة، أو إعادة التوازن. لمن كان ينتظر عند هذا المكان، ربما كان موضعًا جيدًا للشراء مع وضع الوقف أسفل المنطقة.", "Och priset fortsätter upp. Lägg märke till att det vände i gapet och aldrig nådde ner till order blocket. Det händer ofta. Därför ser många zonerna som områden, inte exakta linjer, och använder order blocket som en sista gräns där idén är fel om priset går under.": "ويستمر السعر في الصعود. لاحظ أنه انعكس داخل الفجوة ولم يصل أبدًا إلى الـ order block. يحدث هذا كثيرًا. لذلك يرى كثيرون المناطق كمساحات لا كخطوط دقيقة، ويستخدمون الـ order block كحد أخير: إذا نزل السعر تحته فالفكرة خاطئة.", "Nu den ärliga delen. Order blocks och fair value gaps är populära, men det finns inga starka bevis för att de fungerar bättre än andra metoder. Ibland respekterar priset zonerna, ibland skär det rakt igenom. Därför är de ledtrådar, inte löften, och du behöver alltid en stop-loss.": "والآن الجزء الصادق. الـ order blocks والـ fair value gaps شائعة، لكن لا توجد أدلة قوية على أنها أفضل من غيرها. أحيانًا يحترم السعر المناطق، وأحيانًا يخترقها مباشرة. لذلك هي أدلة لا وعود، وتحتاج دائمًا إلى وقف خسارة.", "Fördjupning: så ritar du ett fair value gap exakt. Ta tre ljus i rad under ett kraftigt lyft. Säg att det första ljusets topp är 104,20 och det tredje ljusets botten är 105,00. Mellan 104,20 och 105,00 handlades nästan inget, och det är gapet. Mitten, 104,60, kallas ibland gapets jämvikt, och många tittar extra på den. Är det tredje ljusets botten lägre än det första ljusets topp finns inget gap alls. Ett order block ritar du från det sista röda ljusets botten till dess topp. Kom ihåg: de här zonerna är områden att hålla ögonen på, inte signaler att köpa blint.": "تعمق: كيف ترسم فجوة القيمة العادلة بدقة. خذ ثلاث شموع متتالية أثناء صعود قوي. لنفترض أن قمة الشمعة الأولى 104.20 وقاع الشمعة الثالثة 105.00. بين 104.20 و105.00 لم يُتداول شيء تقريبًا، وهذه هي الفجوة. المنتصف 104.60 يُسمى أحيانًا توازن الفجوة، ويراقبه كثيرون. إذا كان قاع الشمعة الثالثة أدنى من قمة الأولى فلا توجد فجوة أصلًا. ترسم كتلة الأوامر من قاع آخر شمعة حمراء إلى قمتها. تذكّر: هذه المناطق للمراقبة، لا إشارات للشراء الأعمى.", "Sammanfattning: ett order block är sista motsatta ljuset före en stark impuls. Ett fair value gap är ett glapp mellan ljus ett och tre. Båda är zoner där priset ibland reagerar. I nästa video sätter vi ihop allt: när ska man köpa och när ska man sälja?": "الخلاصة: الـ order block هو آخر شمعة معاكسة قبل اندفاع قوي. والـ fair value gap فجوة بين الشمعتين الأولى والثالثة. كلاهما منطقة يتفاعل عندها السعر أحيانًا. في الفيديو التالي نجمع كل شيء: متى تشتري ومتى تبيع؟", "Vad är ett order block i en upptrend?": "ما الـ order block في الاتجاه الصاعد؟", "Sista röda ljuset före en stark impuls uppåt": "آخر شمعة حمراء قبل اندفاع صاعد قوي", "Första gröna ljuset på dagen": "أول شمعة خضراء في اليوم", "En spärrad aktie": "سهم محظور", "Ett stort köp från dig": "شراء كبير منك", "Hur hittar du ett fair value gap?": "كيف تجد fair value gap؟", "Ljus ett och tre överlappar inte": "الشمعتان الأولى والثالثة لا تتداخلان", "Två röda ljus i rad": "شمعتان حمراوان متتاليتان", "Börsen är stängd": "البورصة مغلقة", "Ett ljus utan veke": "شمعة بلا فتيل", "Fungerar order blocks och FVG alltid?": "هل تنجح الـ order blocks والـ FVG دائمًا؟", "Nej, de är ledtrådar och kräver stop-loss": "لا، إنها أدلة وتحتاج إلى وقف خسارة", "Ja, alltid": "نعم، دائمًا", "Ja, om man har många följare": "نعم، إن كان لديك متابعون كثر", "Ja, på fredagar": "نعم، أيام الجمعة", "När ska man köpa och sälja?": "متى تشتري ومتى تبيع؟", "Riktning, zon och bekräftelse, steg för steg.": "الاتجاه والمنطقة والتأكيد خطوة بخطوة.", "Det här är frågan alla vill ha svar på: när ska jag köpa och när ska jag sälja? Det finns inget magiskt svar, men det finns ett sätt att tänka som de flesta seriösa traders använder. Jag kallar det tre steg: riktning, zon och bekräftelse.": "هذا هو السؤال الذي يريد الجميع جوابه: متى أشتري ومتى أبيع؟ لا يوجد جواب سحري، لكن هناك طريقة تفكير يستخدمها معظم المتداولين الجادين. أسميها ثلاث خطوات: الاتجاه، والمنطقة، والتأكيد.", "Steg ett: riktning. Vilket håll går trenden åt? Här ser vi högre toppar och högre bottnar, alltså en upptrend. Då letar vi bara efter köp. Vi försöker inte gissa toppen. Det enklaste sättet att förlora pengar är att slåss mot trenden.": "الخطوة الأولى: الاتجاه. في أي اتجاه يسير الترند؟ هنا نرى قممًا أعلى وقيعانًا أعلى، أي اتجاهًا صاعدًا. لذا نبحث عن الشراء فقط ولا نحاول تخمين القمة. أسهل طريقة لخسارة المال هي محاربة الاتجاه.", "Steg två: zon. Köp inte när priset just har rusat upp, då köper du dyrt. Vänta på en rekyl. Dra en linje mitt i den senaste rörelsen, från botten till toppen. Under mitten är priset billigt, discount. Över mitten är det dyrt, premium. Vi vill köpa i discount.": "الخطوة الثانية: المنطقة. لا تشترِ بعد اندفاع السعر مباشرة، فأنت تشتري غاليًا. انتظر تراجعًا. ارسم خطًا في منتصف الحركة الأخيرة من القاع إلى القمة. تحت المنتصف يكون السعر رخيصًا، discount، وفوقه غاليًا، premium. نريد الشراء في منطقة الـ discount.", "Nu är priset i discount och dessutom vid en nivå som tidigare var motstånd. Gammalt motstånd blir ofta nytt stöd. Det här är en bra zon. Men att priset är i en bra zon räcker inte. Det kan fortsätta falla rakt igenom.": "الآن السعر في منطقة الـ discount وعند مستوى كان مقاومة سابقًا. المقاومة القديمة تصبح غالبًا دعمًا جديدًا. هذه منطقة جيدة، لكن وجود السعر في منطقة جيدة لا يكفي، فقد يواصل الهبوط عبرها.", "Steg tre: bekräftelse. Vänta tills köparna visar att de är tillbaka. Det kan vara ett starkt grönt ljus som stänger högt, en hammare, eller ett litet CHoCH uppåt på en lägre tidsram. Först nu har vi en anledning att köpa.": "الخطوة الثالثة: التأكيد. انتظر حتى يُظهر المشترون أنهم عادوا. قد يكون ذلك شمعة خضراء قوية تغلق مرتفعة، أو مطرقة، أو CHoCH صغيرًا صاعدًا على إطار زمني أصغر. الآن فقط لدينا سبب للشراء.", "Så här ser köpet ut. Ingång strax efter bekräftelsen. Stop-loss under botten i zonen, med lite luft, för om priset går dit var idén fel. Mål vid den gamla toppen, där köpsidans likviditet ligger. Planen är klar innan vi klickar.": "هكذا تبدو صفقة الشراء. الدخول مباشرة بعد التأكيد. وقف الخسارة تحت القاع في المنطقة مع بعض المساحة، لأنه إذا وصل السعر إلى هناك فالفكرة كانت خاطئة. والهدف عند القمة القديمة حيث سيولة جانب الشراء. الخطة جاهزة قبل أن نضغط.", "När ska man sälja? På två ställen som du bestämt i förväg. Antingen når priset målet, och du tar vinsten. Eller så når det stoppen, och du tar en liten förlust. Du säljer inte för att du blir nervös, och du flyttar aldrig ner stoppen.": "متى تبيع؟ في مكانين حددتهما مسبقًا. إما أن يصل السعر إلى الهدف فتأخذ الربح، أو يصل إلى الوقف فتأخذ خسارة صغيرة. لا تبيع لأنك توترت، ولا تنزل الوقف أبدًا.", "Och när ska man inte handla alls? När trenden är otydlig. När priset är mitt i ingenstans, varken i en zon eller vid en nivå. Precis innan stora nyheter. Och när du är trött, arg eller vill vinna tillbaka en förlust. Att avstå är också ett beslut.": "ومتى لا تتداول أصلًا؟ عندما يكون الاتجاه غير واضح. عندما يكون السعر في منتصف اللامكان، لا في منطقة ولا عند مستوى. قبل الأخبار الكبيرة مباشرة. وعندما تكون متعبًا أو غاضبًا أو تريد تعويض خسارة. البقاء خارج السوق قرار أيضًا.", "Fördjupning: så räknar du premium och discount. Ta den senaste rörelsen från botten till toppen. Här gick priset från 103 till 111. Skillnaden är 8 kronor, och mitten ligger 4 kronor upp, på 107. Allt över 107 är premium, dyrt. Allt under 107 är discount, billigt. I en upptrend vill du köpa i discount, helst där det också finns ett gammalt motstånd som kan bli stöd, som här runt 106. Mitten är ingen magisk linje. Den hjälper dig bara att undvika att köpa på toppen av en rörelse. Gör toppen ny behöver du räkna om mitten.": "تعمق: كيف تحسب منطقتي الغلاء والخصم. خذ آخر حركة من القاع إلى القمة. هنا انتقل السعر من 103 إلى 111. الفرق 8 كرونات، والمنتصف أعلى بأربع كرونات عند 107. كل ما فوق 107 منطقة غلاء. وكل ما تحته منطقة خصم رخيصة. في الاتجاه الصاعد تريد الشراء في منطقة الخصم، ويُفضل حيث يمكن لمقاومة قديمة أن تصبح دعمًا، كما هنا قرب 106. المنتصف ليس خطًا سحريًا، بل يساعدك فقط على تجنب الشراء عند قمة الحركة. وإذا تشكلت قمة جديدة فأعد حساب المنتصف.", "Sammanfattning: riktning först, sedan en bra zon, sedan bekräftelse. Bestäm ingång, stopp och mål innan du klickar. Sälj vid målet eller stoppen, inte på känsla. I nästa video räknar vi på en trade: hur stor ska den vara och vad händer med pengarna?": "الخلاصة: الاتجاه أولًا، ثم منطقة جيدة، ثم التأكيد. حدد الدخول والوقف والهدف قبل أن تضغط. بِع عند الهدف أو الوقف، لا بحسب شعورك. في الفيديو التالي نحسب صفقة: ما حجمها وماذا يحدث للمال؟", "Vilka är de tre stegen?": "ما الخطوات الثلاث؟", "Riktning, zon, bekräftelse": "الاتجاه، المنطقة، التأكيد", "Köp, sälj, köp igen": "اشترِ، بِع، اشترِ مجددًا", "Nyhet, hype, köp": "خبر، ضجيج، شراء", "Gissa, hoppas, vänta": "خمّن، تمنَّ، انتظر", "I en upptrend, var vill man helst köpa?": "في الاتجاه الصاعد، أين يُفضّل الشراء؟", "I discount, efter en rekyl": "في منطقة discount بعد تراجع", "På toppen efter ett rusning": "عند القمة بعد اندفاع", "Var som helst": "في أي مكان", "När någon på TikTok säger det": "عندما يقول ذلك أحد على تيك توك", "När säljer du enligt planen?": "متى تبيع حسب الخطة؟", "Vid målet eller stoppen": "عند الهدف أو الوقف", "När du blir nervös": "عندما تتوتر", "Aldrig": "أبدًا", "När en vän säljer": "عندما يبيع صديق", "Gå in i en trade": "الدخول في صفقة", "Ingång, stopp, mål, risk/belöning och positionsstorlek.": "الدخول والوقف والهدف والمخاطرة إلى العائد وحجم المركز.", "Du har hittat ett läge. Nu kommer delen som avgör om du överlever som trader: hur du går in i traden. De flesta nybörjare tänker bara på var de ska köpa. Proffs tänker först på hur mycket de kan förlora.": "وجدت فرصة. الآن يأتي الجزء الذي يحدد ما إذا كنت ستبقى كمتداول: كيف تدخل الصفقة. معظم المبتدئين يفكرون فقط في مكان الشراء، أما المحترفون فيفكرون أولًا في مقدار ما قد يخسرونه.", "Ingången. Du kan köpa direkt till marknadspris med en marknadsorder. Eller lägga en limitorder på det pris du vill ha och vänta. Limit ger bättre pris men du kan missa traden. Här köper vi på 105 kronor när bekräftelsen kommer.": "الدخول. يمكنك الشراء فورًا بسعر السوق بأمر سوق، أو وضع أمر محدد بالسعر الذي تريده والانتظار. الأمر المحدد يعطي سعرًا أفضل لكن قد تفوتك الصفقة. هنا نشتري بـ 105 كرونة عند ظهور التأكيد.", "Stop-lossen. Den ska ligga där din idé är fel, inte där det känns bekvämt. Vår idé är att stödet håller. Om priset går under botten vid 103,60 har vi fel. Vi lägger stoppen på 103 kronor, med lite luft. Risken per aktie blir 2 kronor.": "وقف الخسارة. يجب أن يكون حيث تصبح فكرتك خاطئة، لا حيث تشعر بالراحة. فكرتنا أن الدعم سيصمد. إذا نزل السعر تحت القاع عند 103,60 فنحن مخطئون. نضع الوقف عند 103 كرونة مع بعض المساحة. المخاطرة لكل سهم كرونتان.", "Målet. Vi siktar på 109 kronor, strax under den gamla toppen. Vinsten per aktie blir då 4 kronor. Vi riskerar alltså 2 för att kunna tjäna 4. Det kallas risk/belöning ett till två. Med ett till två kan du ha fel oftare än rätt och ändå gå plus.": "الهدف. نستهدف 109 كرونة، أسفل القمة القديمة مباشرة. يصبح الربح لكل سهم 4 كرونات. نخاطر إذن بـ 2 لنربح 4. يُسمى هذا نسبة المخاطرة إلى العائد واحد إلى اثنين. بهذه النسبة يمكن أن تخطئ أكثر مما تصيب وتبقى رابحًا.", "Räkna så här. Tio trades med ett till två. Du har rätt fyra gånger och fel sex gånger. Fyra vinster gånger 4 kronor blir 16. Sex förluster gånger 2 kronor blir 12. Du har ändå tjänat 4 kronor per aktie, trots att du hade fel oftast.": "احسبها هكذا. عشر صفقات بنسبة واحد إلى اثنين. تصيب أربع مرات وتخطئ ست مرات. أربعة أرباح ضرب 4 كرونات تساوي 16، وست خسائر ضرب كرونتين تساوي 12. ما زلت ربحت 4 كرونات لكل سهم رغم أنك أخطأت في أغلب المرات.", "Positionsstorlek. Bestäm hur mycket av kontot du får förlora på en trade, till exempel 1 procent. Har du 10 000 kronor är det 100 kronor. Risken per aktie är 2 kronor. 100 delat med 2 blir 50 aktier. Det är hela regeln: risk i kronor delat med risk per aktie.": "حجم المركز. حدد كم من حسابك يُسمح لك بخسارته في صفقة واحدة، مثلًا 1 بالمئة. إذا كان لديك 10 000 كرونة فهذا 100 كرونة. المخاطرة لكل سهم كرونتان. 100 مقسومة على 2 تساوي 50 سهمًا. هذه هي القاعدة كلها: المخاطرة بالكرونة مقسومة على المخاطرة لكل سهم.", "Och traden går vår väg. Priset når målet och vi säljer 50 aktier med 4 kronors vinst, alltså 200 kronor. Om stoppen hade slagits ut hade vi förlorat 100 kronor, bara 1 procent av kontot. Med den regeln kan du ha flera förluster i rad utan att kontot försvinner.": "وتسير الصفقة لصالحنا. يصل السعر إلى الهدف فنبيع 50 سهمًا بربح 4 كرونات لكل سهم، أي 200 كرونة. لو ضُرب الوقف لخسرنا 100 كرونة فقط، أي 1 بالمئة من الحساب. بهذه القاعدة يمكنك تحمّل عدة خسائر متتالية دون أن يختفي حسابك.", "Fördjupning: positionsstorlek steg för steg. Ditt konto är 10 000 kronor och du riskerar 1 procent, alltså 100 kronor. Ingången är 105 och stoppen 103, så avståndet är 2 kronor per aktie. 100 delat med 2 är 50. Du köper alltså 50 aktier, värda 5 250 kronor. Om stoppen slås ut förlorar du 100 kronor plus courtage, inte mer. Lägg märke till att det är stoppens avstånd som bestämmer antalet aktier, inte hur säker du känner dig. Ligger stoppen längre bort köper du färre aktier, så att risken i kronor blir densamma varje gång.": "تعمق: حجم الصفقة خطوة بخطوة. حسابك 10 آلاف كرونة وتخاطر بواحد في المئة، أي 100 كرونة. الدخول عند 105 والوقف عند 103، فالمسافة كرونتان لكل سهم. 100 مقسومة على 2 تساوي 50. إذن تشتري 50 سهمًا بقيمة 5250 كرونة. إذا ضُرب الوقف تخسر 100 كرونة زائد العمولة، لا أكثر. لاحظ أن مسافة الوقف هي التي تحدد عدد الأسهم، لا مدى ثقتك. إذا كان الوقف أبعد تشتري أسهمًا أقل، لتبقى المخاطرة بالكرونات نفسها في كل مرة.", "Sammanfattning: stoppen ligger där idén är fel. Målet ger minst dubbelt så mycket som risken. Positionsstorleken räknar du fram så att en förlust bara kostar 1 procent. I sista videon följer vi två hela trades från början till slut, en vinst och en förlust.": "الخلاصة: الوقف يوضع حيث تصبح الفكرة خاطئة. والهدف يعطي ضعف المخاطرة على الأقل. وتحسب حجم المركز بحيث لا تكلفك الخسارة إلا 1 بالمئة. في الفيديو الأخير نتابع صفقتين كاملتين من البداية إلى النهاية، واحدة رابحة وأخرى خاسرة.", "Ingång 105, stopp 103, mål 109. Vad är risk/belöning?": "الدخول 105 والوقف 103 والهدف 109. ما نسبة المخاطرة إلى العائد؟", "1 till 2": "1 إلى 2", "1 till 1": "1 إلى 1", "2 till 1": "2 إلى 1", "1 till 4": "1 إلى 4", "Konto 10 000 kr, risk 1 %, risk per aktie 2 kr. Hur många aktier?": "الحساب 10 000 كرونة، المخاطرة 1٪، المخاطرة لكل سهم 2 كرونة. كم سهمًا؟", "50": "50", "100": "100", "10": "10", "500": "500", "Var ska stop-lossen ligga?": "أين يجب وضع وقف الخسارة؟", "Där det känns bekvämt": "حيث تشعر بالراحة", "Ingenstans": "لا مكان", "Precis på köppriset": "عند سعر الشراء بالضبط", "En hel trade från början till slut": "صفقة كاملة من البداية إلى النهاية", "En vinst, en förlust och vad du lär dig av båda.": "ربح وخسارة وما تتعلمه من كليهما.", "I den här sista videon gör vi allt i ordning, som en riktig trader. Först riktningen. Dagsgrafen visar högre toppar och högre bottnar. Trenden är upp, så vi letar bara efter köp. Vi skriver ner det i tradingdagboken innan vi gör något annat.": "في هذا الفيديو الأخير نفعل كل شيء بالترتيب كمتداول حقيقي. أولًا الاتجاه. الرسم اليومي يُظهر قممًا أعلى وقيعانًا أعلى. الاتجاه صاعد، لذا نبحث عن الشراء فقط. ونكتب ذلك في مفكرة التداول قبل أي شيء آخر.", "Sedan zonen. Priset rekylerar ner i discount, under mitten av den senaste rörelsen, och når området runt 105 där det tidigare var motstånd. Vi gör ingenting än. Vi väntar på att köparna ska visa sig.": "ثم المنطقة. يتراجع السعر إلى منطقة الـ discount تحت منتصف الحركة الأخيرة، ويصل إلى المنطقة حول 105 التي كانت مقاومة سابقًا. لا نفعل شيئًا بعد، بل ننتظر ظهور المشترين.", "Bekräftelse: två starka gröna ljus. Nu planerar vi. Ingång 106,60. Stopp 104,60 under botten. Mål 110,80 vid den gamla toppen. Risk 2 kronor, möjlig vinst drygt 4. Kontot är 10 000 kronor och vi riskerar 1 procent, alltså 50 aktier.": "التأكيد: شمعتان خضراوان قويتان. الآن نخطط. الدخول 106,60. الوقف 104,60 تحت القاع. الهدف 110,80 عند القمة القديمة. المخاطرة كرونتان، والربح المحتمل أكثر من 4 بقليل. الحساب 10 000 كرونة ونخاطر بـ 1 بالمئة، أي 50 سهمًا.", "Priset stiger och når målet. Vi säljer och tar vinsten, ungefär 210 kronor. Vi flyttade inte målet för att det kändes som att det kunde gå högre. Planen sa sälj, så vi sålde. Det låter tråkigt, men det är så man håller sig vid liv länge.": "يرتفع السعر ويصل إلى الهدف. نبيع ونأخذ الربح، نحو 210 كرونات. لم نحرك الهدف لأننا شعرنا أنه قد يرتفع أكثر. الخطة قالت بِع، فبعنا. يبدو ذلك مملًا، لكن هكذا تبقى في السوق طويلًا.", "Nu en andra trade. Priset faller tillbaka till ungefär 110, den gamla toppen. Vi tror att den blir stöd. Ingång 110,60, stopp 109,40, mål 113. Lägg märke till att bekräftelsen var svagare den här gången. Det är vanligt att man ändå går in.": "الآن صفقة ثانية. يعود السعر إلى نحو 110، القمة القديمة. نعتقد أنها ستصبح دعمًا. الدخول 110,60 والوقف 109,40 والهدف 113. لاحظ أن التأكيد كان أضعف هذه المرة. من الشائع أن يدخل المرء رغم ذلك.", "Priset faller rakt igenom stödet och slår ut stoppen. Vi förlorar 100 kronor, exakt 1 procent som planerat. Det gör ont, men det är en liten skada. Om vi inte hade haft en stopp hade priset tagit med sig mycket mer.": "يهبط السعر مباشرة عبر الدعم ويضرب الوقف. نخسر 100 كرونة، أي 1 بالمئة بالضبط كما خططنا. يؤلم ذلك، لكنه ضرر صغير. لولا الوقف لأخذ السعر معه أكثر بكثير.", "Titta vad som hände sen. Priset fortsatte ner mot 104. Strukturen gav en varning: en lägre topp och sedan ett brott under den sista högre botten, ett CHoCH. Det här är vad dagboken är till för. Vi skriver: gick in trots svag bekräftelse och en lägre topp.": "انظر ماذا حدث بعد ذلك. واصل السعر الهبوط نحو 104. أعطت البنية تحذيرًا: قمة أدنى ثم كسر تحت آخر قاع أعلى، أي CHoCH. لهذا وُجدت المفكرة. نكتب: دخلت رغم تأكيد ضعيف وقمة أدنى.", "Resultat: en vinst på 210 och en förlust på 100. Totalt plus 110 kronor, trots att hälften av traderna var fel. Det är så trading fungerar: inte att ha rätt hela tiden, utan att förlora lite när man har fel och vinna mer när man har rätt.": "النتيجة: ربح 210 وخسارة 100. المجموع زائد 110 كرونات رغم أن نصف الصفقات كانت خاطئة. هكذا يعمل التداول: ليس أن تكون محقًا دائمًا، بل أن تخسر قليلًا حين تخطئ وتربح أكثر حين تصيب.", "Fördjupning: skriv en tradingdagbok. Efter varje trade antecknar du fem saker. Ett: varför du gick in, med en mening. Två: ingång, stopp och mål. Tre: resultatet i kronor och i R, alltså hur många gånger risken du vann eller förlorade. Vår första trade blev ungefär plus 2 R, den andra minus 1 R. Fyra: följde du planen, ja eller nej? Fem: hur kändes det? Efter tjugo trades läser du dagboken. Då ser du mönster du aldrig märker i stunden, till exempel att dina förluster nästan alltid kommer när du bröt mot planen.": "تعمق: احتفظ بمفكرة تداول. بعد كل صفقة دوّن خمسة أشياء. أولًا: لماذا دخلت، في جملة واحدة. ثانيًا: الدخول والوقف والهدف. ثالثًا: النتيجة بالكرونات وبوحدة R، أي كم مرة من مخاطرتك ربحت أو خسرت. صفقتنا الأولى كانت نحو زائد 2R، والثانية ناقص 1R. رابعًا: هل التزمت بالخطة، نعم أم لا؟ خامسًا: بماذا شعرت؟ بعد عشرين صفقة اقرأ المفكرة. سترى أنماطًا لا تلاحظها في اللحظة، مثلًا أن خسائرك تأتي غالبًا عندما خالفت الخطة.", "Till sist, ärligt: de flesta som daytradar förlorar pengar, särskilt med hävstång. Öva därför först i Wickis handelssimulator med låtsaspengar. Skriv dagbok. Använd bara pengar du har råd att förlora. Och kom ihåg: Wicki lär ut kunskap, inte investeringsråd. Lycka till, och vi ses i nästa lektion!": "أخيرًا، بصدق: معظم من يتداولون يوميًا يخسرون المال، خاصة مع الرافعة المالية. لذا تدرب أولًا في محاكي التداول في Wicki بأموال افتراضية. اكتب مفكرتك. لا تستخدم إلا مالًا تستطيع تحمّل خسارته. وتذكر: Wicki يعلّم المعرفة لا النصائح الاستثمارية. بالتوفيق، ونراك في الدرس التالي!", "En vinst på 210 kr och en förlust på 100 kr. Vad blir resultatet?": "ربح 210 كرونة وخسارة 100 كرونة. ما النتيجة؟", "+110 kr": "‎+110 كرونة", "−110 kr": "‎−110 كرونة", "+310 kr": "‎+310 كرونة", "0 kr": "0 كرونة", "Vad var varningen före den förlorande traden?": "ما التحذير قبل الصفقة الخاسرة؟", "En lägre topp och svag bekräftelse": "قمة أدنى وتأكيد ضعيف", "Ett starkt grönt ljus": "شمعة خضراء قوية", "En högre botten": "قاع أعلى", "Var är det klokt att öva först?": "أين من الحكمة أن تتدرب أولًا؟", "I en simulator med låtsaspengar": "في محاكٍ بأموال افتراضية", "Med lånade pengar": "بمال مقترض", "Med hela sparkontot": "بكل مدخراتك", "Med hävstång": "بالرافعة المالية", "Vanliga nybörjarmisstag": "أخطاء المبتدئين الشائعة", "FOMO, ingen stopp, hämndtrading och för stora positioner.": "FOMO، وغياب الوقف، والتداول الانتقامي، والمراكز الكبيرة جدًا.", "Den här bonusvideon handlar om misstagen nästan alla nybörjare gör. De flesta förlorar inte pengar för att de inte kan läsa en graf. De förlorar för att de bryter sina egna regler när känslorna tar över. Låt oss gå igenom de vanligaste, så att du känner igen dem.": "يتناول هذا الفيديو الإضافي الأخطاء التي يقع فيها تقريبًا كل المبتدئين. معظم الناس لا يخسرون لأنهم لا يجيدون قراءة الرسم، بل لأنهم يكسرون قواعدهم حين تسيطر المشاعر. لنستعرض أكثرها شيوعًا كي تتعرف عليها.", "Misstag ett: att jaga priset. Aktien har stigit i flera dagar, alla pratar om den och du är rädd att missa. Du köper på toppen, efter att rörelsen redan har hänt. Det är FOMO, och det är ofta precis där de tidiga köparna säljer till dig.": "الخطأ الأول: مطاردة السعر. السهم يرتفع منذ أيام، والجميع يتحدث عنه، وتخشى أن يفوتك. فتشتري عند القمة بعد أن حدثت الحركة بالفعل. هذا هو FOMO، وغالبًا ما يكون هذا هو المكان الذي يبيع لك فيه المشترون الأوائل.", "Misstag två: ingen stop-loss. Priset faller och du tänker att det kommer tillbaka. Det faller mer. Nu är förlusten så stor att det känns omöjligt att sälja. Utan stopp kan en liten förlust växa till en stor. Bestäm alltid stoppen innan du köper.": "الخطأ الثاني: لا وقف خسارة. يهبط السعر فتظن أنه سيعود. يهبط أكثر. الآن الخسارة كبيرة لدرجة أن البيع يبدو مستحيلًا. بدون وقف قد تكبر الخسارة الصغيرة لتصبح كبيرة. حدد الوقف دائمًا قبل الشراء.", "Misstag tre: att flytta stoppen. Priset närmar sig din stopp och du flyttar ner den lite, sedan lite till. Det är samma sak som att inte ha någon stopp alls. Stoppen var planen när du var lugn. Lita på den, inte på känslan i stunden.": "الخطأ الثالث: تحريك الوقف. يقترب السعر من الوقف فتنزله قليلًا، ثم قليلًا آخر. هذا يعادل عدم وجود وقف أصلًا. الوقف كان خطتك حين كنت هادئًا، فثق به لا بشعور اللحظة.", "Misstag fyra: hämndtrading. Efter en förlust vill du vinna tillbaka pengarna direkt. Du tar nästa trade utan ett riktigt läge, kanske med dubbelt så stor position. Det slutar ofta med en ännu större förlust. Efter två förluster i rad: ta en paus.": "الخطأ الرابع: التداول الانتقامي. بعد الخسارة تريد استعادة المال فورًا. تأخذ الصفقة التالية دون فرصة حقيقية، وربما بضعف حجم المركز. وغالبًا ينتهي ذلك بخسارة أكبر. بعد خسارتين متتاليتين: خذ استراحة.", "Misstag fem: för stora positioner. Om du riskerar 20 procent av kontot på en trade räcker det med fem förluster för att allt är borta. Med 1 procent kan du ha tjugo förluster i rad och fortfarande ha det mesta kvar. Små positioner håller dig kvar i spelet.": "الخطأ الخامس: مراكز كبيرة جدًا. إذا خاطرت بـ 20 بالمئة من الحساب في صفقة واحدة فخمس خسائر تكفي لتضيع كل شيء. ومع 1 بالمئة يمكنك تحمّل عشرين خسارة متتالية ويبقى معظم المال. المراكز الصغيرة تبقيك في اللعبة.", "Misstag sex: att handla för ofta. Det finns inte ett bra läge varje timme. Varje affär kostar courtage och varje snabbt beslut ökar risken för fel. De bästa traders väntar mycket och handlar lite. Tålamod är en del av strategin.": "الخطأ السادس: التداول بكثرة. لا توجد فرصة جيدة كل ساعة. كل صفقة تكلف عمولة وكل قرار سريع يزيد احتمال الخطأ. أفضل المتداولين ينتظرون كثيرًا ويتداولون قليلًا. الصبر جزء من الاستراتيجية.", "Misstag sju: att tro på den som säljer drömmen. Kurser och signalgrupper som lovar snabba, säkra vinster tjänar oftast mer på dig än på trading. Ingen seriös person lovar säker vinst. Lär dig grunderna själv, som du gör nu, och var skeptisk.": "الخطأ السابع: تصديق من يبيع الحلم. الدورات ومجموعات الإشارات التي تعد بأرباح سريعة ومضمونة تكسب منك غالبًا أكثر مما تكسب من التداول. لا يعد أي شخص جاد بربح مضمون. تعلّم الأساسيات بنفسك كما تفعل الآن، وكن متشككًا.", "Fördjupning: en checklista före varje trade. Läs den högt innan du klickar. Ett: vilken är trenden på den högre tidsramen? Två: är priset i en zon jag planerat, eller jagar jag? Tre: har jag sett en bekräftelse? Fyra: var ligger stoppen, och är den där idén är fel? Fem: är målet minst dubbelt så långt bort som stoppen? Sex: hur många aktier ger 1 procents risk? Sju: är jag lugn, eller vill jag vinna tillbaka något? Om svaret på någon fråga är fel eller osäkert, låt bli. Det kostar ingenting att avstå från en trade.": "تعمق: قائمة تحقق قبل كل صفقة. اقرأها بصوت عالٍ قبل أن تنقر. أولًا: ما الاتجاه على الإطار الزمني الأعلى؟ ثانيًا: هل السعر في منطقة خططت لها، أم أنني أطارده؟ ثالثًا: هل رأيت تأكيدًا؟ رابعًا: أين الوقف، وهل هو حيث تكون الفكرة خاطئة؟ خامسًا: هل الهدف أبعد من الوقف بمرتين على الأقل؟ سادسًا: كم سهمًا يعطي مخاطرة 1%؟ سابعًا: هل أنا هادئ، أم أريد استعادة شيء خسرته؟ إذا كانت أي إجابة خاطئة أو غير مؤكدة فتجاوز الصفقة. الامتناع عن صفقة لا يكلّف شيئًا.", "Sammanfattning: köp inte på FOMO, ha alltid en stopp och flytta den inte, ta paus efter förluster, riskera lite per trade, handla mindre och var skeptisk mot drömförsäljare. Om du undviker de här sju misstagen ligger du redan före de flesta nybörjare.": "الخلاصة: لا تشترِ بدافع FOMO، وضع وقفًا دائمًا ولا تحركه، وخذ استراحة بعد الخسائر، وخاطر بالقليل في كل صفقة، وتداول أقل، وكن متشككًا في بائعي الأحلام. إذا تجنبت هذه الأخطاء السبعة فأنت متقدم على معظم المبتدئين.", "Vad är FOMO i trading?": "ما FOMO في التداول؟", "Att köpa sent av rädsla att missa": "الشراء متأخرًا خوفًا من التفويت", "En säker strategi": "استراتيجية آمنة", "En typ av order": "نوع من الأوامر", "Att ta en paus": "أخذ استراحة", "Vad bör du göra efter två förluster i rad?": "ماذا تفعل بعد خسارتين متتاليتين؟", "Ta en paus": "خذ استراحة", "Dubbla positionen": "ضاعف المركز", "Ta bort stoppen": "أزل الوقف", "Köpa en kurs": "اشترِ دورة", "Hur många förluster i rad tål du med 20 % risk per trade?": "كم خسارة متتالية تتحمل بمخاطرة 20٪ لكل صفقة؟", "Ungefär fem": "نحو خمس", "Hundra": "مئة", "Tjugo": "عشرون", "Oändligt många": "عدد لا نهائي", "Köpare": "المشترون", "Säljare": "البائعون", "Animerad graf": "رسم متحرك", "Videoskolan": "مدرسة الفيديو", "Se trading förklaras på grafen, med röst.": "شاهد شرح التداول على الرسم البياني مع صوت.", "klara": "مكتملة", "Video": "فيديو", "Rösten är datorgenererad och läser på ditt språk.": "الصوت مولّد بالحاسوب ويقرأ بلغتك.", "Testa dig själv · 3 frågor": "اختبر نفسك · 3 أسئلة", "Nästa video:": "الفيديو التالي:", "Föregående": "السابق", "Spela upp": "تشغيل", "Nästa": "التالي", "Ljud": "الصوت", "8 videor om varför priset rör sig, när man köper och säljer.": "8 فيديوهات عن سبب تحرك السعر ومتى تشتري وتبيع.", "Fortsätt titta": "تابع المشاهدة", "Jag vill lära mig trading": "أريد تعلّم التداول", "Börja med videor om hur priset rör sig": "ابدأ بفيديوهات عن حركة السعر", "min": "دقيقة"}};
